def _classify_callback_log_line(line: str) -> tuple[str, str, str]:
    """Classify receiver/HID log lines into callback event, severity, and category."""
    lower = line.lower()
    if any(token in lower for token in ("error", "exception", "traceback", "denied", "crash")):
        severity = "error"
    elif any(token in lower for token in ("fail", "failed", "timeout", "black screen", "no frame")):
        severity = "fail"
    elif any(token in lower for token in ("warn", "warning", "retry", "reconnect", "dropped", "unstable")):
        severity = "warn"
    else:
        severity = "info"

    if any(token in lower for token in ("hid", "mouse", "keyboard", "ch9329", "serial", "baud")):
        return "hid_log", severity, "hid"
    if any(token in lower for token in ("capture", "screenshot", "frame", "black screen", "encoder", "decoder")):
        return "capture_log", severity, "capture"
    if any(token in lower for token in ("airplay", "bonjour", "raop", "mirror", "screen mirroring", "receiver")):
        return "airplay_log", severity, "airplay_stream"
    if any(token in lower for token in ("usb", "iphone", "ios", "udid", "device")):
        return "device_log", severity, "device"
    if severity in {"error", "fail"}:
        return "receiver_error", severity, "uncategorized"
    return "receiver_log", severity, "uncategorized"


def callback_log_events_from_text(
    text: str,
    *,
    device_id: str = "",
    source: str = "receiver_log",
    max_lines: int = 200,
    line_limit: int = 500,
) -> list[dict]:
    """Convert pasted or attached receiver/HID logs into callback events."""
    events: list[dict] = []
    normalized_source = str(source or "receiver_log")
    normalized_device = str(device_id or "")
    limit = max(0, int(max_lines or 0))
    if limit <= 0:
        return events
    for line_no, raw_line in enumerate(str(text or "").splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        event_name, severity, category = _classify_callback_log_line(line)
        clipped = line[:line_limit]
        events.append({
            "event": event_name,
            "device_id": normalized_device,
            "source": normalized_source,
            "severity": severity,
            "data": {
                "line_no": line_no,
                "line": clipped,
                "category": category,
                "truncated": len(line) > len(clipped),
            },
        })
        if len(events) >= limit:
            break
    return events


def callback_log_brief(events: list[dict], *, pushed: int = 0) -> str:
    counts: dict[str, int] = {}
    event_counts: dict[str, int] = {}
    for event in events:
        severity = str(event.get("severity", "info") or "info")
        counts[severity] = counts.get(severity, 0) + 1
        event_name = str(event.get("event", "") or "receiver_log")
        event_counts[event_name] = event_counts.get(event_name, 0) + 1
    top_events = ", ".join(
        f"{name}={count}" for name, count in sorted(event_counts.items())[:4]
    ) or "none"
    return (
        f"Callback log attach: events={len(events)}, pushed={pushed}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"error={counts.get('error', 0)}; top={top_events}"
    )


def callback_log_evidence_status(events: list[dict]) -> str:
    """Return the JSONL status for an attached receiver/HID log triage."""
    if not events:
        return "skip"
    severities = {str(event.get("severity", "info") or "info") for event in events}
    if severities.intersection({"fail", "error"}):
        return "fail"
    return "info"


def callback_log_evidence_details(
    events: list[dict],
    *,
    source_path: str | Path = "",
    pushed: int = 0,
    push_error: str = "",
    sample_limit: int = 8,
) -> dict:
    """Build structured JSONL details for receiver/HID log triage evidence."""
    severity_counts: dict[str, int] = {}
    event_counts: dict[str, int] = {}
    category_counts: dict[str, int] = {}
    devices: list[str] = []
    sources: list[str] = []
    samples = []
    first_problem_category = ""

    for event in events:
        severity = str(event.get("severity", "info") or "info")
        event_name = str(event.get("event", "receiver_log") or "receiver_log")
        data = event.get("data", {}) if isinstance(event.get("data"), dict) else {}
        category = str(data.get("category", "") or "uncategorized")
        severity_counts[severity] = severity_counts.get(severity, 0) + 1
        event_counts[event_name] = event_counts.get(event_name, 0) + 1
        category_counts[category] = category_counts.get(category, 0) + 1
        _append_unique(devices, str(event.get("device_id", "") or ""))
        _append_unique(sources, str(event.get("source", "") or ""))
        if severity in {"fail", "error"} and not first_problem_category:
            first_problem_category = category
        if len(samples) < sample_limit:
            samples.append({
                "line_no": data.get("line_no", ""),
                "event": event_name,
                "severity": severity,
                "category": category,
                "line": str(data.get("line", "") or "")[:300],
            })

    details = {
        "log_triage": True,
        "source_path": str(source_path or ""),
        "events": len(events),
        "pushed": int(pushed or 0),
        "push_error": str(push_error or ""),
        "by_severity": dict(sorted(severity_counts.items())),
        "by_event": dict(sorted(event_counts.items())),
        "by_category": dict(sorted(category_counts.items())),
        "devices": devices,
        "sources": sources,
        "samples": samples,
        "manual_observation": False,
        "claim_boundary": "Log triage supports debugging and recovery; it does not prove real iPhone control.",
    }
    if first_problem_category:
        details["category"] = first_problem_category
    return details


