def issue_triage_rows(events: list[dict]) -> list[dict[str, str]]:
    """Group failed evidence events into SOP issue buckets."""
    groups: dict[str, dict[str, Any]] = {}
    for event in events:
        if event.get("status") != "fail" or is_aggregate_failure(event):
            continue
        category = failure_category(event)
        group = groups.setdefault(
            category,
            {
                "category": category,
                "count": 0,
                "devices": [],
                "steps": [],
                "artifacts": [],
                "first_ts": "",
                "last_ts": "",
            },
        )
        group["count"] += 1
        ts = str(event.get("ts", "") or "")
        if ts and not group["first_ts"]:
            group["first_ts"] = ts
        if ts:
            group["last_ts"] = ts
        _append_unique(group["steps"], str(event.get("step", "") or "unknown"))
        for device_id in event.get("device_ids", []) if isinstance(event.get("device_ids", []), list) else []:
            _append_unique(group["devices"], str(device_id))
        for artifact in event.get("artifacts", []) if isinstance(event.get("artifacts", []), list) else []:
            _append_unique(group["artifacts"], str(artifact))

    rows = []
    for category in sorted(groups):
        group = groups[category]
        rows.append({
            "category": category,
            "count": str(group["count"]),
            "devices": ", ".join(group["devices"]) or "-",
            "steps": ", ".join(group["steps"][:4]) or "-",
            "artifacts": ", ".join(group["artifacts"][:3]) or "-",
            "first_ts": group["first_ts"] or "-",
            "last_ts": group["last_ts"] or "-",
            "recommendation": RECOMMENDATIONS.get(
                category,
                "Open Timeline and Matrix, add a manual failure category, and rerun the smallest reproducible scenario.",
            ),
            "next_action": _issue_next_action(category),
        })
    return rows


def issue_triage_brief(rows: list[dict[str, str]]) -> str:
    total = sum(int(row.get("count", "0") or 0) for row in rows)
    category_text = ", ".join(f"{row.get('category')}={row.get('count')}" for row in rows[:4]) or "none"
    return f"Issue triage: categories={len(rows)}, failures={total}; {category_text}"


