def rerun_playbook_rows(
    issue_rows_data: list[dict[str, str]] | None = None,
    *,
    stage: str = "p1",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Convert current failures and gates into a field rerun decision playbook."""
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []
    seen: set[str] = set()

    def add_row(
        category: str,
        *,
        count: int = 0,
        status: str,
        current: str,
        devices: str = "-",
        steps: str = "-",
        source: str = "computed",
    ) -> None:
        policy = _rerun_playbook_policy(category)
        method = policy["method"]
        rows.append({
            "category": category,
            "status": status,
            "count": str(count),
            "devices": devices or "-",
            "steps": steps or "-",
            "current": current,
            "rerun_rule": policy["rerun_rule"],
            "fresh_run_id": policy["fresh_run_id"],
            "evidence": policy["evidence"],
            "stop_rule": policy["stop_rule"],
            "gui_action": _rerun_playbook_gui_action(method),
            "method": method,
            "source": source,
        })
        seen.add(category)

    for issue in issue_rows_data or []:
        category = str(issue.get("category", "") or "uncategorized")
        try:
            count = int(issue.get("count", 0) or 0)
        except (TypeError, ValueError):
            count = 0
        if count <= 0:
            continue
        add_row(
            category,
            count=count,
            status="fail",
            current=(
                f"issue_count={count}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; real_ios_verified={real_ios_verified}"
            ),
            devices=str(issue.get("devices", "-") or "-"),
            steps=str(issue.get("steps", "-") or "-"),
            source="Issue Triage",
        )

    if route_report is None and "route_decision" not in seen:
        add_row(
            "route_decision",
            status="pending",
            current=f"stage={normalized_stage.upper()}; route decision not loaded; events={total_events}, fail={fail_events}",
            source="Route gate",
        )
    elif route_report is not None and not route_ready and "route_decision" not in seen:
        add_row(
            "route_decision",
            status="fail",
            current=route_decision_brief(route_report),
            source="Route gate",
        )

    if doctor_report is None and "doctor" not in seen:
        add_row(
            "doctor",
            status="pending",
            current=f"stage={normalized_stage.upper()}; doctor not run",
            source="Doctor gate",
        )
    elif doctor_report is not None and not doctor_clean and "doctor" not in seen:
        add_row(
            "doctor",
            status="fail" if doctor_overall == "fail" else "warn",
            current=doctor_brief(doctor_report),
            source="Doctor gate",
        )

    if acceptance_report is None and "acceptance" not in seen:
        add_row(
            "acceptance",
            status="pending",
            current="acceptance not evaluated",
            source="Acceptance gate",
        )
    elif acceptance_report is not None and not acceptance_ok and "acceptance" not in seen:
        add_row(
            "acceptance",
            status="fail",
            current=acceptance_brief(acceptance_report),
            source="Acceptance gate",
        )

    if readiness_report is None and "readiness" not in seen:
        add_row(
            "readiness",
            status="pending",
            current="readiness not evaluated",
            source="Readiness gate",
        )
    elif readiness_report is not None and (not readiness_ok or not real_ios_verified) and "readiness" not in seen:
        add_row(
            "readiness",
            status="fail" if not readiness_ok else "warn",
            current=f"{readiness_brief(readiness_report)}; real_ios_verified={real_ios_verified}",
            source="Readiness gate",
        )

    if not rows:
        status = "ready" if evidence_exists and total_events > 0 and fail_events == 0 else "pending"
        add_row(
            "no_open_rerun",
            status=status,
            current=f"events={total_events}, fail={fail_events}; route_ready={route_ready}; doctor_clean={doctor_clean}",
            source="Summary",
        )
    return rows


def rerun_playbook_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_action = _first_attention_value(rows, "category", statuses={"fail", "pending", "warn"})
    return (
        f"Rerun playbook {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_action={first_action}"
    )


def write_rerun_playbook_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# GUI 重跑手册 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This playbook turns failures and gates into rerun decisions. It does not write evidence and does not prove real iPhone response.",
        "",
        "## Rerun Decisions",
        "",
        "| Category | Status | Count | Devices | Steps | Current | Rerun rule | Fresh run_id | Evidence to keep | Stop rule | GUI action | Source |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('category', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('count', ''))} | {_md_cell(row.get('devices', ''))} | "
            f"{_md_cell(row.get('steps', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('rerun_rule', ''))} | {_md_cell(row.get('fresh_run_id', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('source', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | 0 | - | - | no rows built | Refresh Rerun | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Rerun Rule",
        "",
        "Use Rerun after Timeline, Matrix, Triage, and Review. Rerun the smallest failing path first. Start a fresh run_id when route, wiring, receiver identity, selected devices, or iPhone settings changed. Promotion still depends on JSONL evidence, Acceptance, Readiness, and manual real-iPhone observation.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _issue_category_counts(issue_rows_data: list[dict[str, str]] | None) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in issue_rows_data or []:
        category = str(row.get("category", "") or "").strip()
        if not category:
            continue
        try:
            count = int(row.get("count", 0) or 0)
        except (TypeError, ValueError):
            count = 0
        counts[category] = counts.get(category, 0) + count
    return counts


def _recovery_gui_action(method: str) -> str:
    return {
        "edit_route_decision_from_gui": "Edit Route",
        "run_preflight_doctor": "Run Doctor",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_template_asset_manager": "Open Assets",
        "show_device_evidence_matrix_from_gui": "Open Matrix",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "write_evidence_pack_from_gui": "Export Pack",
        "show_issue_triage_from_gui": "Open Triage",
    }.get(method, method)


def recovery_drill_rows(
    issue_rows_data: list[dict[str, str]] | None = None,
    *,
    stage: str = "p1",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build a field recovery drill board for receiver/HID/ops failures."""
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    metrics = summary.get("metrics", {}) if isinstance(summary.get("metrics"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = int(metrics.get("count", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    issue_counts = _issue_category_counts(issue_rows_data)

    topics = [
        {
            "key": "route_doctor_recovery",
            "categories": ("route_decision",),
            "trigger": "Route placeholder, open blocker, receiver/HID identity drift, or doctor fail.",
            "recovery": "Freeze the bench, edit Route Decision, rerun Doctor, then use a fresh run_id if route evidence was written.",
            "verify": "Route report ready=true, Doctor overall=ok, selected device scope unchanged.",
            "evidence": "Route JSON/report, Doctor report, component metadata, operator note.",
            "stop": "Stop real actions while route or doctor is fail.",
            "method": "edit_route_decision_from_gui",
        },
        {
            "key": "receiver_capture_recovery",
            "categories": ("airplay_discovery", "airplay_stream", "capture"),
            "trigger": "iPhone cannot find receiver, wrong window, black/stale frame, or screenshot drift.",
            "recovery": "Restart receiver/capture, reselect AirPlay identity, attach logs, then run Shot Bench.",
            "verify": "Fresh screenshots are non-black, correct-device, stable size, and tied to receiver metadata.",
            "evidence": "Receiver log, screenshot artifacts, screenshot_quality rows, capture method/window binding.",
            "stop": "Stop HID/control replay until screenshot quality is pass for the selected device.",
            "method": "run_capture_quality_bench_from_gui",
        },
        {
            "key": "hid_control_recovery",
            "categories": ("hid",),
            "trigger": "API/HID command returns but phone does not move, stuck press, no release, or text input drift.",
            "recovery": "Release/replug HID, confirm serial/firmware/Hub/Cable, then run Control Bench with Manual observation.",
            "verify": "Click, swipe, and text lanes have Manual pass or explicit fail category with artifact.",
            "evidence": "HID id/serial/firmware, Hub/Cable note, Control Bench, manual pass/fail, video/screenshot.",
            "stop": "Stop scaling if software success is not visible on the real iPhone.",
            "method": "show_control_response_bench_from_gui",
        },
        {
            "key": "calibration_recovery",
            "categories": ("calibration",),
            "trigger": "Pointer offset, wrong orientation, safe-area drift, or inverted swipe.",
            "recovery": "Redo five-point calibration for the exact model/iOS/orientation/profile before replaying scripts.",
            "verify": "Safe points land within tolerance and a fresh manual click/swipe observation is recorded.",
            "evidence": "Calibration profile, active area, target size, five-point error note, screenshot artifact.",
            "stop": "Stop reusing coordinates when model, iOS, orientation, receiver crop, or mouse profile changed.",
            "method": "show_p1_trial_from_gui",
        },
        {
            "key": "vision_business_recovery",
            "categories": ("vision_template", "vision_color", "ocr", "business_state"),
            "trigger": "Template miss, color/OCR drift, or page state no longer matches script assumptions.",
            "recovery": "Replay from saved screenshots, adjust region/threshold/assets, then rerun the smallest business step.",
            "verify": "Recognition is reproducible from artifacts before touching HID again.",
            "evidence": "Template/color/OCR settings, source screenshot, false-positive note, scenario step.",
            "stop": "Stop if a business click is not guarded by vision evidence or a manual state check.",
            "method": "show_template_asset_manager",
        },
        {
            "key": "group_isolation_recovery",
            "categories": ("group_dispatch",),
            "trigger": "One device fails inside a group or aggregate success hides per-device failure.",
            "recovery": "Remove the failing device from the group, prove it alone, then rejoin and rerun group step.",
            "verify": "Matrix shows each target device with its own event, manual observation, and failure category.",
            "evidence": "Device Matrix, group membership, per-device results, failure artifact, isolation note.",
            "stop": "Stop P3/P4 if any target device is pending or unassigned.",
            "method": "show_device_evidence_matrix_from_gui",
        },
        {
            "key": "performance_watchdog_recovery",
            "categories": ("performance",),
            "trigger": "Latency, reconnect, resource pressure, screenshot/HID failure after long run.",
            "recovery": "Capture metrics and logs before increasing duration or device count; reduce concurrency if needed.",
            "verify": "Metrics samples, receiver/HID logs, and failure categories explain every long-run failure.",
            "evidence": "Metrics rows, callback log, receiver log, resource snapshot, duration note.",
            "stop": "Stop P2/P3/P4 promotion without metrics and recovery notes.",
            "method": "show_stage_dashboard_from_gui",
        },
        {
            "key": "handoff_claim_recovery",
            "categories": ("acceptance", "readiness", "uncategorized"),
            "trigger": "Acceptance/Readiness fail, missing pack artifact, or unresolved uncategorized failure.",
            "recovery": "Export Pack, fill missing evidence, classify uncategorized failures, rerun Acceptance and Readiness.",
            "verify": "No fail events remain unexplained and real_ios_verified matches manual observations.",
            "evidence": "Evidence Pack, Acceptance, Readiness, Review, Rerun Playbook, operator handoff note.",
            "stop": "Stop all control/parity claims while Acceptance or Readiness is fail.",
            "method": "write_evidence_pack_from_gui",
        },
    ]

    rows: list[dict[str, str]] = []
    for topic in topics:
        key = str(topic["key"])
        categories = tuple(str(item) for item in topic["categories"])
        category_count = sum(issue_counts.get(category, 0) for category in categories)
        status = "pending"
        current = (
            f"events={total_events}, fail={fail_events}; route_ready={route_ready}; "
            f"doctor={doctor_overall or '-'}; acceptance_ok={acceptance_ok}; "
            f"readiness_ok={readiness_ok}; real_ios_verified={real_ios_verified}"
        )

        if category_count:
            status = "fail"
            current = f"category_failures={category_count}; {current}"
        elif key == "route_doctor_recovery":
            if route_report is None or doctor_report is None:
                status = "pending"
                current = f"route/doctor not loaded; stage={normalized_stage.upper()}"
            elif not route_ready or not doctor_clean:
                status = "fail"
                current = f"{route_decision_brief(route_report or {})}; {doctor_brief(doctor_report or {})}"
            else:
                status = "ready"
                current = "route and doctor clean; recovery drill can proceed to receiver/HID proof"
        elif key == "receiver_capture_recovery":
            if screenshot_status == "pass" and route_ready and doctor_clean:
                status = "ready"
            elif screenshot_status == "fail" or (route_report is not None and not route_ready) or (doctor_report is not None and not doctor_clean):
                status = "fail"
            else:
                status = "pending"
            current = f"screenshot={screenshot_text}; route_ready={route_ready}; doctor_clean={doctor_clean}"
        elif key == "hid_control_recovery":
            if manual_status == "pass" and route_ready and doctor_clean:
                status = "ready"
            elif manual_status == "fail" or (route_report is not None and not route_ready) or (doctor_report is not None and not doctor_clean):
                status = "fail"
            else:
                status = "pending"
            current = f"manual={manual_text}; route_ready={route_ready}; doctor_clean={doctor_clean}"
        elif key == "calibration_recovery":
            if screenshot_status == "pass" and manual_status == "pass":
                status = "ready"
            elif manual_status == "fail":
                status = "fail"
            else:
                status = "pending" if evidence_exists else "warn"
            current = f"screenshot={screenshot_text}; manual={manual_text}"
        elif key == "vision_business_recovery":
            if evidence_exists and total_events > 0 and fail_events == 0:
                status = "ready"
            elif fail_events:
                status = "warn"
            else:
                status = "pending"
            current = f"events={total_events}, fail={fail_events}; replay from artifacts before HID"
        elif key == "group_isolation_recovery":
            if normalized_stage in {"p3", "p4"} and not evidence_exists:
                status = "pending"
            elif normalized_stage in {"p1", "p2"}:
                status = "warn"
            elif fail_events:
                status = "warn"
            else:
                status = "ready"
            current = f"stage={normalized_stage.upper()}; events={total_events}, fail={fail_events}"
        elif key == "performance_watchdog_recovery":
            if normalized_stage in {"p2", "p3", "p4"} and metrics_count == 0:
                status = "pending"
            elif metrics_count:
                status = "ready" if fail_events == 0 else "warn"
            else:
                status = "warn"
            current = f"metrics={metrics_count}; events={total_events}, fail={fail_events}"
        elif key == "handoff_claim_recovery":
            if not evidence_exists:
                status = "pending"
                current = "evidence JSONL missing; no handoff claim is allowed"
            elif acceptance_report is None or readiness_report is None:
                status = "pending"
                current = "acceptance/readiness not loaded"
            elif not acceptance_ok or not readiness_ok:
                status = "fail"
                current = f"{acceptance_brief(acceptance_report or {})}; {readiness_brief(readiness_report or {})}"
            elif not real_ios_verified:
                status = "warn"
                current = f"gates clean but real_ios_verified={real_ios_verified}"
            elif fail_events:
                status = "fail"
                current = f"fail_events={fail_events}; classify and rerun before handoff"
            else:
                status = "ready"
                current = "handoff pack can be reviewed against the proven stage claim"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "status": status,
            "category_count": str(category_count),
            "categories": ", ".join(categories),
            "trigger": str(topic["trigger"]),
            "current": current,
            "recovery": str(topic["recovery"]),
            "verify": str(topic["verify"]),
            "evidence": str(topic["evidence"]),
            "stop_rule": str(topic["stop"]),
            "gui_action": _recovery_gui_action(method),
            "method": method,
        })
    return rows


def recovery_drill_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_action = _first_attention_value(rows, "key", statuses={"fail", "pending", "warn"})
    return (
        f"Recovery drill {stage.upper()}: "
        f"ready={counts.get('ready', 0)}, warn={counts.get('warn', 0)}, "
        f"fail={counts.get('fail', 0)}, pending={counts.get('pending', 0)}; "
        f"first_action={first_action}"
    )


def write_recovery_drill_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# GUI 恢复演练 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This drill turns failures into recovery steps. The GUI Record Pass/Fail buttons can write recovery execution evidence, but the Markdown export alone does not prove real iPhone response.",
        "",
        "## Recovery Rows",
        "",
        "| Key | Status | Category failures | Categories | Trigger | Current | Recovery step | Verify step | Evidence to keep | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('category_count', ''))} | {_md_cell(row.get('categories', ''))} | "
            f"{_md_cell(row.get('trigger', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('recovery', ''))} | {_md_cell(row.get('verify', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | 0 | - | no rows built | - | Refresh Recovery | - | - | Do not promote | - |")
    lines.extend([
        "",
        "## Recovery Rule",
        "",
        "Use Recovery after Triage/Rerun and before longer P2/P3/P4 runs. A recovery row is closed only when the recovery step, verification step, artifacts, and Acceptance/Readiness boundary are all recorded for the same run or for a fresh run_id after bench changes. Recovery execution evidence is not a substitute for Manual/P1 Trial click, swipe, and text observations.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _pitfall_gui_action(method: str) -> str:
    return {
        "run_preflight_doctor": "Run Doctor",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_template_asset_manager": "Open Assets",
        "show_device_evidence_matrix_from_gui": "Open Matrix",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "show_scenario_library_from_gui": "Open Scenario Library",
        "show_gui_goal_gate_from_gui": "Open Goals",
        "write_xp_gap_audit_from_gui": "Export XP Gap",
        "show_issue_triage_from_gui": "Open Triage",
        "attach_callback_log_from_gui": "Attach Log",
    }.get(method, method)


def pitfall_library_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    issue_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build an operator pitfall library with current run risk signals."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    issue_counts = _issue_category_counts(issue_rows_data)
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}
    hid_route = str(route_values.get("hid.route", nested_get(route_decision or {}, "hid.route", "")) or "").strip()

    rows: list[dict[str, str]] = []

    for topic in PITFALL_LIBRARY_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        categories = tuple(str(item) for item in topic.get("categories", ()))
        category_count = sum(issue_counts.get(category, 0) for category in categories)
        doc_status = "pass" if (root / source).exists() else "warn"
        status = doc_status
        current = f"category_failures={category_count}; events={total_events}, fail={fail_events}"

        if category_count:
            status = _worst_status(doc_status, "fail")
            current = f"category_failures={category_count}; fix this bucket before rerun"
        elif key == "receiver_discovery":
            if route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
                current = "route/doctor not loaded"
            elif not route_ready or not doctor_clean:
                status = _worst_status(doc_status, "fail")
                current = f"route_ready={route_ready}, doctor_clean={doctor_clean}"
            else:
                status = _worst_status(doc_status, "ready")
                current = "route and doctor are clean; verify iPhone AirPlay target on the bench"
        elif key == "receiver_stream_capture":
            if screenshot_status == "pass":
                status = _worst_status(doc_status, "ready")
            elif screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = f"screenshot={screenshot_text}; route_ready={route_ready}, doctor_clean={doctor_clean}"
        elif key == "hid_no_response":
            if manual_status == "pass":
                status = _worst_status(doc_status, "ready")
            elif manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = f"manual={manual_text}; route_ready={route_ready}, doctor_clean={doctor_clean}"
        elif key == "calibration_pointer_drift":
            if manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "pending")
            current = f"screenshot={screenshot_text}; manual={manual_text}"
        elif key == "vision_asset_drift":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"events={total_events}, fail={fail_events}; check template/color/OCR artifacts before scale"
        elif key == "group_isolation":
            if normalized_stage in {"p3", "p4"} and len(selected_devices) < required_devices:
                status = _worst_status(doc_status, "fail")
            elif normalized_stage in {"p3", "p4"} and not evidence_exists:
                status = _worst_status(doc_status, "pending")
            elif normalized_stage in {"p1", "p2"}:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"selected={len(selected_devices)}, required={required_devices}, stage={normalized_stage.upper()}"
        elif key == "performance_stability":
            if normalized_stage in {"p2", "p3", "p4"} and metrics_count == 0:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready" if metrics_count else "warn")
            current = f"metrics={metrics_count}, events={total_events}, fail={fail_events}"
        elif key == "business_state":
            if not evidence_exists:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"events={total_events}, fail={fail_events}; replay scenario artifacts before editing flow logic"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = (
                f"acceptance_ok={acceptance_ok}, readiness_ok={readiness_ok}, "
                f"real_ios_verified={real_ios_verified}, fail={fail_events}"
            )
        elif key == "xp_hardware_parity":
            if hid_route == "xp_hardware":
                status = _worst_status(doc_status, "ready")
                current = "hid.route=xp_hardware; side-by-side XP hardware evidence still required"
            elif hid_route:
                status = _worst_status(doc_status, "warn")
                current = f"hid.route={hid_route}; generic P1 may continue, XP hardware parity blocked"
            else:
                status = _worst_status(doc_status, "pending")
                current = "hid.route not selected"

        rows.append({
            "key": key,
            "pitfall": str(topic["pitfall"]),
            "status": status,
            "symptom": str(topic["symptom"]),
            "current": current,
            "likely_causes": str(topic["likely_causes"]),
            "sop_check": str(topic["sop_check"]),
            "first_probe": str(topic["first_probe"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "categories": ", ".join(categories) or "-",
            "gui_action": _pitfall_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def pitfall_library_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_focus = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_focus == "none" and status in {"fail", "pending", "warn"}:
            first_focus = str(row.get("pitfall", "") or "unknown")
    return (
        f"Pitfall library {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_pitfall_library_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 陷阱库 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This library turns industry/SOP failure patterns into field actions. It does not write evidence or prove real iPhone response.",
        "",
        "## Pitfalls",
        "",
        "| Pitfall | Status | Current signal | Symptom | Likely causes | SOP check | First probe | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('pitfall', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('symptom', ''))} | "
            f"{_md_cell(row.get('likely_causes', ''))} | {_md_cell(row.get('sop_check', ''))} | "
            f"{_md_cell(row.get('first_probe', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | no rows built | - | - | Refresh Pitfalls | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Use Pitfalls before reruns and after every failed trial. It is a SOP index, not evidence. Convert each row into JSONL evidence, artifacts, Issue Triage, Acceptance, and Readiness before changing any product claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _pitfall_category_map(rows: list[dict[str, str]]) -> dict[str, dict[str, str]]:
    mapping: dict[str, dict[str, str]] = {}
    for row in rows:
        for category in str(row.get("categories", "") or "").split(","):
            text = category.strip()
            if text and text != "-":
                mapping.setdefault(text, row)
    return mapping


def _issue_count_map(rows: list[dict[str, str]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        category = str(row.get("category", "") or "").strip()
        if not category:
            continue
        try:
            counts[category] = counts.get(category, 0) + int(row.get("count", 0) or 0)
        except (TypeError, ValueError):
            counts[category] = counts.get(category, 0)
    return counts


def _rerun_row_map(rows: list[dict[str, str]]) -> dict[str, dict[str, str]]:
    return {
        str(row.get("category", "") or "").strip(): row
        for row in rows
        if str(row.get("category", "") or "").strip()
    }


def _ledger_row_from_pitfall(
    row: dict[str, str],
    *,
    issue_counts: dict[str, int],
    rerun_by_category: dict[str, dict[str, str]],
) -> dict[str, str]:
    categories = [
        item.strip()
        for item in str(row.get("categories", "") or "").split(",")
        if item.strip() and item.strip() != "-"
    ]
    count = sum(issue_counts.get(category, 0) for category in categories)
    category = categories[0] if categories else "uncategorized"
    rerun = next((rerun_by_category.get(item) for item in categories if item in rerun_by_category), None)
    policy = _rerun_playbook_policy(category)
    if rerun:
        policy_method = str(rerun.get("method", "") or policy["method"])
        status = _worst_status(str(row.get("status", "pending")), str(rerun.get("status", "pending")))
        rerun_rule = str(rerun.get("rerun_rule", "") or policy["rerun_rule"])
        fresh_run_id = str(rerun.get("fresh_run_id", "") or policy["fresh_run_id"])
        evidence = str(rerun.get("evidence", "") or policy["evidence"])
        gui_action = str(rerun.get("gui_action", "") or _rerun_playbook_gui_action(policy_method))
        source = str(rerun.get("source", "") or "Pitfall Library")
    else:
        policy_method = policy["method"]
        status = "fail" if count else str(row.get("status", "pending") or "pending")
        rerun_rule = policy["rerun_rule"]
        fresh_run_id = policy["fresh_run_id"]
        evidence = policy["evidence"]
        gui_action = str(row.get("gui_action", "") or _rerun_playbook_gui_action(policy_method))
        source = "Pitfall Library"
    if count:
        status = "fail"
    return {
        "problem": str(row.get("pitfall", "") or category),
        "category": ", ".join(categories) or category,
        "status": status,
        "count": str(count),
        "ledger_type": "field_failure" if count else "industry_risk",
        "current": str(row.get("current", "") or ""),
        "sop_prevention": str(row.get("sop_check", "") or ""),
        "first_replay": str(row.get("first_probe", "") or ""),
        "rerun_rule": rerun_rule,
        "fresh_run_id": fresh_run_id,
        "evidence": evidence,
        "stop_rule": str(row.get("stop_rule", "") or policy["stop_rule"]),
        "gui_action": gui_action,
        "method": policy_method,
        "source": source,
    }


def sop_problem_ledger_rows(
    *,
    stage: str = "p1",
    pitfall_rows_data: list[dict[str, str]] | None = None,
    issue_rows_data: list[dict[str, str]] | None = None,
    rerun_rows_data: list[dict[str, str]] | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    readiness_report: dict | None = None,
) -> list[dict[str, str]]:
    """Combine industry pitfalls, field failures, and rerun rules into a SOP problem ledger."""
    normalized_stage = stage.lower().strip() or "p1"
    pitfall_rows = pitfall_rows_data or []
    issue_rows = issue_rows_data or []
    rerun_rows = rerun_rows_data or []
    issue_counts = _issue_count_map(issue_rows)
    pitfall_by_category = _pitfall_category_map(pitfall_rows)
    rerun_by_category = _rerun_row_map(rerun_rows)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []
    covered_categories: set[str] = set()
    for pitfall in pitfall_rows:
        row = _ledger_row_from_pitfall(
            pitfall,
            issue_counts=issue_counts,
            rerun_by_category=rerun_by_category,
        )
        row_categories = [
            item.strip()
            for item in row["category"].split(",")
            if item.strip() and item.strip() != "-"
        ]
        if row["ledger_type"] == "field_failure" and any(category in covered_categories for category in row_categories):
            row["count"] = "0"
            row["ledger_type"] = "industry_risk"
            row["status"] = str(pitfall.get("status", "pending") or "pending")
        rows.append(row)
        covered_categories.update(row_categories)

    for issue in issue_rows:
        category = str(issue.get("category", "") or "uncategorized").strip() or "uncategorized"
        if category in covered_categories:
            continue
        policy = _rerun_playbook_policy(category)
        rerun = rerun_by_category.get(category, {})
        rows.append({
            "problem": f"Unmapped field failure: {category}",
            "category": category,
            "status": str(rerun.get("status", "") or "fail"),
            "count": str(issue_counts.get(category, issue.get("count", "0") or "0")),
            "ledger_type": "field_failure",
            "current": f"devices={issue.get('devices', '-')}; steps={issue.get('steps', '-')}",
            "sop_prevention": "Add this category to Pitfalls after the run if it repeats.",
            "first_replay": str(issue.get("next_action", "") or _rerun_playbook_gui_action(policy["method"])),
            "rerun_rule": str(rerun.get("rerun_rule", "") or policy["rerun_rule"]),
            "fresh_run_id": str(rerun.get("fresh_run_id", "") or policy["fresh_run_id"]),
            "evidence": str(rerun.get("evidence", "") or policy["evidence"]),
            "stop_rule": str(rerun.get("stop_rule", "") or policy["stop_rule"]),
            "gui_action": str(rerun.get("gui_action", "") or _rerun_playbook_gui_action(policy["method"])),
            "method": str(rerun.get("method", "") or policy["method"]),
            "source": str(rerun.get("source", "") or "Issue Triage"),
        })

    if not rows:
        rows.append({
            "problem": "No SOP problem rows built",
            "category": "-",
            "status": "pending",
            "count": "0",
            "ledger_type": "empty",
            "current": f"stage={normalized_stage.upper()}, evidence_exists={evidence_exists}, events={total_events}, fail={fail_events}",
            "sop_prevention": "Refresh Pitfalls and Triage first.",
            "first_replay": "Open Pitfalls",
            "rerun_rule": "Do not rerun blindly without a category or stage gate.",
            "fresh_run_id": "no",
            "evidence": "Pitfall export, Issue Triage, Timeline, Matrix.",
            "stop_rule": "Stop promotion while the problem ledger is empty.",
            "gui_action": "Open Pitfalls",
            "method": "show_pitfall_library_from_gui",
            "source": "computed",
        })

    if fail_events == 0 and evidence_exists and real_ios_verified:
        for row in rows:
            if row["ledger_type"] == "industry_risk" and row["status"] in {"ready", "pass"}:
                row["status"] = "pass"
    return rows


def sop_problem_ledger_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    field_failures = sum(int(row.get("count", 0) or 0) for row in rows if row.get("ledger_type") == "field_failure")
    first_focus = _first_attention_value(rows, "problem", statuses={"fail", "pending", "warn"})
    return (
        f"SOP problem ledger {stage.upper()}: "
        f"field_failures={field_failures}, pass={counts.get('pass', 0)}, "
        f"ready={counts.get('ready', 0)}, warn={counts.get('warn', 0)}, "
        f"fail={counts.get('fail', 0)}, pending={counts.get('pending', 0)}; "
        f"first_focus={first_focus}"
    )


def write_sop_problem_ledger_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# GUI SOP 问题台账 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This ledger turns industry pitfalls and field failures into a reusable SOP issue log. It does not write JSONL evidence or prove real iPhone response.",
        "",
        "## Problem Rows",
        "",
        "| Problem | Type | Status | Count | Category | Current signal | SOP prevention | First replay | Rerun rule | Fresh run_id | Evidence to keep | Stop rule | GUI action | Source |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('problem', ''))} | {_md_cell(row.get('ledger_type', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('count', ''))} | "
            f"{_md_cell(row.get('category', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('sop_prevention', ''))} | {_md_cell(row.get('first_replay', ''))} | "
            f"{_md_cell(row.get('rerun_rule', ''))} | {_md_cell(row.get('fresh_run_id', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('source', ''))} |"
        )
    lines.extend([
        "",
        "## Ledger Rule",
        "",
        "Use this ledger after every field run and before changing scripts. A problem is closed only when the smallest replay path, evidence to keep, stop rule, Acceptance, Readiness, and operator observation all agree for the same run_id or a deliberately fresh run_id after bench changes.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def device_evidence_matrix_rows(
    *,
    device_rows: list[dict] | None = None,
    selected_device_ids: list[str] | None = None,
    events: list[dict] | None = None,
) -> list[dict[str, str]]:
    """Build per-device evidence coverage rows for group-control review."""
    devices = device_rows or []
    event_items = events or []
    device_by_id = {
        str(row.get("device_id", "") or ""): row
        for row in devices
        if str(row.get("device_id", "") or "").strip()
    }
    ordered_ids: list[str] = []

    def add_id(value: Any) -> None:
        text = str(value or "").strip()
        if text and text not in ordered_ids:
            ordered_ids.append(text)

    for device_id in selected_device_ids or []:
        add_id(device_id)
    for row in devices:
        add_id(row.get("device_id", ""))

    events_by_device: dict[str, list[dict]] = {}
    unassigned_events = []
    for event in event_items:
        ids = event.get("device_ids", [])
        if not isinstance(ids, list):
            ids = []
        cleaned = [str(item).strip() for item in ids if str(item).strip()]
        if not cleaned:
            unassigned_events.append(event)
            continue
        for device_id in cleaned:
            add_id(device_id)
            events_by_device.setdefault(device_id, []).append(event)
    if unassigned_events:
        add_id("unassigned")
        events_by_device["unassigned"] = unassigned_events

    rows = []
    selected = {str(item).strip() for item in selected_device_ids or [] if str(item).strip()}
    for device_id in ordered_ids:
        row = device_by_id.get(device_id, {})
        profile = _device_profile_from_status_row(row)
        device_events = events_by_device.get(device_id, [])
        fail_events = [event for event in device_events if event.get("status") == "fail"]
        last_event = device_events[-1] if device_events else {}
        categories = sorted({failure_category(event) for event in fail_events})
        artifacts = _event_artifacts(device_events)
        component_ok = (
            _component_metadata_complete(profile)
            or any(_component_metadata_complete(_event_details(event)) for event in device_events)
        )
        manual_pass = any(_event_has_manual_pass(event) for event in device_events)
        screenshot_pass = any(_event_has_screenshot_quality_pass(event) for event in device_events)
        gaps = []
        if device_id == "unassigned":
            gaps.append("missing_device_id")
        else:
            if not device_events:
                gaps.append("no_events")
            if not component_ok:
                gaps.append("component_metadata")
            if not screenshot_pass:
                gaps.append("screenshot_quality")
            if not manual_pass:
                gaps.append("manual_observation")
            if fail_events:
                gaps.append("failures")
        status = "fail" if fail_events else "pending" if gaps else "pass"
        rows.append({
            "device_id": device_id,
            "selected": "yes" if device_id in selected else "no",
            "state": str(row.get("state", "-") or "-") if device_id != "unassigned" else "-",
            "hardware": str(row.get("hardware_id", "") or profile.get("serial_port", "") or "-"),
            "iphone": str(row.get("iphone_name", "") or profile.get("iphone_id", "") or "-"),
            "component": "ok" if component_ok else "missing",
            "events": str(len(device_events)),
            "failures": str(len(fail_events)),
            "last_status": str(last_event.get("status", "-") or "-"),
            "last_step": str(last_event.get("step", "-") or "-"),
            "last_ts": str(last_event.get("ts", "-") or "-"),
            "categories": ", ".join(categories) or "-",
            "artifacts": ", ".join(artifacts[:3]) if artifacts else "-",
            "gaps": ", ".join(gaps) or "none",
            "status": status,
        })
    return rows


def device_evidence_matrix_brief(rows: list[dict[str, str]]) -> str:
    counts: dict[str, int] = {}
    selected_count = 0
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if row.get("selected") == "yes":
            selected_count += 1
    blockers = [
        row.get("device_id", "")
        for row in rows
        if row.get("status") != "pass"
    ]
    blocker_text = ", ".join(blockers[:4]) if blockers else "none"
    return (
        f"Device matrix: devices={len(rows)}, selected={selected_count}, "
        f"pass={counts.get('pass', 0)}, pending={counts.get('pending', 0)}, "
        f"fail={counts.get('fail', 0)}; blockers={blocker_text}"
    )


def device_ios_compatibility_rows(
    *,
    device_rows: list[dict] | None = None,
    selected_device_ids: list[str] | None = None,
    events: list[dict] | None = None,
    target_stage: str = "p1",
) -> list[dict[str, str]]:
    """Build a compatibility matrix by iPhone model/iOS version."""
    normalized_stage = target_stage.lower().strip() or "p1"
    matrix_rows = device_evidence_matrix_rows(
        device_rows=device_rows,
        selected_device_ids=selected_device_ids,
        events=events,
    )
    devices_by_id = {
        str(row.get("device_id", "") or ""): row
        for row in (device_rows or [])
        if str(row.get("device_id", "") or "").strip()
    }
    event_items = events or []
    events_by_device: dict[str, list[dict]] = {}
    for event in event_items:
        ids = event.get("device_ids", [])
        if not isinstance(ids, list):
            ids = []
        for device_id in ids:
            text = str(device_id).strip()
            if text:
                events_by_device.setdefault(text, []).append(event)

    groups: dict[tuple[str, str], dict[str, Any]] = {}

    def profile_for(device_id: str) -> dict:
        profile = _device_profile_from_status_row(devices_by_id.get(device_id, {}))
        if profile:
            return profile
        for event in events_by_device.get(device_id, []):
            details = _event_details(event)
            if isinstance(details, dict) and details:
                return details
        return {}

    for row in matrix_rows:
        device_id = str(row.get("device_id", "") or "")
        if device_id == "unassigned":
            key = ("unknown_model", "unknown_ios")
        else:
            profile = profile_for(device_id)
            raw_model = (
                profile.get("iphone_model")
                or profile.get("model")
                or profile.get("iphone")
                or row.get("iphone")
                or ""
            )
            raw_ios = profile.get("ios_version") or profile.get("ios") or ""
            model = str(raw_model or "").strip()
            ios_version = str(raw_ios or "").strip()
            if not model or model == "-":
                model = "unknown_model"
            if not ios_version or ios_version == "-":
                ios_version = "unknown_ios"
            key = (model, ios_version)
        group = groups.setdefault(
            key,
            {
                "model": key[0],
                "ios_version": key[1],
                "devices": [],
                "selected": 0,
                "pass": 0,
                "pending": 0,
                "fail": 0,
                "events": 0,
                "failures": 0,
                "gaps": [],
            },
        )
        _append_unique(group["devices"], device_id)
        if row.get("selected") == "yes":
            group["selected"] += 1
        status = str(row.get("status", "pending") or "pending")
        group[status if status in {"pass", "pending", "fail"} else "pending"] += 1
        try:
            group["events"] += int(row.get("events", "0") or 0)
            group["failures"] += int(row.get("failures", "0") or 0)
        except ValueError:
            pass
        for gap in str(row.get("gaps", "") or "").split(","):
            gap = gap.strip()
            if gap and gap != "none":
                _append_unique(group["gaps"], gap)

    rows: list[dict[str, str]] = []
    for key in sorted(groups):
        group = groups[key]
        device_count = len(group["devices"])
        if group["fail"]:
            status = "fail"
        elif group["pending"] or group["events"] == 0:
            status = "pending"
        elif group["pass"] == device_count and device_count > 0:
            status = "pass"
        else:
            status = "pending"
        if group["model"] == "unknown_model" or group["ios_version"] == "unknown_ios":
            status = _worst_status(status, "warn")
            _append_unique(group["gaps"], "model_or_ios_unknown")
        claim = (
            f"covered_for_{normalized_stage}"
            if status == "pass"
            else "not_covered"
        )
        rows.append({
            "model": str(group["model"]),
            "ios_version": str(group["ios_version"]),
            "devices": ", ".join(group["devices"]) or "-",
            "selected": str(group["selected"]),
            "device_count": str(device_count),
            "events": str(group["events"]),
            "failures": str(group["failures"]),
            "pass_devices": str(group["pass"]),
            "pending_devices": str(group["pending"]),
            "fail_devices": str(group["fail"]),
            "gaps": ", ".join(group["gaps"]) or "none",
            "claim": claim,
            "status": status,
            "next_action": _compatibility_next_action(status, group["gaps"]),
        })
    if not rows:
        rows.append({
            "model": "unknown_model",
            "ios_version": "unknown_ios",
            "devices": "-",
            "selected": "0",
            "device_count": "0",
            "events": "0",
            "failures": "0",
            "pass_devices": "0",
            "pending_devices": "0",
            "fail_devices": "0",
            "gaps": "no_devices",
            "claim": "not_covered",
            "status": "pending",
            "next_action": "Register/select a real iPhone and record component metadata.",
        })
    return rows


def device_ios_compatibility_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_gap = "none"
    covered = 0
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if row.get("claim") == f"covered_for_{stage.lower().strip() or 'p1'}":
            covered += 1
        if first_gap == "none" and status != "pass":
            first_gap = f"{row.get('model', '')}/{row.get('ios_version', '')}"
    return (
        f"Device/iOS compatibility {stage.upper()}: rows={len(rows)}, covered={covered}, "
        f"pass={counts.get('pass', 0)}, warn={counts.get('warn', 0)}, "
        f"pending={counts.get('pending', 0)}, fail={counts.get('fail', 0)}; first_gap={first_gap}"
    )


def write_device_ios_compatibility_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
) -> Path:
    out_path = Path(path)
    lines = [
        f"# Device iOS Compatibility Matrix {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        "- Real iOS control verified: `False`",
        "- This matrix groups local evidence by iPhone model and iOS version. It does not write evidence and does not prove broad compatibility or real iOS control.",
        "",
        "## Compatibility Rows",
        "",
        "| Model | iOS | Status | Claim | Devices | Selected | Events | Failures | Pass/Pending/Fail devices | Gaps | Next action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        device_counts = (
            f"{row.get('pass_devices', '0')}/"
            f"{row.get('pending_devices', '0')}/"
            f"{row.get('fail_devices', '0')}"
        )
        lines.append(
            f"| {_md_cell(row.get('model', ''))} | {_md_cell(row.get('ios_version', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | `{_md_cell(row.get('claim', ''))}` | "
            f"{_md_cell(row.get('devices', ''))} | {_md_cell(row.get('selected', ''))}/"
            f"{_md_cell(row.get('device_count', ''))} | {_md_cell(row.get('events', ''))} | "
            f"{_md_cell(row.get('failures', ''))} | {_md_cell(device_counts)} | "
            f"{_md_cell(row.get('gaps', ''))} | {_md_cell(row.get('next_action', ''))} |"
        )
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Do not convert public iMouse compatibility claims into our claims until each model/iOS row has local component metadata, screenshot quality, manual real-iPhone observations, no unexplained failures, Acceptance PASS, and Readiness PASS for the target stage.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _compatibility_next_action(status: str, gaps: list[str]) -> str:
    gap_set = {str(gap) for gap in gaps}
    if "model_or_ios_unknown" in gap_set or "component_metadata" in gap_set:
        return "Record component metadata with iPhone model and iOS version."
    if "screenshot_quality" in gap_set:
        return "Run Screenshot/P1 Trial and record screenshot quality evidence."
    if "manual_observation" in gap_set:
        return "Record manual click/swipe/type observations on the real iPhone."
    if "failures" in gap_set or status == "fail":
        return "Open Timeline/Triage, fix failures, then rerun with a fresh run_id when route changed."
    if status == "pass":
        return "Keep as local stage coverage only; do not generalize to untested models/iOS versions."
    return "Select device, run Wizard, Acceptance, and Readiness for this model/iOS row."


def real_run_guard_report(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    require_doctor_ok: bool = True,
) -> dict:
    """Return whether GUI real-run actions are allowed for the current bench."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    blockers = []
    checks = []

    def add_check(name: str, ok: bool, message: str) -> None:
        checks.append({"name": name, "ok": ok, "message": message})
        if not ok:
            blockers.append({"name": name, "message": message})

    add_check(
        "device_scope",
        len(selected_devices) >= required_devices,
        f"selected={len(selected_devices)}, required>={required_devices}",
    )

    if route_report is None:
        add_check("route_decision", False, "Route Decision is not loaded or not validated")
    else:
        route_ok = bool(route_report.get("ok")) and bool(route_report.get("ready"))
        add_check(
            "route_decision",
            route_ok,
            route_decision_brief(route_report),
        )

    if require_doctor_ok:
        if doctor_report is None:
            add_check("doctor", False, "Doctor has not been run for this run_id")
        else:
            add_check(
                "doctor",
                _doctor_allows_real_run(doctor_report),
                doctor_brief(doctor_report),
            )

    return {
        "stage": normalized_stage,
        "ok": not blockers,
        "device_ids": selected_devices,
        "required_devices": required_devices,
        "checks": checks,
        "blockers": blockers,
        "claims": {
            "guard_writes_evidence": False,
            "guard_verifies_real_ios_control": False,
        },
    }


def real_run_guard_brief(report: dict) -> str:
    stage = str(report.get("stage", "p1") or "p1").upper()
    status = "allow" if report.get("ok") else "blocked"
    blockers = report.get("blockers", []) if isinstance(report.get("blockers"), list) else []
    names = ", ".join(str(item.get("name", "")) for item in blockers[:3] if isinstance(item, dict)) or "none"
    return f"Real-run guard {stage} {status}: blockers={names}"


def write_real_run_guard_markdown(report: dict, path: str | Path, *, run_id: str = "") -> Path:
    out_path = Path(path)
    lines = [
        f"# GUI 真实运行守卫 {str(report.get('stage', 'p1')).upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Allowed: `{bool(report.get('ok'))}`",
        f"- Guard writes evidence: `{report.get('claims', {}).get('guard_writes_evidence', False)}`",
        f"- Guard verifies real iOS control: `{report.get('claims', {}).get('guard_verifies_real_ios_control', False)}`",
        "- This guard only blocks unsafe GUI real-run actions. It does not prove real iPhone response.",
        "",
        "## Checks",
        "",
        "| Check | OK | Message |",
        "|---|---|---|",
    ]
    for check in report.get("checks", []) or []:
        if not isinstance(check, dict):
            continue
        lines.append(
            f"| {_md_cell(check.get('name', ''))} | `{bool(check.get('ok'))}` | "
            f"{_md_cell(check.get('message', ''))} |"
        )
    lines.extend(["", "## Blockers", ""])
    blockers = [item for item in report.get("blockers", []) or [] if isinstance(item, dict)]
    if blockers:
        for item in blockers:
            lines.append(f"- {item.get('name', '')}: {item.get('message', '')}")
    else:
        lines.append("- none")
    lines.extend([
        "",
        "## Next Actions",
        "",
    ])
    if blockers:
        action_map = {
            "device_scope": "Select the exact physical device ids for this stage, then refresh Live Probe and Runner.",
            "route_decision": "Open Route Edit / Receiver / Rx Setup, remove placeholders and open blockers, then validate the same route decision path.",
            "doctor": "Run Doctor or route-aware Doctor. Fix hard fails before disabling Dry Run; route-specific warns need an operator note.",
        }
        for item in blockers:
            name = str(item.get("name", "") or "")
            lines.append(f"- {name}: {action_map.get(name, 'Open Verify and Runner, then resolve this blocker before real run.')}")
    else:
        lines.append("- Guard allows the real-run attempt, but this is still not a pass. Run the scenario, keep JSONL/artifacts, then use Acceptance and Readiness.")
    lines.extend([
        "",
        "## Stop Rule",
        "",
        "Do not bypass this guard by manually calling lower-level APIs when it is blocked. A guard allow only permits the attempt; real iOS control still requires screenshot quality, visible click/swipe/text behavior, lane-separated Manual observations, JSONL evidence, Acceptance PASS, and Readiness PASS.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


