def readiness_brief(report: dict) -> str:
    """Return one-line status text for a project readiness audit."""
    target = str(report.get("target", "unknown")).upper()
    status = "ok" if report.get("ok") else "fail"
    stages = report.get("stage_status", {})
    stage_text = ", ".join(
        f"{stage.upper()}={'pass' if item.get('ok') else 'fail'}"
        for stage, item in stages.items()
        if stage in {"p0", "p1", "p2", "p3", "p4"} and isinstance(item, dict)
    )
    blockers = report.get("blockers", [])
    blocker_names = ", ".join(str(item.get("name", "")) for item in blockers[:3] if isinstance(item, dict))
    if not blocker_names:
        blocker_names = "none"
    return f"Readiness {target} {status}: {stage_text}; blockers={blocker_names}"


def route_decision_brief(report: dict) -> str:
    """Return one-line status text for a route decision validation report."""
    target = str(report.get("target_stage", "p1") or "p1").upper()
    status = "ok" if report.get("ok") else "fail"
    ready = bool(report.get("ready"))
    blockers = report.get("blockers", [])
    blocker_names = ", ".join(
        str(item.get("name", "")) for item in blockers[:3] if isinstance(item, dict) and item.get("name")
    )
    if not blocker_names:
        blocker_names = "none"
    return f"Route decision {target} {status}: ready={ready}; blockers={blocker_names}"


def field_packet_brief(packet: dict) -> str:
    """Return one-line status text for a generated field packet."""
    stage = str(packet.get("stage", "p1") or "p1").upper()
    device_count = int(packet.get("device_count", len(packet.get("devices", []) or [])) or 0)
    doctor = packet.get("doctor", {}) if isinstance(packet.get("doctor"), dict) else {}
    readiness = packet.get("readiness", {}) if isinstance(packet.get("readiness"), dict) else {}
    readiness_status = "pass" if readiness.get("ok") else "fail"
    blockers = readiness.get("blockers", []) if isinstance(readiness, dict) else []
    blocker_names = ", ".join(
        str(item.get("name", "")) for item in blockers[:3] if isinstance(item, dict) and item.get("name")
    )
    if not blocker_names:
        blocker_names = "none"
    return (
        f"Field packet {stage}: devices={device_count}, "
        f"doctor={doctor.get('overall', 'not_run')}, readiness={readiness_status}; "
        f"blockers={blocker_names}"
    )


def operator_worksheet_brief(worksheet: dict) -> str:
    """Return one-line status text for a generated operator worksheet."""
    stage = str(worksheet.get("stage", "p1") or "p1").upper()
    device_count = int(worksheet.get("device_count", len(worksheet.get("devices", []) or [])) or 0)
    step_count = len(worksheet.get("steps", []) or [])
    script_count = len(worksheet.get("scripts", []) or [])
    return f"Operator worksheet {stage}: devices={device_count}, steps={step_count}, scripts={script_count}"


def acceptance_brief(report: dict) -> str:
    """Return one-line status text for an acceptance gate report."""
    gate = str(report.get("gate", "p1") or "p1").upper()
    status = "ok" if report.get("ok") else "fail"
    checks = report.get("checks", [])
    total = len(checks) if isinstance(checks, list) else 0
    passed = len([item for item in checks if isinstance(item, dict) and item.get("status") == "pass"])
    failed = [
        str(item.get("name", ""))
        for item in checks
        if isinstance(item, dict) and item.get("status") != "pass" and item.get("name")
    ]
    failed_text = ", ".join(failed[:3]) if failed else "none"
    return f"Acceptance {gate} {status}: checks={passed}/{total}; failed={failed_text}"


def standard_probe_script(stage: str) -> str:
    """Return the default GUI probe scenario for a field stage."""
    return STAGE_PRIMARY_SCENARIOS.get(stage.lower().strip(), STAGE_PRIMARY_SCENARIOS["p1"])


def scenario_library_rows(base_dir: str | Path = "scripts") -> list[dict[str, str]]:
    """Return runnable scenario metadata for the GUI library."""
    root = Path(base_dir)
    if not root.exists():
        return []
    stage_by_path = {
        str(Path(path).as_posix()).lower(): stage
        for stage, path in STAGE_PRIMARY_SCENARIOS.items()
    }
    rows = []
    for path in sorted(root.glob("*.json")):
        try:
            scenario = json.loads(path.read_text(encoding="utf-8-sig"))
            if not isinstance(scenario, dict):
                raise ValueError("scenario root is not an object")
            stats = _scenario_step_stats(scenario.get("steps", []))
            normalized_path = path.as_posix().lower()
            stage = stage_by_path.get(normalized_path) or _scenario_stage_from_name(path.stem, scenario)
            rows.append({
                "name": str(scenario.get("name", "") or path.stem),
                "stage": stage,
                "path": str(path),
                "steps": str(stats["steps"]),
                "actions": ", ".join(f"{key}={value}" for key, value in sorted(stats["actions"].items())) or "-",
                "devices": ", ".join(stats["devices"]) or "-",
                "groups": ", ".join(stats["groups"]) or "-",
                "dry_run": "required_first",
                "status": "ok",
                "note": _scenario_library_note(stage, stats),
            })
        except Exception as exc:
            rows.append({
                "name": path.stem,
                "stage": "unknown",
                "path": str(path),
                "steps": "0",
                "actions": "-",
                "devices": "-",
                "groups": "-",
                "dry_run": "blocked",
                "status": "fail",
                "note": str(exc),
            })
    return rows


def scenario_library_brief(rows: list[dict[str, str]]) -> str:
    stages: dict[str, int] = {}
    failures = 0
    for row in rows:
        stages[row.get("stage", "unknown")] = stages.get(row.get("stage", "unknown"), 0) + 1
        if row.get("status") != "ok":
            failures += 1
    stage_text = ", ".join(f"{stage}={count}" for stage, count in sorted(stages.items())) or "none"
    return f"Scenario library: total={len(rows)}, fail={failures}; {stage_text}"


def write_scenario_library_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str = "",
) -> Path:
    out_path = Path(path)
    lines = [
        "# GUI Scenario Library",
        "",
        f"- Run ID: `{run_id}`",
        "- Real iOS control verified: `False`",
        "- This library is a script selection index. It does not run scripts, write evidence, or prove real iPhone response.",
        "",
        "| Stage | Name | Status | Steps | Actions | Devices | Groups | Dry-run | Path | Note |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('stage', ''))} | {_md_cell(row.get('name', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('steps', ''))} | "
            f"{_md_cell(row.get('actions', ''))} | {_md_cell(row.get('devices', ''))} | "
            f"{_md_cell(row.get('groups', ''))} | {_md_cell(row.get('dry_run', ''))} | "
            f"`{row.get('path', '')}` | {_md_cell(row.get('note', ''))} |"
        )
    if not rows:
        lines.append("| - | none | missing | 0 | - | - | - | blocked | - | no scenario files found |")
    lines.extend([
        "",
        "## Use Rule",
        "",
        "Load a script, keep Dry Run enabled first, then let Real-run Guard decide whether a real run is allowed.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _scenario_step_stats(steps: Any) -> dict[str, Any]:
    stats: dict[str, Any] = {"steps": 0, "actions": {}, "devices": [], "groups": []}

    def visit(items: Any) -> None:
        if not isinstance(items, list):
            return
        for step in items:
            if not isinstance(step, dict):
                continue
            stats["steps"] += 1
            action = str(step.get("action", "unknown") or "unknown")
            stats["actions"][action] = stats["actions"].get(action, 0) + 1
            _append_unique(stats["devices"], str(step.get("device_id", "") or ""))
            ids = step.get("device_ids") or step.get("ids")
            if isinstance(ids, list):
                for device_id in ids:
                    _append_unique(stats["devices"], str(device_id))
            _append_unique(stats["groups"], str(step.get("group", "") or ""))
            visit(step.get("steps"))

    visit(steps)
    return stats


def _scenario_stage_from_name(name: str, scenario: dict) -> str:
    text = f"{name} {scenario.get('name', '')}".lower()
    for stage in ("p4", "p3", "p2", "p1", "p0"):
        if stage in text:
            return stage
    if "pilot_4" in text or "4_group" in text:
        return "p3"
    if "stable_10" in text or "10" in text:
        return "p4"
    return "p1"


def _scenario_library_note(stage: str, stats: dict[str, Any]) -> str:
    if stage in {"p3", "p4"}:
        return "Use only after P1/P2 pass; verify Matrix per device after run."
    if stats["actions"].get("record"):
        return "Edit record details/manual observations before real run."
    return "Dry-run first; Real-run Guard blocks unsafe real runs."


def _acceptance_check(report: dict | None, name: str) -> dict | None:
    if not report:
        return None
    for item in report.get("checks", []):
        if isinstance(item, dict) and item.get("name") == name:
            return item
    return None


def _check_status(check: dict | None) -> str:
    if not check:
        return "pending"
    return "pass" if check.get("status") == "pass" else "fail"


def _check_message(check: dict | None, fallback: str) -> str:
    if not check:
        return fallback
    return str(check.get("message", "") or fallback)


def live_probe_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build the GUI live-probe checklist without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    selected_devices = [item for item in (device_ids or []) if str(item).strip()]
    total_events = int((evidence_summary or {}).get("total", 0) or 0)
    evidence_ok = evidence_exists and total_events > 0

    rows: list[dict[str, str]] = [
        {
            "key": "devices",
            "label": "Device selection",
            "status": "pass" if len(selected_devices) >= required_devices else "fail",
            "message": f"{len(selected_devices)} selected, required >= {required_devices}",
            "action": "Register/select the target device ids before field actions.",
        }
    ]

    if route_report:
        route_ok = bool(route_report.get("ok"))
        rows.append({
            "key": "route_decision",
            "label": "Route decision",
            "status": "pass" if route_ok else "fail",
            "message": route_decision_brief(route_report),
            "action": "Use Route Edit, Checklist, then Validate with real receiver/HID/iPhone values.",
        })
    else:
        rows.append({
            "key": "route_decision",
            "label": "Route decision",
            "status": "pending",
            "message": "No validated route decision loaded for this run.",
            "action": "Click Prepare/Route Init, fill the route, then Validate.",
        })

    if doctor_report:
        overall = str(doctor_report.get("overall", "unknown")).lower()
        rows.append({
            "key": "doctor",
            "label": "Preflight doctor",
            "status": "fail" if overall == "fail" else ("warn" if overall == "warn" else "pass"),
            "message": doctor_brief(doctor_report),
            "action": "Fix fail checks before claiming P1; warn still needs operator review.",
        })
    else:
        rows.append({
            "key": "doctor",
            "label": "Preflight doctor",
            "status": "pending",
            "message": "Doctor has not been run in this GUI session.",
            "action": "Click Doctor before touching hardware.",
        })

    if scenario_summary:
        rows.append({
            "key": "scenario",
            "label": "Probe scenario",
            "status": "pass" if scenario_summary.get("ok") else "fail",
            "message": scenario_brief(scenario_summary),
            "action": "Dry-run first, then real-run only after route and doctor are clean.",
        })
    else:
        rows.append({
            "key": "scenario",
            "label": "Probe scenario",
            "status": "pending",
            "message": f"Default script: {standard_probe_script(normalized_stage)}",
            "action": "Load Probe Script and run a dry-run before real hardware.",
        })

    rows.append({
        "key": "evidence",
        "label": "Evidence JSONL",
        "status": "pass" if evidence_ok else "fail",
        "message": f"{total_events} event(s) recorded" if evidence_exists else "Evidence file is missing",
        "action": "Keep Record enabled and add metadata, screenshot, manual, and script evidence.",
    })

    for check_name, label, action in (
        ("component_traceability", "Component metadata", "Record Metadata for every target device with no placeholders."),
        ("screenshot_quality", "Screenshot quality", "Start Capture, click Screenshot, and verify non-black/non-white frames."),
        ("manual_observation", "Manual observation", "Record pass/fail only after the real iPhone visibly responds."),
        ("metrics", "Metrics samples", "Run the watchdog scenario for P2/P3/P4 stability gates."),
    ):
        check = _acceptance_check(acceptance_report, check_name)
        rows.append({
            "key": check_name,
            "label": label,
            "status": _check_status(check),
            "message": _check_message(check, "Acceptance has not been evaluated yet."),
            "action": action,
        })

    if acceptance_report:
        rows.append({
            "key": "acceptance",
            "label": "Acceptance gate",
            "status": "pass" if acceptance_report.get("ok") else "fail",
            "message": acceptance_brief(acceptance_report),
            "action": "Use Gap to convert failed checks into evidence actions.",
        })
    else:
        rows.append({
            "key": "acceptance",
            "label": "Acceptance gate",
            "status": "pending",
            "message": "Acceptance has not been evaluated yet.",
            "action": "Click Acceptance after evidence exists.",
        })

    if readiness_report:
        rows.append({
            "key": "readiness",
            "label": "Readiness audit",
            "status": "pass" if readiness_report.get("ok") else "fail",
            "message": readiness_brief(readiness_report),
            "action": "Only PASS here allows promotion to the next stage.",
        })
    else:
        rows.append({
            "key": "readiness",
            "label": "Readiness audit",
            "status": "pending",
            "message": "Readiness has not been evaluated yet.",
            "action": "Click Readiness after acceptance.",
        })

    return rows


def live_probe_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    blockers = []
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if status in {"fail", "pending"}:
            blockers.append(str(row.get("key", row.get("label", ""))))
    blocker_text = ", ".join(blockers[:3]) if blockers else "none"
    return (
        f"Live probe {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, warn={counts.get('warn', 0)}, "
        f"fail={counts.get('fail', 0)}, pending={counts.get('pending', 0)}; "
        f"blockers={blocker_text}"
    )


def write_live_probe_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    stage: str = "p1",
    run_id: str = "",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 实时探测 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This report is a GUI checklist snapshot; it does not write evidence or prove real iPhone response.",
        "",
        "## Checks",
        "",
        "| Check | Status | Message | GUI action |",
        "|---|---|---|---|",
    ]
    for row in rows:
        label = str(row.get("label", "")).replace("|", "\\|")
        status = str(row.get("status", "")).replace("|", "\\|")
        message = str(row.get("message", "")).replace("|", "\\|")
        action = str(row.get("action", "")).replace("|", "\\|")
        lines.append(f"| {label} | `{status}` | {message} | {action} |")
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "Do not move to the next stage unless Route Decision, Doctor, Acceptance, and Readiness are PASS and the operator recorded real iPhone behavior in Manual evidence.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def p1_trial_rows(
    *,
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    callback_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the operator-facing P1 real-device trial board."""
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    summary = evidence_summary or {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = 0
    if isinstance(summary.get("by_status"), dict):
        fail_events = int(summary.get("by_status", {}).get("fail", 0) or 0)
    callback_rows_list = callback_rows_data or []
    callback_warn = sum(1 for row in callback_rows_list if str(row.get("severity", "")).lower() in {"warn", "fail", "error"})

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        lane: str,
        status: str,
        operator_action: str,
        gui_action: str,
        evidence: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "lane": lane,
            "status": status,
            "operator_action": operator_action,
            "gui_action": gui_action,
            "evidence": evidence,
            "stop_rule": stop_rule,
            "method": method,
        })

    add(
        "1",
        "Bench ledger",
        "pass" if len(selected_devices) >= 1 else "fail",
        "Select exactly one real iPhone bench device and keep its HID/receiver/Hub/cable labels visible.",
        "Register/select device, then Record Metadata.",
        f"selected={len(selected_devices)}, required=1",
        "Stop if the target iPhone, HID, receiver name, Hub port, or cable cannot be uniquely identified.",
        "record_component_metadata",
    )

    if route_report is None:
        route_status = "pending"
        route_text = "Route Decision not loaded."
    else:
        route_status = "pass" if bool(route_report.get("ok")) and bool(route_report.get("ready")) else "fail"
        route_text = route_decision_brief(route_report)
    add(
        "2",
        "Route gate",
        route_status,
        "Lock receiver, capture method, HID route, iPhone model/iOS, operator, Hub, and cable before real actions.",
        "Route Init/Edit, Use Metadata, Checklist, Validate.",
        route_text,
        "Stop if placeholders, open blockers, or Allow P1 real run is not true.",
        "edit_route_decision_from_gui",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_text = "Doctor not run."
    else:
        overall = str(doctor_report.get("overall", "") or "").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_text = doctor_brief(doctor_report)
    add(
        "3",
        "Preflight",
        doctor_status,
        "Confirm local API, receiver provider, serial/HID visibility, state files, and dependencies.",
        "Doctor.",
        doctor_text,
        "Stop if doctor has fail; warn requires operator sign-off and a note in Manual evidence.",
        "run_preflight_doctor",
    )

    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    add(
        "4",
        "Receiver/capture",
        screenshot_status,
        "Start mirroring/capture, take a screenshot, and verify the frame is not black/white/invalid.",
        "Start AirPlay, Start Capture, Screenshot.",
        screenshot_text,
        "Stop if no usable frame is traceable to this iPhone.",
        "screenshot",
    )

    add(
        "5",
        "Calibration",
        "ready" if screenshot_status == "pass" else "pending",
        "Map screenshot coordinates to HID target space and pick one visible safe test point.",
        "Use Screenshot, Save calibration, then click the picked point.",
        "Requires current screenshot plus saved calibration profile.",
        "Stop if the active area, orientation, or click point is ambiguous.",
        "calibration_from_screenshot",
    )

    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    add(
        "6",
        "HID click",
        manual_status,
        "Click a visible safe point and watch the real iPhone response.",
        "Click, then Manual Record pass/fail.",
        manual_text,
        "Stop if the iPhone pointer/click does not visibly respond or the pointer sticks.",
        "click_device",
    )
    add(
        "7",
        "HID swipe",
        "ready" if manual_status == "pass" else "pending",
        "Swipe on a harmless scrollable surface and watch release behavior.",
        "Swipe, then Manual Record pass/fail with category=hid on failure.",
        "Manual observation must describe direction, release, and final screen state.",
        "Stop if press/release is wrong, scroll is inverted, or coordinates drift.",
        "swipe_device",
    )
    add(
        "8",
        "Keyboard input",
        "ready" if manual_status == "pass" else "pending",
        "Type a short ASCII probe into a controlled input field and observe focus/text.",
        "Type, then Manual Record pass/fail.",
        "Manual observation must include actual text displayed on iPhone.",
        "Stop if focus is wrong, text is missing, or unexpected keyboard language changes occur.",
        "type_text",
    )

    if not callback_rows_list:
        callback_status = "pending"
        callback_text = "No callback/log rows loaded."
    elif callback_warn:
        callback_status = "warn"
        callback_text = f"callback/log rows={len(callback_rows_list)}, warn/fail/error={callback_warn}"
    else:
        callback_status = "pass"
        callback_text = f"callback/log rows={len(callback_rows_list)}, warn/fail/error=0"
    add(
        "9",
        "Log triage",
        callback_status,
        "Attach receiver/HID logs and inspect callback rows before rerunning failures.",
        "Attach Log, Callback, Triage.",
        callback_text,
        "Stop promotion if logs show unexplained receiver, capture, HID, USB, or device failures.",
        "attach_callback_log_from_gui",
    )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_text = "Acceptance not evaluated."
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_text = acceptance_brief(acceptance_report)
    add(
        "10",
        "Acceptance",
        acceptance_status,
        "Evaluate P1 evidence and fill every listed gap before promotion review.",
        "Acceptance, Gap, Timeline, Matrix.",
        acceptance_text,
        "Stop until P1 Acceptance PASS and the evidence JSONL has no fail event.",
        "run_acceptance_from_gui",
    )

    if readiness_report is None:
        readiness_status = "pending"
        readiness_text = "Readiness not evaluated."
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_text = readiness_brief(readiness_report)
    if not evidence_exists or total_events == 0:
        readiness_status = "fail" if readiness_status == "pass" else readiness_status
        evidence_text = "evidence missing"
    else:
        evidence_text = f"events={total_events}, fail={fail_events}"
        if fail_events and readiness_status == "pass":
            readiness_status = "fail"
    add(
        "11",
        "Promotion",
        readiness_status,
        "Run Readiness and export Pack/Dashboard/XP Gap only after evidence gates are clean.",
        "Readiness, Pack, Dashboard, XP Gap.",
        f"{readiness_text}; {evidence_text}",
        "Do not claim iOS perfect control unless real-device evidence, Acceptance, and Readiness all pass.",
        "run_readiness_audit",
    )
    return rows


def p1_trial_brief(rows: list[dict[str, str]]) -> str:
    counts: dict[str, int] = {}
    first_stop = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_stop == "none" and status in {"fail", "pending"}:
            first_stop = str(row.get("lane", "") or row.get("step", ""))
    return (
        "P1 trial: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_stop={first_stop}"
    )


def write_p1_trial_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        "# GUI P1 Trial",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This trial board is an operator checklist. It does not write evidence or prove real iPhone response.",
        "",
        "## Trial Steps",
        "",
        "| # | Lane | Status | Operator action | GUI action | Evidence/status | Stop rule |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('lane', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('operator_action', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('evidence', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | Build P1 trial first | Refresh P1 Trial | - | Do not promote |")
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "P1 is reviewable only when the target iPhone has component metadata, usable screenshot evidence, manual pass observations for real click/swipe/type behavior, no unexplained callback/log failures, Acceptance PASS, and Readiness PASS.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


CONTROL_BENCH_ACTIONS = (
    {
        "action": "click",
        "label": "HID click",
        "keywords": ("hid click", "click"),
        "required": "At least one visible real-iPhone click response with Manual pass.",
        "gui_action": "Open P1 Trial / Click / Manual Record",
        "method": "show_p1_trial_from_gui",
        "stop_rule": "Stop on missing click, wrong point, stuck press, or pointer drift.",
    },
    {
        "action": "swipe",
        "label": "HID swipe",
        "keywords": ("hid swipe", "swipe"),
        "required": "At least one visible real-iPhone swipe response with release observation.",
        "gui_action": "Open P1 Trial / Swipe / Manual Record",
        "method": "show_p1_trial_from_gui",
        "stop_rule": "Stop on inverted direction, wrong distance, no release, or coordinate drift.",
    },
    {
        "action": "type",
        "label": "Keyboard input",
        "keywords": ("keyboard input", "type text", "type", "keyboard"),
        "required": "At least one real iPhone text-input observation with displayed text in the note.",
        "gui_action": "Open P1 Trial / Type / Manual Record",
        "method": "show_p1_trial_from_gui",
        "stop_rule": "Stop on wrong focus, missing text, duplicated text, or unexpected keyboard language.",
    },
)


def _control_action_from_text(text: str) -> str:
    lowered = text.lower()
    matches: list[str] = []
    for spec in CONTROL_BENCH_ACTIONS:
        if any(keyword in lowered for keyword in spec["keywords"]):
            _append_unique(matches, str(spec["action"]))
    return matches[0] if len(matches) == 1 else ""


def _control_event_action(event: dict) -> str:
    text = f"{event.get('step', '')} {flatten_event_details(event.get('details', {}))}"
    return _control_action_from_text(text)


def flatten_event_details(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        parts: list[str] = []
        for key, item in value.items():
            parts.append(str(key))
            parts.append(flatten_event_details(item))
        return " ".join(parts)
    if isinstance(value, (list, tuple, set)):
        return " ".join(flatten_event_details(item) for item in value)
    return str(value)


def _event_detail_dicts(value: Any) -> list[dict]:
    found: list[dict] = []
    if isinstance(value, dict):
        found.append(value)
        for item in value.values():
            found.extend(_event_detail_dicts(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(_event_detail_dicts(item))
    return found


def control_response_bench_rows(
    events: list[dict],
    *,
    device_ids: list[str] | None = None,
    min_manual_pass: int = 1,
) -> list[dict[str, str]]:
    """Summarize real-control evidence for click, swipe, and text lanes."""
    selected = {str(item).strip() for item in (device_ids or []) if str(item).strip()}
    buckets: dict[str, dict[str, Any]] = {}
    for spec in CONTROL_BENCH_ACTIONS:
        buckets[str(spec["action"])] = {
            "spec": spec,
            "command_count": 0,
            "command_fail": 0,
            "manual_pass": 0,
            "manual_fail": 0,
            "manual_info": 0,
            "devices": [],
            "categories": [],
            "artifacts": [],
            "last_ts": "",
            "last_step": "",
            "notes": [],
        }

    for event in events:
        action = _control_event_action(event)
        if not action or action not in buckets:
            continue
        event_devices = [
            str(item).strip()
            for item in (event.get("device_ids", []) if isinstance(event.get("device_ids", []), list) else [])
            if str(item).strip()
        ]
        if selected and event_devices and not any(device_id in selected for device_id in event_devices):
            continue
        bucket = buckets[action]
        bucket["last_ts"] = str(event.get("ts", "") or bucket["last_ts"])
        bucket["last_step"] = str(event.get("step", "") or bucket["last_step"])
        for device_id in event_devices:
            _append_unique(bucket["devices"], device_id)
        for artifact in event.get("artifacts", []) if isinstance(event.get("artifacts", []), list) else []:
            _append_unique(bucket["artifacts"], str(artifact))
        is_manual = _event_has_manual_pass(event) or (
            isinstance(event.get("details"), dict)
            and any(details.get("manual") is True for details in _event_detail_dicts(event.get("details", {})))
        )
        status = str(event.get("status", "") or "").lower()
        if is_manual:
            if status == "pass":
                bucket["manual_pass"] += 1
            elif status == "fail":
                bucket["manual_fail"] += 1
                _append_unique(bucket["categories"], failure_category(event))
            else:
                bucket["manual_info"] += 1
            details_text = flatten_event_details(event.get("details", {}))
            if details_text:
                _append_unique(bucket["notes"], details_text[:160])
        else:
            bucket["command_count"] += 1
            if status == "fail":
                bucket["command_fail"] += 1
                _append_unique(bucket["categories"], failure_category(event))

    rows: list[dict[str, str]] = []
    for action in [str(spec["action"]) for spec in CONTROL_BENCH_ACTIONS]:
        bucket = buckets[action]
        spec = bucket["spec"]
        if bucket["manual_fail"] or bucket["command_fail"]:
            status = "fail"
        elif bucket["manual_pass"] >= min_manual_pass:
            status = "pass"
        elif bucket["command_count"]:
            status = "ready"
        else:
            status = "pending"
        current = (
            f"manual_pass={bucket['manual_pass']}, manual_fail={bucket['manual_fail']}, "
            f"commands={bucket['command_count']}, command_fail={bucket['command_fail']}, "
            f"info={bucket['manual_info']}"
        )
        rows.append({
            "action": action,
            "label": str(spec["label"]),
            "status": status,
            "current": current,
            "required": str(spec["required"]),
            "devices": ", ".join(bucket["devices"]) or "-",
            "categories": ", ".join(bucket["categories"]) or "-",
            "artifacts": ", ".join(bucket["artifacts"][:3]) if bucket["artifacts"] else "-",
            "last_ts": bucket["last_ts"] or "-",
            "last_step": bucket["last_step"] or "-",
            "note": " | ".join(bucket["notes"][:2]) if bucket["notes"] else "-",
            "gui_action": str(spec["gui_action"]),
            "method": str(spec["method"]),
            "stop_rule": str(spec["stop_rule"]),
        })
    return rows


def control_response_bench_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "label")
    return (
        f"Control bench {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_control_response_bench_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 控制响应基准 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This bench audits click, swipe, and text-input observations. It does not write evidence and does not prove full iOS control by itself.",
        "",
        "## Control Lanes",
        "",
        "| Lane | Status | Current | Required evidence | Devices | Categories | Artifacts | Last step | GUI action | Stop rule |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('label', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('required', ''))} | "
            f"{_md_cell(row.get('devices', ''))} | {_md_cell(row.get('categories', ''))} | "
            f"{_md_cell(row.get('artifacts', ''))} | {_md_cell(row.get('last_step', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | no rows built | Refresh Control Bench | - | - | - | - | - | Do not promote |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "API/HID command success is not enough. Each lane needs a Manual pass recorded after the operator sees the real iPhone respond. Any fail row must keep category and artifact context before rerun.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _event_manual_marker(event: dict) -> bool:
    details = event.get("details", {})
    if str(event.get("step", "") or "").strip().lower() == "manual observation":
        return True
    if isinstance(details, dict):
        return any(item.get("manual") is True for item in _event_detail_dicts(details))
    return False


def _event_matches_selected_devices(event: dict, selected: set[str]) -> bool:
    if not selected:
        return True
    event_devices = [
        str(item).strip()
        for item in (event.get("device_ids", []) if isinstance(event.get("device_ids", []), list) else [])
        if str(item).strip()
    ]
    return not event_devices or any(device_id in selected for device_id in event_devices)


def _manual_control_event_counts(events: list[dict], selected: set[str]) -> dict[str, int]:
    counts = {
        "manual_total": 0,
        "manual_generic": 0,
        "manual_action_specific": 0,
        "generic_fail": 0,
    }
    for event in events:
        if not _event_matches_selected_devices(event, selected) or not _event_manual_marker(event):
            continue
        counts["manual_total"] += 1
        action = _control_event_action(event)
        if action:
            counts["manual_action_specific"] += 1
        else:
            counts["manual_generic"] += 1
            if str(event.get("status", "") or "").lower() == "fail":
                counts["generic_fail"] += 1
    return counts


def _control_ledger_gui_action(method: str) -> str:
    return {
        "prepare_live_probe_from_gui": "Prepare",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_evidence_timeline_from_gui": "Open Timeline",
        "run_acceptance_from_gui": "Run Acceptance",
        "run_readiness_audit": "Run Readiness",
        "write_evidence_pack_from_gui": "Export Pack",
    }.get(method, method)


def control_evidence_ledger_rows(
    events: list[dict],
    *,
    run_id: str = "",
    stage: str = "p1",
    device_ids: list[str] | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    control_rows_data: list[dict[str, str]] | None = None,
    evidence_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build a lane-separated real-control evidence ledger without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id or normalized_stage).safe_run_id
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    selected = set(selected_devices)
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    control_rows = control_rows_data or control_response_bench_rows(
        events,
        device_ids=selected_devices,
        min_manual_pass=1,
    )
    by_label = {str(row.get("label", "") or ""): row for row in control_rows}
    manual_counts = _manual_control_event_counts(events, selected)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        lane: str,
        status: str,
        current: str,
        minimum_evidence: str,
        record_path: str,
        next_action: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "lane": lane,
            "status": status,
            "current": current,
            "minimum_evidence": minimum_evidence,
            "record_path": record_path,
            "next_action": next_action,
            "gui_action": _control_ledger_gui_action(method),
            "stop_rule": stop_rule,
            "method": method,
        })

    if not run_id.strip() or len(selected_devices) < required_devices:
        scope_status = "fail"
    elif evidence_exists and total_events > 0:
        scope_status = "pass"
    else:
        scope_status = "pending"
    add(
        "1",
        "Run and device scope",
        scope_status,
        (
            f"run_id={safe_run_id}; selected={len(selected_devices)}, required={required_devices}; "
            f"events={total_events}; evidence={'present' if evidence_exists else 'missing'}"
        ),
        "One same-run JSONL, exact physical iPhone/device id, receiver route, HID route, Hub port, cable, and operator.",
        str(evidence_path or Path("evidence") / f"{safe_run_id}.jsonl"),
        "Prepare the run and record component metadata before interpreting control evidence.",
        "Stop if device identity, route, HID, or evidence path is ambiguous.",
        "prepare_live_probe_from_gui",
    )

    for step, label, prompt in (
        (
            "2",
            "HID click",
            "Record target, before state, after state, visible pointer/click behavior, and artifact path.",
        ),
        (
            "3",
            "HID swipe",
            "Record direction, distance, release, before/after screen movement, and artifact path.",
        ),
        (
            "4",
            "Keyboard input",
            "Record focused field, expected text, actual visible text, keyboard/input state, and artifact path.",
        ),
    ):
        control = by_label.get(label, {})
        status = str(control.get("status", "pending") or "pending")
        current = str(control.get("current", "") or f"{label} action-specific Manual observation missing")
        artifacts = str(control.get("artifacts", "") or "-")
        last_step = str(control.get("last_step", "") or "-")
        note = str(control.get("note", "") or "-")
        add(
            step,
            label,
            status,
            f"{current}; last={last_step}; note={note}",
            f"{control.get('required', '') or 'Action-specific Manual pass required.'} {prompt}",
            f"Manual step should name `{label}`; artifacts={artifacts}",
            "Use P1 Trial or this ledger Record Pass/Fail while watching the physical iPhone.",
            str(control.get("stop_rule", "") or "Stop if visible real-iPhone behavior does not match the command."),
            "show_p1_trial_from_gui",
        )

    lane_pass = sum(1 for label in ("HID click", "HID swipe", "Keyboard input") if by_label.get(label, {}).get("status") == "pass")
    if manual_counts["manual_generic"] == 0:
        generic_status = "pass" if lane_pass == 3 else "pending"
    elif lane_pass == 0:
        generic_status = "fail"
    elif lane_pass < 3 or manual_counts["generic_fail"]:
        generic_status = "warn"
    else:
        generic_status = "pass"
    add(
        "5",
        "Generic Manual quarantine",
        generic_status,
        (
            f"manual_total={manual_counts['manual_total']}, action_specific={manual_counts['manual_action_specific']}, "
            f"generic={manual_counts['manual_generic']}, generic_fail={manual_counts['generic_fail']}, lane_pass={lane_pass}/3"
        ),
        "Generic Manual rows are context only. Click, swipe, and text each need their own action-specific Manual pass.",
        "Timeline -> Manual Observation rows without HID click/HID swipe/Keyboard input wording",
        "Convert generic notes into three explicit lane records, or keep them only as context.",
        "Stop promotion if one broad Manual pass is being used to close multiple control lanes.",
        "show_evidence_timeline_from_gui",
    )

    acceptance_status = "pending" if acceptance_report is None else "pass" if acceptance_report.get("ok") else "fail"
    acceptance_text = acceptance_brief(acceptance_report) if acceptance_report else "acceptance not evaluated"
    readiness_status = "pending" if readiness_report is None else "pass" if readiness_report.get("ok") else "fail"
    readiness_text = readiness_brief(readiness_report) if readiness_report else "readiness not evaluated"
    if lane_pass == 3 and acceptance_status == "pass" and readiness_status == "pass" and real_ios_verified and fail_events == 0:
        claim_status = "pass"
    elif lane_pass == 3:
        claim_status = "warn"
    else:
        claim_status = "fail"
    add(
        "6",
        "Claim boundary",
        claim_status,
        (
            f"lane_pass={lane_pass}/3; fail_events={fail_events}; {acceptance_text}; "
            f"{readiness_text}; real_ios_verified={real_ios_verified}"
        ),
        "Same-run click/swipe/text Manual pass, screenshot quality, Acceptance PASS, Readiness PASS, and exact device/iOS scope.",
        "Control ledger export, JSONL, screenshots/recordings, Acceptance, Readiness, Evidence Pack",
        "Run Acceptance, Readiness, Pack, and hand off only the evidence-backed claim.",
        "Stop iOS perfect-control, broad compatibility, or XP parity wording unless every ledger row is clean.",
        "run_readiness_audit" if claim_status != "fail" else "run_acceptance_from_gui",
    )
    return rows


def control_evidence_ledger_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "lane")
    return (
        f"Control ledger {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_control_evidence_ledger_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 控制证据台账 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This ledger audits same-run real-control evidence. It does not write evidence by itself and does not prove iPhone response.",
        "",
        "## Ledger Rows",
        "",
        "| # | Lane | Status | Current | Minimum evidence | Record path | GUI action | Next action | Stop rule |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('lane', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('minimum_evidence', ''))} | {_md_cell(row.get('record_path', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Ledger | - | - | - | Do not promote |")
    lines.extend([
        "",
        "## Lane Separation Rule",
        "",
        "A generic Manual pass is not enough. Click, swipe, and text must each have an action-specific Manual pass recorded after the operator watches the physical iPhone and keeps the useful artifact/log path.",
        "",
        "## Operator Prompts",
        "",
        "- HID click: target, before state, after state, pointer/click behavior, artifact.",
        "- HID swipe: direction, distance, release, before/after movement, artifact.",
        "- Keyboard input: focused field, expected text, actual visible text, input method state, artifact.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _p1_trial_failure_category(lane: str) -> str:
    text = str(lane or "").lower()
    if "receiver" in text or "capture" in text:
        return "capture"
    if "hid" in text or "keyboard" in text or "calibration" in text:
        return "hid"
    if "log" in text:
        return "uncategorized"
    if "route" in text:
        return "uncategorized"
    return "uncategorized"


def stage_dashboard_rows(
    *,
    target_stage: str = "p1",
    device_ids: list[str] | None = None,
    readiness_report: dict | None = None,
    acceptance_reports: dict[str, dict] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build the P0-P4 GUI stage dashboard without writing evidence."""
    normalized_target = target_stage.lower().strip() or "p1"
    if normalized_target not in STAGE_DASHBOARD_ORDER:
        normalized_target = "p1"
    selected_devices = [item for item in (device_ids or []) if str(item).strip()]
    acceptance_by_stage = acceptance_reports or {}
    stage_status = readiness_report.get("stage_status", {}) if isinstance(readiness_report, dict) else {}
    evidence_total = int((evidence_summary or {}).get("total", 0) or 0)
    fail_total = int((evidence_summary or {}).get("by_status", {}).get("fail", 0) or 0)
    metric_total = int((evidence_summary or {}).get("metrics", {}).get("count", 0) or 0)
    evidence_text = (
        f"events={evidence_total}, fail={fail_total}, metrics={metric_total}"
        if evidence_exists
        else "missing"
    )

    rows = []
    for stage in STAGE_DASHBOARD_ORDER:
        readiness_item = stage_status.get(stage, {}) if isinstance(stage_status, dict) else {}
        if isinstance(readiness_item, dict) and readiness_item:
            status = "pass" if readiness_item.get("ok") else "fail"
        elif stage == "p0":
            status = "pending"
        else:
            report = acceptance_by_stage.get(stage)
            status = "pass" if isinstance(report, dict) and report.get("ok") else "pending"

        blockers = _stage_dashboard_blockers(
            stage=stage,
            selected_devices=selected_devices,
            readiness_report=readiness_report,
            acceptance_report=acceptance_by_stage.get(stage),
            route_report=route_report,
            doctor_report=doctor_report,
            evidence_exists=evidence_exists,
        )
        if blockers and status == "pass":
            status = "fail"
        rows.append({
            "stage": stage,
            "label": STAGE_DASHBOARD_LABELS[stage],
            "status": status,
            "selected_devices": str(len(selected_devices)),
            "required_devices": str(STAGE_DEVICE_REQUIREMENTS.get(stage, 1)),
            "evidence": evidence_text,
            "gate": STAGE_DASHBOARD_GATES[stage],
            "script": STAGE_PRIMARY_SCENARIOS.get(stage, ""),
            "blockers": ", ".join(blockers[:4]) if blockers else "none",
            "next_action": _stage_dashboard_next_action(stage, blockers),
            "current": "yes" if stage == normalized_target else "",
        })
    return rows


def stage_dashboard_brief(rows: list[dict[str, str]], *, target_stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    normalized_target = target_stage.lower().strip() or "p1"
    current = next((row for row in rows if row.get("stage") == normalized_target), None)
    if current:
        current_text = f"{normalized_target.upper()} {current.get('status', 'pending')}"
        blockers = str(current.get("blockers", "none") or "none")
    else:
        current_text = f"{normalized_target.upper()} pending"
        blockers = "none"
    return (
        f"Stage dashboard {normalized_target.upper()}: "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; current={current_text}; blockers={blockers}"
    )


def write_stage_dashboard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    target_stage: str = "p1",
    run_id: str = "",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    claims = (readiness_report or {}).get("claims", {}) if isinstance(readiness_report, dict) else {}
    real_ios_verified = bool(claims.get("real_ios_control_verified"))
    group_verified = bool(claims.get("ios_group_control_verified"))
    lines = [
        f"# GUI 阶段仪表盘 {target_stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        f"- iOS group control verified: `{group_verified}`",
        "- This dashboard is a GUI snapshot; it does not write evidence or prove real iPhone response.",
        "",
        "## Stage Matrix",
        "",
        "| Stage | Current | Status | Devices | Evidence | Gate | Script | Blockers | Next action |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        devices = f"{row.get('selected_devices', '0')}/{row.get('required_devices', '0')}"
        values = [
            row.get("stage", "").upper(),
            row.get("current", ""),
            row.get("status", ""),
            devices,
            row.get("evidence", ""),
            row.get("gate", ""),
            row.get("script", ""),
            row.get("blockers", ""),
            row.get("next_action", ""),
        ]
        escaped = [str(value).replace("|", "\\|") for value in values]
        lines.append(
            f"| {escaped[0]} | {escaped[1]} | `{escaped[2]}` | {escaped[3]} | "
            f"{escaped[4]} | {escaped[5]} | `{escaped[6]}` | {escaped[7]} | {escaped[8]} |"
        )
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "Do not promote beyond the current stage unless the current row is PASS, Route Decision is PASS, Doctor has no fail, Acceptance is PASS, Readiness is PASS, and Manual evidence records real iPhone behavior.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _acceptance_check_line(report: dict | None, check_name: str) -> tuple[str, str]:
    if not isinstance(report, dict) or not report:
        return "pending", f"{check_name} has not been evaluated."
    for check in report.get("checks", []) or []:
        if not isinstance(check, dict) or check.get("name") != check_name:
            continue
        status = str(check.get("status", "pending") or "pending").lower()
        if status == "ok":
            status = "pass"
        if status not in {"pass", "fail", "warn", "pending"}:
            status = "pending"
        message = str(check.get("message", "") or f"{check_name} evaluated")
        return status, message
    if report.get("ok"):
        return "pass", f"{check_name} is not required by this gate."
    return "pending", f"{check_name} check not found in acceptance report."


def field_runbook_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    command_queue_items: list[dict] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the operator-facing field runbook for the current GUI stage."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    template_rows = template_asset_rows_data or []
    queue_count = len(command_queue_rows(command_queue_items or []))
    guard = real_run_guard_report(
        stage=normalized_stage,
        device_ids=selected_devices,
        route_report=route_report,
        doctor_report=doctor_report,
    )

    rows: list[dict[str, str]] = []

    def add(
        phase: str,
        status: str,
        objective: str,
        gui_action: str,
        evidence: str,
        stop_rule: str,
    ) -> None:
        rows.append({
            "phase": phase,
            "status": status,
            "objective": objective,
            "gui_action": gui_action,
            "evidence": evidence,
            "stop_rule": stop_rule,
        })

    add(
        "Bench scope",
        "pass" if len(selected_devices) >= required_devices else "fail",
        f"Select the target bench devices for {normalized_stage.upper()} ({len(selected_devices)}/{required_devices}).",
        "Register/select devices, then Record Metadata.",
        "Device ids plus receiver/HID/iPhone component metadata in JSONL.",
        "Stop if target device count is below the stage requirement.",
    )

    if route_report is None:
        route_status = "pending"
        route_text = "Route Decision has not been loaded or validated."
    else:
        route_status = "pass" if bool(route_report.get("ok")) and bool(route_report.get("ready")) else "fail"
        route_text = route_decision_brief(route_report)
    add(
        "Route ledger",
        route_status,
        "Lock receiver, capture, HID, iPhone, hub, cable, and operator ledger before field actions.",
        "Route Init/Edit, Use Metadata, Checklist, Validate.",
        route_text,
        "Stop real runs until Route Decision is ok and ready with no placeholders or open blockers.",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_text = "Doctor has not been run for this run_id."
    else:
        overall = str(doctor_report.get("overall", "") or "").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_text = doctor_brief(doctor_report)
    add(
        "Preflight doctor",
        doctor_status,
        "Check Python modules, receiver provider, ports, writable evidence, and local API health.",
        "Doctor.",
        doctor_text,
        "Stop if doctor has fail before touching real devices.",
    )

    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    add(
        "Receiver/capture",
        screenshot_status,
        "Bring up AirPlay/receiver/capture and prove the screenshot is usable.",
        "Start AirPlay, Start Capture, Screenshot, Timeline.",
        screenshot_text,
        "Stop if screenshot is missing, black/white/invalid, or not traceable to the device.",
    )

    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    add(
        "HID/manual control",
        manual_status,
        "Run click/swipe/type and record what the real iPhone did.",
        "Click, Swipe, Type, Manual Record.",
        manual_text,
        "Stop promotion if there is no manual pass observation from a real iPhone.",
    )

    if not template_rows:
        template_status = "pending"
        template_text = "No template asset index has been refreshed."
    else:
        template_fail = len([row for row in template_rows if row.get("status") == "fail"])
        template_ok = len([row for row in template_rows if row.get("status") == "ok"])
        template_status = "fail" if template_fail else "pass" if template_ok else "pending"
        template_text = f"templates ok={template_ok}, fail={template_fail}, total={len(template_rows)}"
    add(
        "Vision assets",
        template_status,
        "Prepare reusable templates/colors/OCR probes before repeated GUI automation.",
        "Assets, Save Crop, Find, Find Color, OCR, Find Text.",
        template_text,
        "Stop template-driven runs if assets are too small or low texture.",
    )

    if scenario_summary is None:
        scenario_status = "ready" if queue_count else "pending"
        scenario_text = f"Command queue items={queue_count}; scenario summary not run."
    else:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_text = scenario_brief(scenario_summary)
    add(
        "Probe scenario",
        scenario_status,
        "Dry-run the stage script or GUI-built queue, then keep the exact JSON for repeatability.",
        "Scenario Library, Dry Run, Command Queue Save JSON, Run.",
        scenario_text,
        "Stop before real run if dry-run or queue validation fails.",
    )

    add(
        "Real-run guard",
        "pass" if guard.get("ok") else "fail",
        "Verify the GUI is allowed to disable dry-run for the current stage.",
        "Run Scenario or Command Queue with Dry Run disabled.",
        real_run_guard_brief(guard),
        "Stop if guard blocks route, doctor, or device scope.",
    )

    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    if metrics_status == "pending" and normalized_stage == "p1":
        metrics_text = f"metrics samples={metrics_count}; optional for P1 but required for later stability stages."
    add(
        "Stability metrics",
        metrics_status,
        "Record host/device stability signals before P2/P3/P4 promotion.",
        "Run P2/P3/P4 watchdog scenario or a metrics step.",
        metrics_text,
        "Stop P2/P3/P4 promotion if metrics are absent or show resource pressure.",
    )

    if not evidence_exists or total_events == 0:
        triage_status = "pending"
        triage_text = "No evidence JSONL events loaded."
    else:
        triage_status = "fail" if fail_events else "pass"
        triage_text = f"events={total_events}, fail={fail_events}"
    add(
        "Review and triage",
        triage_status,
        "Inspect event order, affected devices, artifacts, and failure categories.",
        "Timeline, Matrix, Triage, Review.",
        triage_text,
        "Stop promotion until root failed events are explained or re-run cleanly.",
    )

    acceptance_ok = isinstance(acceptance_report, dict) and bool(acceptance_report.get("ok"))
    readiness_ok = isinstance(readiness_report, dict) and bool(readiness_report.get("ok"))
    if acceptance_ok and readiness_ok:
        promotion_status = "pass"
    elif acceptance_report is None and readiness_report is None:
        promotion_status = "pending"
    else:
        promotion_status = "fail"
    add(
        "Promotion gate",
        promotion_status,
        "Decide whether the stage can advance without overstating real iOS control.",
        "Acceptance, Gap, Readiness, Dashboard, Pack, XP Gap.",
        f"{acceptance_brief(acceptance_report or {})}; {readiness_brief(readiness_report or {})}",
        "Only promote when Acceptance and Readiness pass and manual evidence proves real iPhone behavior.",
    )
    return rows


def field_runbook_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    first_stop = next(
        (row.get("phase", "") for row in rows if row.get("status") in {"fail", "pending"}),
        "none",
    )
    return (
        f"Field runbook {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}; first_stop={first_stop}"
    )


def write_field_runbook_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 现场手册 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This runbook is an operator guide. It does not write evidence or prove real iPhone response.",
        "",
        "## Steps",
        "",
        "| Phase | Status | Objective | GUI action | Evidence | Stop rule |",
        "|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('phase', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('objective', ''))} | {_md_cell(row.get('gui_action', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | `pending` | Build GUI runbook first | Refresh Runbook | - | Do not promote |")
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "Promotion requires clean JSONL evidence, Acceptance PASS, Readiness PASS, usable screenshot quality, component metadata, and manual real-iPhone observation. For P3/P4, every target device must be traceable in Matrix.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def stage_sop_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    command_queue_items: list[dict] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the stage SOP board rows without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    queue_rows = command_queue_rows(command_queue_items or [])
    template_rows = template_asset_rows_data or []

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        workstream: str,
        status: str,
        current: str,
        next_action: str,
        evidence: str,
    ) -> None:
        rows.append({
            "step": step,
            "workstream": workstream,
            "status": status,
            "current": current,
            "next_action": next_action,
            "evidence": evidence,
        })

    device_status = "pass" if len(selected_devices) >= required_devices else "fail"
    add(
        "1",
        "Device scope",
        device_status,
        f"selected={len(selected_devices)}, required={required_devices}",
        "Register/select devices and record component metadata.",
        "Record Metadata evidence with receiver/HID/iPhone fields.",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route decision not loaded"
    else:
        route_status = "pass" if route_report.get("ready") and route_report.get("ok") is not False else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "2",
        "Route decision",
        route_status,
        route_current,
        "Use Route Init/Edit, fill real receiver/HID/iPhone values, then Validate.",
        "Route Decision JSON/report and route decision evidence event.",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_current = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "unknown") or "unknown").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_current = doctor_brief(doctor_report)
    add(
        "3",
        "Preflight doctor",
        doctor_status,
        doctor_current,
        "Run Doctor and fix server, route, binary, serial, and dependency failures.",
        "Doctor report artifact.",
    )

    if not evidence_exists:
        evidence_status = "pending"
        evidence_current = "no JSONL evidence file"
    elif total_events <= 0:
        evidence_status = "fail"
        evidence_current = "JSONL exists but has zero events"
    elif fail_events:
        evidence_status = "fail"
        evidence_current = f"events={total_events}, fail={fail_events}"
    else:
        evidence_status = "pass"
        evidence_current = f"events={total_events}, fail=0"
    add(
        "4",
        "Capture/control evidence",
        evidence_status,
        evidence_current,
        "Record Screenshot, command result, and Manual real-iPhone observation evidence.",
        "JSONL events with screenshot quality and manual observation.",
    )

    if scenario_summary:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_current = scenario_brief(scenario_summary)
        scenario_action = "Use Gap after failures; rerun only after route and doctor blockers are fixed."
    elif queue_rows:
        scenario_status = "ready"
        scenario_current = command_queue_brief(command_queue_items or [])
        scenario_action = "Save JSON, dry-run the queue, then run real only after P1 route is allowed."
    else:
        scenario_status = "pending"
        scenario_current = "no scenario/queue result"
        scenario_action = "Load Probe Script or build Command Queue for the current stage."
    add(
        "5",
        "Probe script",
        scenario_status,
        scenario_current,
        scenario_action,
        "Scenario summary event and GUI queue JSON when using queued actions.",
    )

    template_fail = sum(1 for row in template_rows if row.get("status") == "fail")
    template_ok = sum(1 for row in template_rows if row.get("status") == "ok")
    if not template_rows:
        template_status = "pending"
        template_current = "no template asset index"
    elif template_fail:
        template_status = "fail"
        template_current = f"ok={template_ok}, fail={template_fail}"
    else:
        template_status = "pass"
        template_current = f"ok={template_ok}, fail=0"
    add(
        "6",
        "Vision assets",
        template_status,
        template_current,
        "Open Assets, replace low-texture/small templates, then Write Index.",
        "Template asset index and failure screenshots for misses.",
    )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_current = "acceptance not evaluated"
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_current = acceptance_brief(acceptance_report)
    add(
        "7",
        "Acceptance gate",
        acceptance_status,
        acceptance_current,
        "Run Acceptance; if FAIL, run Gap and add the listed evidence.",
        "Acceptance report and optional acceptance gap report.",
    )

    if readiness_report is None:
        readiness_status = "pending"
        readiness_current = "readiness not evaluated"
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_current = readiness_brief(readiness_report)
    add(
        "8",
        "Promotion review",
        readiness_status,
        readiness_current,
        "Run Readiness, export Dashboard/Pack/Session, then promote only with real iPhone evidence.",
        "Readiness report, stage dashboard, evidence pack, and session snapshot.",
    )
    return rows


def stage_sop_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    blockers = [
        row.get("workstream", "")
        for row in rows
        if row.get("status") in {"fail", "pending"}
    ]
    blocker_text = ", ".join(blockers[:3]) if blockers else "none"
    return (
        f"SOP board {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; blockers={blocker_text}"
    )


def stage_sop_next_command(row: dict, *, queue_has_items: bool = False) -> dict[str, str]:
    """Return the primary GUI command for a SOP row."""
    workstream = str(row.get("workstream", "") or "").strip()
    status = str(row.get("status", "") or "").strip().lower()
    if workstream == "Device scope":
        return {
            "label": "Record Metadata",
            "method": "record_component_metadata",
            "reason": "write component metadata into the current evidence run",
        }
    if workstream == "Route decision":
        return {
            "label": "Edit Route",
            "method": "edit_route_decision_from_gui",
            "reason": "fill and validate real receiver/HID/iPhone route values",
        }
    if workstream == "Preflight doctor":
        return {
            "label": "Run Doctor",
            "method": "run_preflight_doctor",
            "reason": "check service, receiver, serial, route, and local dependencies",
        }
    if workstream == "Capture/control evidence":
        return {
            "label": "Screenshot",
            "method": "screenshot",
            "reason": "capture a frame and record screenshot quality before control claims",
        }
    if workstream == "Probe script":
        if queue_has_items or status == "ready":
            return {
                "label": "Run Queue",
                "method": "run_command_queue_from_gui",
                "reason": "execute the GUI-built command queue through ScriptRunner",
            }
        return {
            "label": "Load Probe Script",
            "method": "load_probe_script_from_gui",
            "reason": "load the stage default dry-run scenario",
        }
    if workstream == "Vision assets":
        return {
            "label": "Open Assets",
            "method": "show_template_asset_manager",
            "reason": "review template size and texture quality",
        }
    if workstream == "Acceptance gate":
        return {
            "label": "Run Acceptance",
            "method": "run_acceptance_from_gui",
            "reason": "evaluate the current JSONL evidence against the selected gate",
        }
    if workstream == "Promotion review":
        if status == "pass":
            return {
                "label": "Export Session",
                "method": "write_gui_session_snapshot_from_gui",
                "reason": "export a handoff snapshot after readiness has passed",
            }
        return {
            "label": "Run Readiness",
            "method": "run_readiness_audit",
            "reason": "evaluate whether the stage can be promoted",
        }
    return {
        "label": "Refresh SOP",
        "method": "refresh_live_probe_status",
        "reason": "refresh the live state before choosing an action",
    }


def write_stage_sop_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
) -> Path:
    out_path = Path(path)
    lines = [
        f"# GUI SOP 面板 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        "- Real iOS control verified: `False`",
        "- This SOP board is an execution guide and review index. It does not write evidence or prove real iPhone response.",
        "",
        "## Stage Steps",
        "",
        "| # | Workstream | Status | Current | Primary GUI command | Next action | Evidence to keep |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        command = stage_sop_next_command(row)
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('workstream', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(command.get('label', ''))} | "
            f"{_md_cell(row.get('next_action', ''))} | {_md_cell(row.get('evidence', ''))} |"
        )
    lines.extend([
        "",
        "## Promotion Rule",
        "",
        "A stage is reviewable only when Route Decision, Doctor, Acceptance, and Readiness are PASS and manual evidence records real iPhone behavior. For P3/P4, every selected device must have per-device evidence and failure isolation notes.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


