def xp_architecture_map_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build an XP architecture map from public signals to local proof gates."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")

    rows: list[dict[str, str]] = []
    for topic in XP_ARCHITECTURE_LAYERS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        )

        if key == "product_boundary":
            if not evidence_exists:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; product route is architecture only until field evidence exists"
            elif acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "ready")
                current = f"{current}; current stage can be described narrowly, not as broad XP parity"
            else:
                status = _worst_status(doc_status, "warn" if total_events else "pending")
                current = f"{current}; source/model claims remain outside local proof"
        elif key == "hardware_usb_hid":
            if not real_ios_verified:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; HID/iPhone response not proven; XP hardware/4.4/auto-binding unverified"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "warn")
                current = f"{current}; generic HID can be current-stage ready, XP hardware parity still needs side-by-side evidence"
            else:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; real response exists but XP Gap HID={gap_status or 'unknown'}"
        elif key == "projection_receiver":
            if doctor_failed or (route_report is not None and not route_ready):
                status = _worst_status(doc_status, "fail")
                current = f"{current}; receiver route or Doctor blocks projection"
            elif route_ready and doctor_clean and screenshot_status == "pass" and not fail_events:
                status = _worst_status(doc_status, "ready")
                current = f"{current}; receiver/capture usable for current run, but Windows/wired/hard-decode parity separate"
            elif route_ready or doctor_clean:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; receiver path partially ready but screenshot proof is incomplete"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; receiver route not locked"
        elif key == "capture_vision":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; no real screenshot/vision artifacts"
            elif screenshot_status == "fail" or fail_events:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; visual lane has failed evidence that must be replayed"
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready" if gap_status != "fail" else "warn")
                current = f"{current}; screenshot proof exists, vision/OCR assets still need replay discipline"
            else:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; evidence exists but screenshot_quality is not pass"
        elif key == "kernel_api":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "warn")
                current = f"{current}; XP Gap/API audit not supplied"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current = f"{current}; protocol layer covered by local tests, hardware truth still downstream"
            else:
                status = _worst_status(doc_status, gap_status or "warn")
                current = f"{current}; XP Gap API status={gap_status or 'unknown'}"
        elif key == "python_sdk":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; SDK/API drift not compared with XP Gap"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current = f"{current}; helper compatibility is local, not hardware proof"
            else:
                status = _worst_status(doc_status, "warn" if gap_status == "warn" else "fail")
                current = f"{current}; SDK/script runtime gap={gap_status or 'unknown'}"
        elif key == "console_gui":
            status = _worst_status(doc_status, "ready")
            current = f"{current}; GUI can guide operators but exports are not evidence"
        elif key == "evidence_readiness":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
                current = f"{current}; evidence gates support current stage only"
            elif evidence_exists and total_events:
                status = _worst_status(doc_status, "fail" if fail_events else "warn")
                current = f"{current}; component={component_text}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}"
            else:
                status = _worst_status(doc_status, "fail")
                current = f"{current}; no JSONL evidence for real iPhone control"
        elif key == "group_ops":
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0 or metric_events == 0:
                    status = _worst_status(doc_status, "fail")
                    current = f"{current}; {normalized_stage.upper()} needs per-device evidence and metrics"
                elif fail_events:
                    status = _worst_status(doc_status, "fail")
                    current = f"{current}; scale blocked by failed per-device evidence"
                else:
                    status = _worst_status(doc_status, "ready" if readiness_ok else "warn")
                    current = f"{current}; group layer review applies to exact device count only"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{current}; group ops intentionally delayed until P1/P2 proof"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "layer": str(topic["layer"]),
            "status": status,
            "xp_gap_status": gap_status or "-",
            "xp_signal": str(topic["xp_signal"]),
            "principle": str(topic["principle"]),
            "local_surface": str(topic["local_surface"]),
            "current": current,
            "proof_gate": str(topic["proof_gate"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "gui_action": _xp_architecture_gui_action(method),
            "method": method,
        })
    return rows


def xp_architecture_map_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "layer", statuses={"fail", "pending", "warn"})
    return (
        f"XP architecture {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_architecture_map_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Architecture Map {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This map explains the inferred XP architecture and local proof gates. It does not write JSONL evidence, does not prove real iPhone response, and does not prove XP parity.",
        "",
        "## Architecture Layers",
        "",
        "| Layer | Status | XP Gap | Public signal | Inferred principle | Local surface | Current local state | Proof gate | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('layer', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"`{_md_cell(row.get('xp_gap_status', ''))}` | {_md_cell(row.get('xp_signal', ''))} | "
            f"{_md_cell(row.get('principle', ''))} | {_md_cell(row.get('local_surface', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('proof_gate', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('source', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | `-` | no rows built | Refresh XP Arch | - | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Use XP Arch before Core, Roadmap, and XP Gap reviews. Architecture rows explain how the system should be built; only same-run field evidence, Acceptance, Readiness, logs, and exact device/iOS coverage can close a capability claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


