def _readiness_check_line(report: dict | None, check_name: str) -> tuple[str, str]:
    if not isinstance(report, dict) or not report:
        return "pending", f"{check_name} has not been evaluated."
    for check in report.get("checks", []) or []:
        if not isinstance(check, dict) or check.get("name") != check_name:
            continue
        status = str(check.get("status", "pending") or "pending").lower()
        if status == "ok":
            status = "pass"
        if status not in {"pass", "fail", "warn", "pending"}:
            status = "pending"
        return status, str(check.get("message", "") or f"{check_name} checked")
    if check_name == "target stage":
        return ("pass" if report.get("ok") else "fail"), readiness_brief(report)
    return "pending", f"{check_name} check not found in readiness report."


def _proof_map_next_command(key: str, *, run_id: str, stage: str, evidence_path: str | Path) -> str:
    safe_run_id = ValidationRecorder(run_id or stage).safe_run_id
    evidence_text = str(evidence_path or Path("evidence") / f"{safe_run_id}.jsonl")
    route_text = str(Path("evidence") / f"{safe_run_id}_route_decision.json")
    stage_token = stage.lower().strip() or "p1"
    if key == "run_scope":
        return f".\\.venv\\Scripts\\python -m imouse.field_packet --stage {stage_token} --run-id {safe_run_id}"
    if key == "route_doctor":
        return f".\\.venv\\Scripts\\python -m imouse.doctor --route-decision {route_text} --json"
    if key in {"acceptance_gate", "evidence_exists", "no_fail_events", "device_traceability", "component_traceability", "screenshot_quality", "manual_observation", "metrics"}:
        return (
            f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_text} --gate {stage_token} "
            f"--markdown evidence\\{safe_run_id}_{stage_token}_acceptance.md "
            f"--gap-markdown evidence\\{safe_run_id}_{stage_token}_gap.md"
        )
    if key == "readiness_gate":
        return (
            f".\\.venv\\Scripts\\python -m imouse.readiness --target {stage_token} "
            f"--evidence {evidence_text} --markdown evidence\\{safe_run_id}_readiness.md"
        )
    if key == "lane_separation":
        return f"Open Ctrl Ledger, record HID click/HID swipe/Keyboard input Manual rows, then rerun Acceptance and Readiness for {safe_run_id}."
    if key == "claim_boundary":
        return f"Export Evidence Pack and limit claims to the exact {stage_token.upper()} device/iOS/receiver/HID scope."
    return ".\\.venv\\Scripts\\python -m imouse.gui"


def acceptance_proof_map_rows(
    *,
    run_id: str,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    control_ledger_rows_data: list[dict[str, str]] | None = None,
    evidence_path: str | Path = "",
) -> list[dict[str, str]]:
    """Map each acceptance/readiness proof requirement to a GUI action."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id or normalized_stage).safe_run_id
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = (
        int(summary.get("metrics", {}).get("count", 0) or 0)
        if isinstance(summary.get("metrics"), dict)
        else 0
    )
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_status = "pass" if doctor_overall == "ok" else "warn" if doctor_overall == "warn" else "fail" if doctor_overall else "pending"
    route_status = "pass" if route_ready else "fail" if route_report is not None else "pending"
    acceptance_status = "pending" if acceptance_report is None else "pass" if acceptance_report.get("ok") else "fail"
    readiness_status = "pending" if readiness_report is None else "pass" if readiness_report.get("ok") else "fail"
    artifact_by_name = {
        str(row.get("name", "") or ""): row
        for row in (artifact_rows or [])
        if isinstance(row, dict)
    }
    ledger_by_lane = {
        str(row.get("lane", "") or ""): row
        for row in (control_ledger_rows_data or [])
        if isinstance(row, dict)
    }
    lane_pass = sum(
        1
        for lane in ("HID click", "HID swipe", "Keyboard input")
        if ledger_by_lane.get(lane, {}).get("status") == "pass"
    )
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")

    rows: list[dict[str, str]] = []
    for topic in ACCEPTANCE_PROOF_TOPICS:
        key = str(topic["key"])
        check = str(topic["check"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        gap_action = GAP_ACTIONS.get(check, {})
        status = "pending"
        current = ""

        if key == "run_scope":
            if not run_id.strip() or len(selected_devices) < required_devices:
                status = "fail"
            elif evidence_exists and total_events > 0:
                status = "pass"
            else:
                status = "pending"
            current = (
                f"run_id={safe_run_id}; selected={len(selected_devices)}, required={required_devices}; "
                f"evidence={'present' if evidence_exists else 'missing'}; events={total_events}"
            )
        elif key == "route_doctor":
            status = _worst_status(route_status, doctor_status)
            current = f"route={route_status}; doctor={doctor_overall or '-'}; route_ready={route_ready}"
        elif check in GAP_ACTIONS:
            check_status, check_text = _acceptance_check_line(acceptance_report, check)
            status = check_status
            if key == "evidence_exists" and not evidence_exists:
                status = "fail"
            if key == "no_fail_events" and evidence_exists and total_events > 0 and fail_events == 0:
                status = "pass" if check_status != "fail" else "fail"
            if key == "metrics" and normalized_stage == "p1" and check_status == "pass":
                status = "ready"
            current = check_text
        elif key == "lane_separation":
            if lane_pass == 3 and real_ios_verified and fail_events == 0:
                status = "pass"
            elif lane_pass == 3 or manual_status == "pass":
                status = "warn"
            elif evidence_exists and total_events > 0:
                status = "fail"
            else:
                status = "pending"
            current = (
                f"lane_pass={lane_pass}/3; manual={manual_text}; "
                f"real_ios_verified={real_ios_verified}; fail_events={fail_events}"
            )
        elif key == "acceptance_gate":
            status = acceptance_status
            current = acceptance_brief(acceptance_report or {})
        elif key == "readiness_gate":
            status, current = _readiness_check_line(readiness_report, "target stage")
            if status == "pass" and normalized_stage in {"p1", "p2", "p3", "p4"} and not real_ios_verified:
                status = "warn"
                current = f"{current}; real_ios_verified=False"
        elif key == "claim_boundary":
            if (
                acceptance_status == "pass"
                and readiness_status == "pass"
                and real_ios_verified
                and fail_events == 0
                and screenshot_status == "pass"
                and manual_status == "pass"
            ):
                status = "pass"
            elif acceptance_status == "fail" or readiness_status == "fail":
                status = "fail"
            else:
                status = "warn"
            current = (
                f"acceptance={acceptance_status}; readiness={readiness_status}; "
                f"screenshot={screenshot_status}; manual={manual_status}; "
                f"metrics={metrics_count}; real_ios_verified={real_ios_verified}"
            )
        artifact_name = str(topic["artifact"])
        artifact_status = str(artifact_by_name.get(artifact_name, {}).get("status", "") or "")
        if artifact_status == "present" and status in {"pending", "warn"}:
            current = f"{current}; artifact=present"
        rows.append({
            "key": key,
            "gate": str(topic["gate"]),
            "check": check,
            "status": _worst_status(doc_status, status),
            "current": current,
            "proof": str(topic["proof"]),
            "readiness_link": str(topic["readiness_link"]).replace("<stage>", normalized_stage),
            "evidence_required": str(gap_action.get("evidence") or topic["evidence_required"]),
            "operator_action": str(gap_action.get("gui") or topic["proof"]),
            "artifact": artifact_name,
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _acceptance_proof_map_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
            "next_command": _proof_map_next_command(
                key,
                run_id=safe_run_id,
                stage=normalized_stage,
                evidence_path=evidence_path or Path("evidence") / f"{safe_run_id}.jsonl",
            ),
        })
    return rows


def acceptance_proof_map_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "key", statuses={"fail", "pending", "warn"})
    return (
        f"Proof map {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_acceptance_proof_map_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Acceptance 证明图 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This proof map is a navigation and audit artifact. It does not run scripts, write JSONL evidence, or prove real iPhone response.",
        "",
        "## Proof Rows",
        "",
        "| Key | Gate | Check | Status | Current | Evidence required | GUI action | Next command | Stop rule | Source |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | {_md_cell(row.get('gate', ''))} | "
            f"`{_md_cell(row.get('check', ''))}` | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('evidence_required', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} | `{_md_cell(row.get('next_command', ''))}` | "
            f"{_md_cell(row.get('stop_rule', ''))} | `{_md_cell(row.get('source', ''))}` |"
        )
    if not rows:
        lines.append("| none | - | `none` | `pending` | no rows built | Build proof map | Open Proof Map | `python -m imouse.gui` | Do not claim control | - |")
    lines.extend([
        "",
        "## Closure Rule",
        "",
        "Use Proof Map after Script Cov and before field handoff. A row can point to the next GUI action, but only same-run JSONL evidence, screenshot quality, lane-separated Manual click/swipe/text observations, Acceptance PASS, Readiness PASS, and exact device/iOS/receiver/HID scope can close a real-control claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


