def _readiness_stage_pass(report: dict | None, stage: str) -> bool:
    if not isinstance(report, dict):
        return False
    item = report.get("stage_status", {}).get(stage.lower().strip())
    return bool(isinstance(item, dict) and item.get("ok"))


def _claim_scope_stage_status(report: dict | None, stage: str) -> str:
    if not isinstance(report, dict):
        return "pending"
    item = report.get("stage_status", {}).get(stage.lower().strip())
    if not isinstance(item, dict):
        return "pending"
    return "pass" if item.get("ok") else "fail"


def claim_scope_rows(
    *,
    run_id: str,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    proof_map_rows: list[dict[str, str]] | None = None,
    core_rows: list[dict[str, str]] | None = None,
    api_coverage_rows: list[dict[str, str]] | None = None,
    compatibility_rows: list[dict[str, str]] | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Return exact allowed/forbidden claim rows for the current run."""
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id or normalized_stage).safe_run_id
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = (
        int(summary.get("metrics", {}).get("count", 0) or 0)
        if isinstance(summary.get("metrics"), dict)
        else 0
    )
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    readiness_claims = readiness_report.get("claims", {}) if isinstance(readiness_report, dict) else {}
    offline_ready = bool(readiness_claims.get("offline_assets_ready"))
    real_ios_verified = bool(readiness_claims.get("real_ios_control_verified"))
    group_verified = bool(readiness_claims.get("ios_group_control_verified"))
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    artifacts = artifact_rows or []
    required_missing = [
        row.get("name", "")
        for row in artifacts
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]
    recommended_missing = [
        row.get("name", "")
        for row in artifacts
        if row.get("requirement") == "recommended" and row.get("status") != "present"
    ]
    proof_status = _rows_worst_status(proof_map_rows or [])
    core_status = _rows_worst_status(core_rows or [])
    api_status = _rows_worst_status(api_coverage_rows or [])
    compat_status = _rows_worst_status(compatibility_rows or [])
    xp_hardware_gap = _xp_gap_status_for_domains(
        xp_gap_audit,
        ("xp hardware", "wired", "firmware", "receiver/capture"),
    ) or "pending"
    device_scope = ", ".join(selected_devices) if selected_devices else "-"

    rows: list[dict[str, str]] = []

    def add(
        claim_area: str,
        status: str,
        allowed_claim: str,
        forbidden_claim: str,
        current_scope: str,
        evidence_required: str,
        handoff_text: str,
        method: str,
    ) -> None:
        rows.append({
            "claim_area": claim_area,
            "status": status,
            "allowed_claim": allowed_claim,
            "forbidden_claim": forbidden_claim,
            "current_scope": current_scope,
            "evidence_required": evidence_required,
            "handoff_text": handoff_text,
            "gui_action": _claim_scope_gui_action(method),
            "method": method,
        })

    p0_status = "pass" if offline_ready else "pending" if readiness_report is None else "warn"
    add(
        "P0 offline assets",
        p0_status,
        "Offline GUI/API/SOP assets may be described as present only when Readiness P0 is PASS.",
        "Do not describe P0 assets as real iPhone control, group control, XP hardware parity, or broad compatibility.",
        f"run_id={safe_run_id}; offline_assets_ready={offline_ready}; docs/scripts/modules checked by Readiness",
        "Readiness report with P0 PASS and current test transcript.",
        "P0 is a local implementation and documentation claim, not a field-control claim.",
        "run_readiness_audit",
    )

    if real_ios_verified and acceptance_ok and readiness_ok and fail_events == 0:
        p1_status = "pass"
        p1_allowed = f"Single-iPhone control is verified only for devices [{device_scope}] in run {safe_run_id}."
    elif acceptance_ok and readiness_ok:
        p1_status = "warn"
        p1_allowed = "Acceptance and Readiness were run, but real_ios_verified is false; keep this as unverified field control."
    else:
        p1_status = "fail" if acceptance_report is not None or readiness_report is not None or evidence_exists else "pending"
        p1_allowed = "No real iPhone control claim is allowed yet."
    add(
        "P1 single-iPhone control",
        p1_status,
        p1_allowed,
        "Do not say iOS perfect control, full control, stable control, or XP-equivalent control without same-run P1 proof.",
        (
            f"route_ready={route_ready}; doctor={doctor_overall or '-'}; events={total_events}; fail={fail_events}; "
            f"screenshot={screenshot_status}; manual={manual_status}; component={component_status}; "
            f"real_ios_verified={real_ios_verified}"
        ),
        "Route, Doctor, screenshot_quality, click/swipe/text Manual observations, Acceptance PASS, Readiness PASS, no unresolved fail events.",
        "If P1 is not pass, hand off the first missing proof row from Proof Map instead of a success statement.",
        "show_acceptance_proof_map_from_gui" if p1_status != "pass" else "show_gui_goal_gate_from_gui",
    )

    p2_pass = _readiness_stage_pass(readiness_report, "p2")
    if p2_pass and metrics_count > 0 and fail_events == 0:
        p2_status = "pass"
        p2_allowed = f"Single-device stability is verified for run {safe_run_id} only."
    elif real_ios_verified and metrics_count > 0:
        p2_status = "warn"
        p2_allowed = "Metrics exist, but P2 Readiness is not closed; call it a stability rehearsal only."
    else:
        p2_status = "pending" if normalized_stage in {"p0", "p1"} else "fail"
        p2_allowed = "No P2 stability claim is allowed yet."
    add(
        "P2 single-device stability",
        p2_status,
        p2_allowed,
        "Do not infer stability from one clean click/swipe/type or from local metrics alone.",
        f"p2={_claim_scope_stage_status(readiness_report, 'p2')}; metrics={metrics_count}; fail={fail_events}",
        "P2 Acceptance/Readiness, repeated screenshots, metrics, logs or failure triage, and no unresolved fail events.",
        "Use stability wording only after P2 gate closes; otherwise list the missing metrics/log/recovery evidence.",
        "show_stage_dashboard_from_gui",
    )

    p3_pass = _readiness_stage_pass(readiness_report, "p3")
    p4_pass = _readiness_stage_pass(readiness_report, "p4")
    if group_verified and (p3_pass or p4_pass) and fail_events == 0:
        group_status = "pass"
        group_allowed = f"iOS group control is verified only for the exact P{'4' if p4_pass else '3'} device set in run {safe_run_id}."
    elif normalized_stage in {"p3", "p4"}:
        group_status = "fail"
        group_allowed = "No group-control claim is allowed until P3/P4 Readiness passes."
    else:
        group_status = "pending"
        group_allowed = "Group control is out of scope until P1/P2 are closed."
    add(
        "P3/P4 iOS group control",
        group_status,
        group_allowed,
        "Do not extrapolate one-device P1 evidence to four-device or ten-device group control.",
        f"p3={_claim_scope_stage_status(readiness_report, 'p3')}; p4={_claim_scope_stage_status(readiness_report, 'p4')}; group_verified={group_verified}",
        "Per-device JSONL evidence, Matrix, metrics, artifacts, recovery/triage, P3/P4 Acceptance and Readiness.",
        "Handoff must list device count, each device id, each iOS version, route, HID, and any excluded devices.",
        "show_device_evidence_matrix_from_gui",
    )

    if api_status in {"pass", "ready"} or core_status in {"pass", "ready"}:
        api_claim_status = "ready"
        api_allowed = "Local XP-style API/helper compatibility may be described for the tested endpoints only."
    elif api_coverage_rows or core_rows:
        api_claim_status = "warn"
        api_allowed = "API/Core coverage is partial; describe only implemented/tested helper domains."
    else:
        api_claim_status = "pending"
        api_allowed = "No API/SDK coverage claim should be made before API Cov/Core review."
    add(
        "XP API/SDK compatibility",
        api_claim_status,
        api_allowed,
        "Do not treat local API/client tests as receiver, HID, real iPhone, XP hardware, cloud, account, or license parity.",
        f"api={api_status}; core={core_status}; proof_map={proof_status}",
        "API tests, XP API Coverage Board, Core Matrix, Events contract, and field evidence for any hardware-backed endpoint claim.",
        "Say 'local compatibility scaffold' unless the same endpoint is also proven through real receiver/HID/iPhone evidence.",
        "show_xp_api_coverage_board_from_gui",
    )

    hardware_status = "warn" if real_ios_verified else "fail"
    add(
        "XP hardware, wired, firmware and decode parity",
        hardware_status,
        "Generic receiver/HID progress may be described separately from XP dedicated hardware parity.",
        "Do not claim XP dedicated hardware, 4.4 firmware, wired auto-binding, Windows receiver parity, or hardware decode parity without side-by-side evidence.",
        f"xp_hardware_gap={xp_hardware_gap}; real_ios_verified={real_ios_verified}; route_ready={route_ready}; doctor_clean={doctor_clean}",
        "Legal XP hardware or equivalent side-by-side run, firmware/binding logs, receiver/decode metrics, screenshots, Manual observations, Acceptance and Readiness.",
        "Keep XP hardware parity in backlog until the side-by-side bench has artifacts and logs.",
        "show_xp_hardware_lab_from_gui",
    )

    if compat_status in {"pass", "ready"} and real_ios_verified:
        compat_claim_status = "ready"
        compat_allowed = "Compatibility may be discussed only for the exact locally covered model/iOS/orientation tuple."
    elif compatibility_rows:
        compat_claim_status = "warn"
        compat_allowed = "Compatibility matrix is local planning evidence only until the exact tuple has real field proof."
    else:
        compat_claim_status = "pending"
        compat_allowed = "No model/iOS compatibility claim should be made before Compat and metadata evidence exist."
    add(
        "Device and iOS compatibility",
        compat_claim_status,
        compat_allowed,
        "Do not inherit public iMouse compatibility claims or generalize from one iPhone/iOS version.",
        f"compat={compat_status}; devices={device_scope}; real_ios_verified={real_ios_verified}",
        "Device/iOS Matrix, component metadata, exact iPhone model/iOS/orientation, screenshots, Manual evidence, Acceptance and Readiness.",
        "Handoff must name supported and untested device/iOS tuples separately.",
        "show_device_ios_compatibility_from_gui",
    )

    if required_missing:
        handoff_status = "fail"
        handoff_allowed = "No final handoff claim; required artifacts are missing."
    elif recommended_missing:
        handoff_status = "warn"
        handoff_allowed = "Handoff may be a work-in-progress packet with explicit missing recommended artifacts."
    else:
        handoff_status = "pass" if real_ios_verified else "ready"
        handoff_allowed = "Documentation/SOP handoff is allowed within the evidence-backed scope only."
    add(
        "Docs and SOP handoff wording",
        handoff_status,
        handoff_allowed,
        "Do not use exported Markdown, public sources, GUI dashboards, dry-run, or API success as the final control claim.",
        f"required_missing={len(required_missing)}; recommended_missing={len(recommended_missing)}; evidence_exists={evidence_exists}",
        "Evidence Pack, Start Pack, Proof Map, Goal Gate, Readiness, Acceptance, Transcript/Worksheet, and exact blocker list.",
        "Final handoff must include strongest allowed claim plus every forbidden claim still blocked.",
        "write_evidence_pack_from_gui",
    )
    return rows


def claim_scope_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "claim_area", statuses={"fail", "pending", "warn"})
    strongest = "none"
    for row in rows:
        if row.get("status") == "pass":
            strongest = str(row.get("claim_area", "") or "none")
    return (
        f"Claim scope {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; strongest={strongest}; first_focus={first_focus}"
    )


def write_claim_scope_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    group_verified = bool((readiness_report or {}).get("claims", {}).get("ios_group_control_verified"))
    lines = [
        f"# GUI 声明范围 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        f"- iOS group control verified: `{group_verified}`",
        "- This board writes claim wording guidance only. It does not write JSONL evidence and does not prove real iPhone response.",
        "",
        "## Claim Rows",
        "",
        "| Claim area | Status | Allowed claim | Forbidden claim | Current scope | Evidence required | Handoff text | GUI action |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('claim_area', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('allowed_claim', ''))} | {_md_cell(row.get('forbidden_claim', ''))} | "
            f"{_md_cell(row.get('current_scope', ''))} | {_md_cell(row.get('evidence_required', ''))} | "
            f"{_md_cell(row.get('handoff_text', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | No claim allowed | Do not claim control | no rows built | Run Readiness | Refresh Claim Scope | - |")
    lines.extend([
        "",
        "## Wording Rule",
        "",
        "Use Claim Scope immediately before a demo, handoff, release note, or acceptance summary. The strongest allowed claim is limited to rows with `pass`. Rows with `ready`, `warn`, `pending`, or `fail` must be described as open work with the listed forbidden wording excluded.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _verification_walkthrough_gui_action(method: str) -> str:
    return {
        "show_first_run_packet_from_gui": "Open Start Pack",
        "prepare_live_probe_from_gui": "Prepare",
        "edit_route_decision_from_gui": "Edit Route",
        "run_preflight_doctor": "Run Doctor",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "run_readiness_audit": "Run Readiness",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "show_device_evidence_matrix_from_gui": "Open Matrix",
        "show_xp_core_function_matrix_from_gui": "Open Core",
        "write_evidence_pack_from_gui": "Export Pack",
    }.get(method, method)


def verification_walkthrough_rows(
    *,
    run_id: str,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    core_rows: list[dict[str, str]] | None = None,
    route_matrix_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the step-by-step verification walkthrough without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id).safe_run_id
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metrics_count = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    artifacts = artifact_rows or []
    required_missing = [
        str(row.get("name", "") or "")
        for row in artifacts
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]
    recommended_missing = [
        str(row.get("name", "") or "")
        for row in artifacts
        if row.get("requirement") == "recommended" and row.get("status") != "present"
    ]
    core_status = _rows_worst_status(core_rows or [])
    route_matrix_status = _rows_worst_status(route_matrix_rows or [])

    rows: list[dict[str, str]] = []
    for index, step in enumerate(VERIFICATION_WALKTHROUGH_STEPS, start=1):
        key = str(step["key"])
        status = "pending"
        current = (
            f"stage={normalized_stage.upper()}; devices={len(selected_devices)}/{required_devices}; "
            f"events={total_events}, fail={fail_events}"
        )

        if key == "offline_self_check":
            status = "ready"
            current = "run local tests/compile/dependency check before field work; latest checked count is documented in README"
        elif key == "run_identity":
            status = "pass" if safe_run_id and len(selected_devices) >= required_devices else "fail"
            current = f"run_id={safe_run_id or '-'}; selected={len(selected_devices)}, required={required_devices}"
        elif key == "route_decision":
            if route_report is None:
                status = "pending"
                current = "route decision not validated"
            else:
                status = "pass" if route_ready else "fail"
                current = route_decision_brief(route_report)
        elif key == "doctor_preflight":
            if doctor_report is None:
                status = "pending"
                current = "doctor not run"
            else:
                status = "pass" if doctor_overall == "ok" else "warn" if doctor_overall == "warn" else "fail"
                current = doctor_brief(doctor_report)
        elif key == "receiver_capture":
            if screenshot_status == "pass":
                status = "pass" if doctor_clean else "warn"
            elif screenshot_status == "fail":
                status = "fail"
            elif route_ready and doctor_clean:
                status = "pending"
            else:
                status = "fail" if route_report or doctor_report else "pending"
            current = f"screenshot={screenshot_text}; doctor={doctor_overall or '-'}; route_ready={route_ready}"
        elif key == "hid_manual_control":
            if manual_status == "pass" and real_ios_verified:
                status = "pass"
            elif manual_status == "pass":
                status = "warn"
            elif manual_status == "fail":
                status = "fail"
            elif route_ready and doctor_clean:
                status = "pending"
            else:
                status = "fail" if route_report or doctor_report else "pending"
            current = f"manual={manual_text}; real_ios_verified={real_ios_verified}; component={component_text}"
        elif key == "acceptance_readiness":
            if acceptance_report is None and readiness_report is None:
                status = "pending"
                current = "Acceptance/Readiness not run"
            elif acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "pass"
                current = "Acceptance and Readiness support current stage claim"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = "warn"
                current = f"acceptance_ok=True; readiness_ok=True; real_ios_verified={real_ios_verified}"
            else:
                status = "fail"
                current = f"{acceptance_brief(acceptance_report or {})}; {readiness_brief(readiness_report or {})}"
        elif key == "p2_stability":
            if normalized_stage in {"p2", "p3", "p4"}:
                if metrics_status == "pass" and fail_events == 0 and evidence_exists:
                    status = "ready"
                elif evidence_exists:
                    status = "warn" if metrics_count else "fail"
                else:
                    status = "pending"
                current = f"metrics={metrics_count}; {metrics_text}; events={total_events}, fail={fail_events}"
            else:
                status = "pending"
                current = "future after P1 passes; keep as next-stage checklist"
        elif key == "p3_group":
            if normalized_stage in {"p3", "p4"}:
                if len(selected_devices) >= 4 and evidence_exists and fail_events == 0:
                    status = "ready"
                else:
                    status = "fail"
                current = f"selected={len(selected_devices)}, required>=4; events={total_events}, fail={fail_events}"
            else:
                status = "pending"
                current = "future after P1/P2; do not scale before single-device stability"
        elif key == "xp_parity_review":
            if core_rows or route_matrix_rows:
                status = _worst_status(core_status, route_matrix_status)
                if status == "pass":
                    status = "ready"
                current = f"core={core_status}; routes={route_matrix_status}; real_ios_verified={real_ios_verified}"
            else:
                status = "pending"
                current = "Core/Routes not built for this run"
        elif key == "handoff_pack":
            if not artifacts:
                status = "pending"
                current = "evidence pack not built"
            elif required_missing:
                status = "fail"
                current = f"required_missing={len(required_missing)}: {', '.join(required_missing[:3])}"
            elif recommended_missing:
                status = "warn"
                current = f"recommended_missing={len(recommended_missing)}; required artifacts present"
            else:
                status = "pass"
                current = "required and recommended artifacts present"

        command = str(step["command"]).replace("<run_id>", safe_run_id).replace("<stage>", normalized_stage)
        rows.append({
            "step": str(index),
            "key": key,
            "phase": str(step["phase"]),
            "scope": str(step["scope"]),
            "status": status,
            "current": current,
            "command": command,
            "expected": str(step["expected"]),
            "evidence": str(step["evidence"]),
            "stop_rule": str(step["stop_rule"]),
            "gui_action": _verification_walkthrough_gui_action(str(step["method"])),
            "method": str(step["method"]),
        })
    return rows


def verification_walkthrough_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "phase")
    return (
        f"Verification walkthrough {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_verification_walkthrough_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 验证演练 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This walkthrough is a step-by-step test guide. It does not write evidence and does not prove real iPhone response.",
        "",
        "## Steps",
        "",
        "| # | Phase | Scope | Status | Current | Command / GUI path | Expected result | Evidence to keep | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('phase', ''))} | "
            f"{_md_cell(row.get('scope', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | `{_md_cell(row.get('command', ''))}` | "
            f"{_md_cell(row.get('expected', ''))} | {_md_cell(row.get('evidence', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| - | none | - | `pending` | no rows built | Refresh Verify | - | - | Do not promote | - |")
    lines.extend([
        "",
        "## Rule",
        "",
        "Run this top to bottom. A later row cannot make an earlier fail safe. Offline tests, API success, GUI exports, and public XP claims are supporting material only; real iPhone control requires screenshot quality, manual observations, JSONL evidence, Acceptance, and Readiness.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _local_verification_gui_action(method: str) -> str:
    return {
        "show_verification_walkthrough_from_gui": "Open Verify",
        "run_preflight_doctor": "Run Doctor",
        "show_receiver_route_gate_from_gui": "Open Receiver",
        "load_probe_script_from_gui": "Load Probe Script",
        "run_readiness_audit": "Run Readiness",
    }.get(method, method)


def local_verification_rows(
    *,
    run_id: str,
    stage: str = "p1",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    route_decision_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build a local command-by-command verification guide without running commands."""
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id).safe_run_id
    route_path_text = str(route_decision_path or "").strip() or f"evidence\\{safe_run_id}_route_decision.json"
    default_script = standard_probe_script(normalized_stage)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []
    for index, step in enumerate(LOCAL_VERIFICATION_STEPS, start=1):
        key = str(step["key"])
        status = "pending"
        current = "not run by this GUI panel"

        if key == "unit_tests":
            status = "ready"
            current = "run after every code edit; latest terminal result belongs in the handoff notes"
        elif key == "compileall":
            status = "ready"
            current = "run after unit-test or import changes; no JSONL evidence is written"
        elif key == "dependency_check":
            ux_status, ux_message, _details = _probe_check_line(doctor_report, "binary:uxplay")
            if doctor_report is None:
                status = "pending"
                current = "main --check has not been captured in this GUI session"
            elif ux_status == "fail":
                status = "warn"
                current = f"binary:uxplay={ux_status}; {ux_message}"
            else:
                status = ux_status
                current = f"binary:uxplay={ux_status}; {ux_message}"
        elif key == "doctor_default":
            if doctor_report is None:
                status = "pending"
                current = "doctor not run in this GUI session"
            else:
                status = "pass" if doctor_overall == "ok" else "warn" if doctor_overall == "warn" else "fail"
                current = doctor_brief(doctor_report)
        elif key == "doctor_route":
            receiver_status, receiver_message, _details = _probe_check_line(doctor_report, "receiver_provider")
            ux_status, ux_message, _ux_details = _probe_check_line(doctor_report, "binary:uxplay")
            if route_report is None:
                status = "pending"
                current = f"route decision not validated; route_path={route_path_text}"
            elif not route_ready:
                status = "fail"
                current = route_decision_brief(route_report)
            elif doctor_report is None:
                status = "ready"
                current = f"route_ready=True; rerun Doctor with --route-decision {route_path_text}"
            elif doctor_overall == "ok":
                status = "pass"
                current = f"route_ready=True; {doctor_brief(doctor_report)}"
            elif doctor_overall == "warn" and receiver_status in {"pass", "warn"} and ux_status in {"pass", "warn", "pending"}:
                status = "warn"
                current = f"route_ready=True; receiver={receiver_status}; binary:uxplay={ux_status}; {ux_message}"
            else:
                status = "fail"
                current = f"route_ready=True; receiver={receiver_status}; {receiver_message}; {doctor_brief(doctor_report)}"
        elif key == "scenario_dry_run":
            if scenario_summary is None:
                status = "ready"
                current = f"default_script={default_script}; dry-run not recorded"
            else:
                status = "pass" if scenario_summary.get("ok") else "fail"
                current = scenario_brief(scenario_summary)
        elif key == "readiness_p1":
            if readiness_report is None:
                status = "pending"
                current = f"readiness not run; evidence_exists={evidence_exists}; events={total_events}"
            else:
                status = "pass" if readiness_ok and real_ios_verified and fail_events == 0 else "fail"
                current = (
                    f"{readiness_brief(readiness_report)}; real_ios_verified={real_ios_verified}; "
                    f"events={total_events}, fail={fail_events}"
                )

        command = (
            str(step["command"])
            .replace("<run_id>", safe_run_id)
            .replace("<stage>", normalized_stage)
            .replace("scripts\\p1_receiver_capture_probe.json", default_script.replace("/", "\\"))
            .replace("scripts\\p1_single_device_control_probe.json", default_script.replace("/", "\\"))
            .replace(f"evidence\\{safe_run_id}_route_decision.json", route_path_text)
        )
        rows.append({
            "step": str(index),
            "key": key,
            "check": str(step["check"]),
            "status": status,
            "current": current,
            "command": command,
            "expected": str(step["expected"]),
            "failure_meaning": str(step["failure_meaning"]),
            "next_action": str(step["next_action"]),
            "boundary": str(step["boundary"]),
            "gui_action": _local_verification_gui_action(str(step["method"])),
            "method": str(step["method"]),
        })
    return rows


def local_verification_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "check")
    return (
        f"Local check {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_local_verification_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 本地验证 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This local check is a step-by-step command guide. It does not run commands, does not write evidence, and does not prove real iOS control.",
        "",
        "## Commands",
        "",
        "| # | Check | Status | Current signal | Command | Expected result | Failure meaning | Next action | Boundary | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('check', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"`{_md_cell(row.get('command', ''))}` | {_md_cell(row.get('expected', ''))} | "
            f"{_md_cell(row.get('failure_meaning', ''))} | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('boundary', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Local | - | - | - | Local only | - |")
    lines.extend([
        "",
        "## Rule",
        "",
        "Run the commands top to bottom in PowerShell after every code change. Passing local checks only makes the prototype runnable; real iOS control still requires receiver screenshots, visible click/swipe/text response, JSONL evidence, Acceptance PASS, and Readiness PASS.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


