def _callback_contract_stats(rows: list[dict[str, str]] | None) -> dict[str, Any]:
    callback_rows = rows or []
    severity_counts: dict[str, int] = {}
    sources: set[str] = set()
    events: set[str] = set()
    for row in callback_rows:
        severity = str(row.get("severity", "info") or "info").lower()
        severity_counts[severity] = severity_counts.get(severity, 0) + 1
        source = str(row.get("source", "") or "").strip()
        event = str(row.get("event", "") or "").strip()
        if source and source != "-":
            sources.add(source)
        if event:
            events.add(event)
    error_count = sum(severity_counts.get(item, 0) for item in ("fail", "error", "critical"))
    warn_count = severity_counts.get("warn", 0) + severity_counts.get("warning", 0)
    return {
        "count": len(callback_rows),
        "error_count": error_count,
        "warn_count": warn_count,
        "sources": sorted(sources),
        "events": sorted(events),
    }


def xp_event_error_contract_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    callback_rows_data: list[dict[str, str]] | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build a GUI-facing XP event/error contract audit without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    failure_counts = (
        summary.get("by_failure_category", {})
        if isinstance(summary.get("by_failure_category"), dict)
        else {}
    )
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    callback_stats = _callback_contract_stats(callback_rows_data)
    callback_count = int(callback_stats["count"])
    callback_errors = int(callback_stats["error_count"])
    callback_warns = int(callback_stats["warn_count"])
    callback_sources = ", ".join(callback_stats["sources"][:4]) or "-"
    api_gap = _xp_gap_status_for_domains(xp_gap_audit, ("kernel/api", "python sdk"))

    def category_total(categories: tuple[str, ...]) -> int:
        return sum(int(failure_counts.get(category, 0) or 0) for category in categories)

    rows: list[dict[str, str]] = []
    for topic in XP_EVENT_CONTRACT_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = _worst_status(doc_status, "ready")
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; "
            f"doctor={doctor_overall or '-'}; evidence={total_events}, fail={fail_events}; "
            f"callbacks={callback_count}, callback_errors={callback_errors}"
        )

        if key == "api_envelope":
            if api_gap == "pass":
                status = _worst_status(doc_status, "ready")
                current = "status/message/data/code/msgid/fun contract is covered by local compatibility tests; field errors still need real devices"
            elif api_gap in {"warn", "fail"}:
                status = _worst_status(doc_status, api_gap)
                current = f"XP Gap API status={api_gap}; keep protocol tests green before SDK parity claims"
            else:
                status = _worst_status(doc_status, "ready")
                current = "local API contract exists; current XP Gap audit was not supplied"
        elif key == "request_transport":
            if api_gap == "fail":
                status = _worst_status(doc_status, "fail")
            elif api_gap == "warn":
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"HTTP/WebSocket /api path is the expected replay boundary; api_gap={api_gap or 'not_loaded'}"
        elif key == "callback_lifecycle":
            if callback_errors:
                status = _worst_status(doc_status, "warn")
            elif callback_count:
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "pending")
            current = (
                f"callbacks={callback_count}; warn={callback_warns}; error={callback_errors}; "
                f"sources={callback_sources}; callback rows are not control proof"
            )
        elif key == "field_event_sources":
            if doctor_failed or (route_report is not None and not route_ready):
                status = _worst_status(doc_status, "fail")
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            elif route_ready and doctor_clean and callback_count:
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "warn")
            current = (
                f"route_ready={route_ready}; doctor={doctor_overall or '-'}; "
                f"events={total_events}; failures={fail_events}; callbacks={callback_count}"
            )
        elif key == "receiver_hid_capture_errors":
            related = category_total(("airplay_discovery", "airplay_stream", "capture", "hid"))
            if doctor_failed or screenshot_status == "fail" or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif related:
                status = _worst_status(doc_status, "warn")
            elif route_ready and doctor_clean and evidence_exists and total_events:
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "pending")
            current = (
                f"related_failures={related}; screenshot={screenshot_text}; "
                f"manual={manual_text}; doctor={doctor_overall or '-'}"
            )
        elif key == "vision_script_errors":
            related = category_total(("vision_template", "vision_color", "ocr", "business_state", "uncategorized"))
            if related:
                status = _worst_status(doc_status, "warn")
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"vision/script related_failures={related}; events={total_events}; fail={fail_events}"
        elif key == "group_ops_events":
            if normalized_stage in {"p3", "p4"} and (not evidence_exists or total_events == 0):
                status = _worst_status(doc_status, "fail")
                current = f"{normalized_stage.upper()} needs per-device events, metrics, and artifacts"
            elif normalized_stage in {"p1", "p2"}:
                status = _worst_status(doc_status, "warn")
                current = f"stage={normalized_stage.upper()}; group contract is reviewed early but proven later"
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
        elif key == "config_user_shortcut_boundary":
            status = _worst_status(doc_status, "warn")
            current = "local config/user/shortcut helpers are scaffolding; account/licensing/cloud parity remains out of proof"
        elif key == "field_log_ingestion":
            has_attach_log = any(
                source in {"attach_log", "log", "receiver_log", "hid_log"}
                for source in callback_stats["sources"]
            )
            if callback_errors:
                status = _worst_status(doc_status, "warn")
            elif has_attach_log:
                status = _worst_status(doc_status, "ready")
            elif callback_count:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "pending")
            current = f"callback_sources={callback_sources}; attach_log_seen={has_attach_log}"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = (
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"real_ios_verified={real_ios_verified}; fail_events={fail_events}"
            )

        rows.append({
            "key": key,
            "layer": str(topic["layer"]),
            "contract": str(topic["contract"]),
            "status": status,
            "xp_gap_status": gap_status or "-",
            "public_signal": str(topic["public_signal"]),
            "local_support": str(topic["local_support"]),
            "current": current,
            "evidence_required": str(topic["evidence_required"]),
            "error_policy": str(topic["error_policy"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _xp_event_contract_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def xp_event_error_contract_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "contract", statuses={"fail", "pending", "warn"})
    return (
        f"XP event/error contract {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_event_error_contract_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Event/Error Contract {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This contract maps XP API/event/error semantics to local GUI/SOP checks. It does not write JSONL evidence and does not prove XP parity.",
        "",
        "## Contract Rows",
        "",
        "| Contract | Layer | Status | XP Gap | Public signal | Local support | Current signal | Evidence required | Error policy | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('contract', ''))} | {_md_cell(row.get('layer', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | `{_md_cell(row.get('xp_gap_status', ''))}` | "
            f"{_md_cell(row.get('public_signal', ''))} | {_md_cell(row.get('local_support', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('evidence_required', ''))} | "
            f"{_md_cell(row.get('error_policy', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | - | `pending` | `-` | no rows built | Refresh Events | - | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Use Events before rerun and before SDK/API parity claims. A callback, log row, or API success is only diagnostic context until it is tied to device id, route, screenshot quality, manual real-iPhone observation, Acceptance, Readiness, and a categorized failure or pass for the same run_id.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _iteration_timeline_gui_action(method: str) -> str:
    return {
        "show_first_run_packet_from_gui": "Open Start Pack",
        "show_xp_event_error_contract_from_gui": "Open Events",
        "show_receiver_candidate_scorecard_from_gui": "Open Rx Score",
        "show_xp_hardware_lab_from_gui": "Open XP Lab",
        "show_scenario_library_from_gui": "Open Library",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "show_gui_goal_gate_from_gui": "Open Goals",
    }.get(method, method)


def xp_iteration_timeline_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Build a chronological XP iteration review without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")

    rows: list[dict[str, str]] = []
    for topic in XP_ITERATION_TIMELINE_TOPICS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = "pending"
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; doctor={doctor_overall or '-'}; "
            f"events={total_events if evidence_exists else 0}; fail_events={fail_events}; metrics={metric_events}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        )

        if key == "black_box_product_model":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "ready"
                current = f"{current}; P1-style black-box proof is reviewable for the exact run only"
            elif evidence_exists and total_events:
                status = "fail" if fail_events or manual_status == "fail" or screenshot_status == "fail" else "warn"
                current = f"{current}; local field evidence exists but acceptance/readiness/control claim is not closed"
            else:
                status = "pending"
                current = f"{current}; no real-iPhone evidence yet"
        elif key == "kernel_console_api_split":
            if gap_status == "pass" and evidence_exists and total_events:
                status = "ready"
                current = f"{current}; API/helper layer is locally reviewable but not hardware proof"
            elif gap_status == "pass":
                status = "warn"
                current = f"{current}; API/helper audit is locally green but no same-run evidence exists"
            elif gap_status in {"fail", "warn"}:
                status = gap_status
                current = f"{current}; XP Gap API/helper status={gap_status}"
            else:
                status = "warn"
                current = f"{current}; XP Gap API/helper audit not supplied"
        elif key == "receiver_projection_productization":
            if doctor_failed or (route_report is not None and not route_ready) or screenshot_status == "fail":
                status = "fail"
                current = f"{current}; receiver/capture route blocks the timeline lane"
            elif route_ready and doctor_clean and screenshot_status == "pass" and metric_events > 0 and fail_events == 0:
                status = "ready"
                current = f"{current}; receiver lane has screenshot and metrics evidence for current run"
            elif route_ready or screenshot_status == "pass":
                status = "warn"
                current = f"{current}; first receiver proof exists but productization metrics/logs are incomplete"
            else:
                status = "pending"
                current = f"{current}; receiver/capture lane not proven"
        elif key == "firmware_wired_binding":
            if real_ios_verified and manual_status == "pass":
                status = "warn"
                current = f"{current}; generic control proof exists, side-by-side XP hardware/4.4/binding evidence is still open"
            elif evidence_exists and total_events:
                status = "fail"
                current = f"{current}; field run exists but XP hardware/4.4/binding remains unproven"
            else:
                status = "pending"
                current = f"{current}; no HID field proof or XP hardware comparison"
        elif key == "vision_script_assets":
            if screenshot_status == "fail" or fail_events:
                status = "fail"
                current = f"{current}; visual/script failures require replay artifacts"
            elif gap_status == "pass" and screenshot_status == "pass":
                status = "ready"
                current = f"{current}; visual/script lane is locally reviewable from saved artifacts"
            elif evidence_exists and total_events:
                status = "warn"
                current = f"{current}; evidence exists but asset/replay discipline is incomplete"
            else:
                status = "pending"
                current = f"{current}; no screenshot-backed asset lane yet"
        elif key == "ops_logs_group_scale":
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0 or metric_events == 0 or fail_events or not readiness_ok:
                    status = "fail"
                    current = f"{current}; scale lane needs per-device evidence, metrics, no hidden failures, and readiness"
                else:
                    status = "ready"
                    current = f"{current}; scale lane review applies only to selected device count"
            elif fail_events:
                status = "warn"
                current = f"{current}; logs/recovery should be attached before rerun"
            else:
                status = "pending"
                current = f"{current}; group/ops lane waits for P1/P2 proof"
        elif key == "source_claim_governance":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = "ready"
                current = f"{current}; claim wording may be reviewed for exact evidence scope"
            elif acceptance_report is None and readiness_report is None:
                status = "pending"
                current = f"{current}; acceptance/readiness not evaluated"
            else:
                status = "warn" if evidence_exists or acceptance_report or readiness_report else "pending"
                current = f"{current}; source-only or partial gates cannot support broad claims"

        method = str(topic["method"])
        rows.append({
            "key": key,
            "order": str(topic["order"]),
            "phase": str(topic["phase"]),
            "status": _worst_status(doc_status, status),
            "xp_gap_status": gap_status or "-",
            "public_signal": str(topic["public_signal"]),
            "pitfall": str(topic["pitfall"]),
            "rd_lesson": str(topic["rd_lesson"]),
            "sop_gate": str(topic["sop_gate"]),
            "current": current,
            "evidence_required": str(topic["evidence_required"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "gui_action": _iteration_timeline_gui_action(method),
            "method": method,
        })
    return rows


def xp_iteration_timeline_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "phase", statuses={"fail", "pending", "warn"})
    return (
        f"XP iteration timeline {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_iteration_timeline_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Iteration Timeline {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This timeline converts public XP iteration signals into R&D lessons, SOP gates, pitfalls, and stop rules. It does not write JSONL evidence and does not prove XP parity.",
        "",
        "## Timeline Rows",
        "",
        "| # | Phase | Status | XP Gap | Public signal | Pitfall | R&D lesson | SOP gate | Current local state | Evidence required | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('order', ''))} | {_md_cell(row.get('phase', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | `{_md_cell(row.get('xp_gap_status', ''))}` | "
            f"{_md_cell(row.get('public_signal', ''))} | {_md_cell(row.get('pitfall', ''))} | "
            f"{_md_cell(row.get('rd_lesson', ''))} | {_md_cell(row.get('sop_gate', ''))} | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('evidence_required', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | `{_md_cell(row.get('source', ''))}` | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | `-` | no rows built | - | Refresh XP Timeline | - | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Use XP Timeline after source refresh and before roadmap or parity planning. A timeline row explains an observed iteration lesson; it is closed only by same-run field evidence, Acceptance, Readiness, logs, and exact claim scope.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


