def xp_iteration_radar_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Convert XP iteration lessons into stage-aware R&D and SOP priorities."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []
    for topic in XP_ITERATION_RADAR_TOPICS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        status = doc_status
        current_gap = "source mapped; local proof pending"

        if key == "p1_black_box_control":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
                current_gap = "single-iPhone control gate currently clean"
            elif evidence_exists and total_events > 0:
                status = _worst_status(doc_status, "fail" if fail_events else "warn")
                current_gap = (
                    f"events={total_events}, fail={fail_events}, acceptance_ok={acceptance_ok}, "
                    f"readiness_ok={readiness_ok}, real_ios_verified={real_ios_verified}"
                )
            else:
                status = _worst_status(doc_status, "pending")
                current_gap = "no JSONL evidence for real iPhone control"
        elif key == "kernel_api_split":
            gap_status = _xp_gap_status_for_domains(xp_gap_audit, ("kernel/api", "python sdk"))
            if not gap_status:
                status = _worst_status(doc_status, "warn")
                current_gap = "current XP Gap audit not exported"
            else:
                status = _worst_status(doc_status, "ready" if gap_status == "pass" else gap_status)
                current_gap = f"XP Gap service/API status={gap_status}"
        elif key == "receiver_capture_evolution":
            gap_status = _xp_gap_status_for_domains(xp_gap_audit, ("receiver/capture",))
            if route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
                current_gap = "route and doctor not loaded"
            elif not route_ready or not doctor_clean:
                status = _worst_status(doc_status, "fail")
                current_gap = f"route_ready={route_ready}, doctor_clean={doctor_clean}, XP Gap receiver={gap_status or 'unknown'}"
            else:
                status = _worst_status(doc_status, "ready" if gap_status == "pass" else "warn")
                current_gap = "route/doctor clean, but Windows/wired/hardware decode still need dedicated bench"
        elif key == "xp_hardware_binding":
            gap_status = _xp_gap_status_for_domains(xp_gap_audit, ("usb/hid", "mouse/keyboard"))
            if not real_ios_verified:
                status = _worst_status(doc_status, "fail")
                current_gap = f"real_ios_verified=False, XP hardware/4.4 not proven, XP Gap HID={gap_status or 'unknown'}"
            else:
                status = _worst_status(doc_status, "warn")
                current_gap = "real HID response exists, but XP hardware/4.4/auto-binding parity still needs comparison"
        elif key == "vision_script_productization":
            gap_status = _xp_gap_status_for_domains(
                xp_gap_audit,
                ("vision/image/color", "ocr", "script runtime"),
            )
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current_gap = "no real screenshot/script artifacts yet"
            elif fail_events:
                status = _worst_status(doc_status, "fail")
                current_gap = f"failed evidence events={fail_events}; replay assets required"
            elif gap_status in {"fail", "warn"}:
                status = _worst_status(doc_status, "warn")
                current_gap = f"evidence clean so far, XP Gap vision/script status={gap_status}"
            else:
                status = _worst_status(doc_status, "ready")
                current_gap = "current evidence clean; keep building replayable assets before scale"
        elif key == "ops_scaling":
            gap_status = _xp_gap_status_for_domains(xp_gap_audit, ("device/group", "observability", "commercial/ops", "gui console"))
            if normalized_stage in {"p3", "p4"} and (not evidence_exists or metric_events == 0):
                status = _worst_status(doc_status, "fail")
                current_gap = f"{normalized_stage.upper()} needs metrics, per-device isolation, and logs"
            elif fail_events:
                status = _worst_status(doc_status, "fail")
                current_gap = f"failed evidence events={fail_events}; fix isolation before scaling"
            else:
                status = _worst_status(doc_status, "warn" if gap_status in {"fail", "warn", ""} else "ready")
                current_gap = f"stage={normalized_stage.upper()}, metrics={metric_events}, XP Gap ops={gap_status or 'unknown'}"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
                current_gap = "claim boundary clean for current stage only"
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
                current_gap = "Acceptance/Readiness not run"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
                current_gap = "gates look clean, but readiness says real_ios_verified=False"
            else:
                status = _worst_status(doc_status, "fail")
                current_gap = (
                    f"acceptance_ok={acceptance_ok}, readiness_ok={readiness_ok}, "
                    f"real_ios_verified={real_ios_verified}, fail_events={fail_events}"
                )

        rows.append({
            "key": key,
            "phase": str(topic["phase"]),
            "status": status,
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "public_signal": str(topic["public_signal"]),
            "current_gap": current_gap,
            "rd_action": str(topic["rd_action"]),
            "sop_test": str(topic["sop_test"]),
            "gui_action": _iteration_radar_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
            "stop_rule": str(topic["stop_rule"]),
        })
    return rows


def xp_iteration_radar_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "phase", statuses={"fail", "pending", "warn"})
    return (
        f"XP iteration radar {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_iteration_radar_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Iteration Radar {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Source refresh date: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This radar converts public XP iteration lessons into R&D priorities, SOP tests, and stop rules. It does not write evidence and does not prove XP parity.",
        "",
        "## Radar Rows",
        "",
        "| Phase | Status | Public signal | Current gap | R&D action | SOP/test path | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('phase', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('public_signal', ''))} | {_md_cell(row.get('current_gap', ''))} | "
            f"{_md_cell(row.get('rd_action', ''))} | {_md_cell(row.get('sop_test', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('source', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | no rows built | Refresh Radar | - | - | - | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Do not turn public XP iteration claims into product claims. Each radar row must be converted into local receiver/HID/iPhone evidence, Acceptance, Readiness, logs, and operator observations before promotion.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def xp_iteration_drill_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
) -> list[dict[str, str]]:
    """Turn XP iteration details into field validation drills and stop lines."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    categories = summary.get("by_failure_category", {}) if isinstance(summary.get("by_failure_category"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    category_text = ", ".join(
        f"{name}={count}" for name, count in sorted(categories.items()) if count
    ) or "none"

    rows: list[dict[str, str]] = []
    for topic in XP_ITERATION_DRILL_TOPICS:
        key = str(topic["key"])
        source_doc = str(topic["source_doc"])
        doc_status = "pass" if (root / source_doc).exists() else "fail"
        gap_status = _xp_gap_status_for_domains(
            xp_gap_audit,
            tuple(str(fragment) for fragment in topic.get("gap_fragments", ())),
        )
        status = doc_status
        current_gap = (
            f"stage={normalized_stage.upper()}, route_ready={route_ready}, "
            f"doctor={doctor_overall or '-'}, evidence_events={total_events if evidence_exists else 0}, "
            f"fail_events={fail_events}, metrics={metric_events}, real_ios_verified={real_ios_verified}, "
            f"categories={category_text}"
        )

        if key == "windows_service_console_split":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; XP Gap audit not exported"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current_gap = f"{current_gap}; XP Gap API/SDK status=pass; field errors still need device evidence"
            elif gap_status in {"fail", "warn"}:
                status = _worst_status(doc_status, gap_status)
                current_gap = f"{current_gap}; XP Gap API/SDK status={gap_status}"
            else:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; API/SDK gap status unknown"
        elif key == "ios_settings_mouse_profile":
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
                current_gap = f"{current_gap}; doctor failed before iOS settings can be trusted"
            elif manual_status == "pass" and screenshot_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
                current_gap = f"{current_gap}; screenshot={screenshot_text}; manual={manual_text}"
            elif route_ready or doctor_clean or evidence_exists:
                status = _worst_status(doc_status, "warn")
                current_gap = (
                    f"{current_gap}; settings/profile may be ready, but screenshot={screenshot_text}; "
                    f"manual={manual_text}; real_ios_verified={real_ios_verified}"
                )
            else:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; route/doctor/evidence not ready for iOS settings drill"
        elif key == "receiver_projection_binding":
            if doctor_failed or (route_report is not None and not route_ready):
                status = _worst_status(doc_status, "fail")
                current_gap = f"{current_gap}; route or doctor blocks receiver/capture"
            elif route_ready and doctor_clean and screenshot_status == "pass" and evidence_exists and not fail_events:
                status = _worst_status(doc_status, "ready")
                current_gap = f"{current_gap}; screenshot={screenshot_text}; still needs stability samples before scale"
            elif route_ready or doctor_clean:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; receiver chosen but screenshot quality/stability evidence is incomplete"
            else:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; receiver lane not locked"
        elif key == "xp_hardware_44_wired_binding":
            if not real_ios_verified:
                status = _worst_status(doc_status, "fail")
                current_gap = (
                    f"{current_gap}; generic HID/CH9329 proof is not XP hardware/4.4/wired-binding proof; "
                    f"manual={manual_text}; XP Gap HID={gap_status or 'unknown'}"
                )
            elif gap_status == "pass":
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; real HID response exists, but XP hardware parity still needs side-by-side artifacts"
            else:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; real iPhone response exists but hardware parity gap={gap_status or 'unknown'}"
        elif key == "sdk_package_namespace_drift":
            if not xp_gap_audit:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; no XP Gap/API baseline for package comparison"
            elif gap_status == "pass":
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; package can be reviewed as drift input only, not hardware proof"
            elif gap_status in {"fail", "warn"}:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; package/API drift remains while XP Gap API/SDK={gap_status}"
            else:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; package identity/version/hash review required"
        elif key == "restart_projection_logs":
            if not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; no JSONL/log evidence to rehearse recovery"
            elif fail_events:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; failures exist and must be attached, categorized, and rerun through Recovery"
            elif metric_events or gap_status == "pass":
                status = _worst_status(doc_status, "ready")
                current_gap = f"{current_gap}; clean evidence exists, but forced failure/recovery drill is still required before P2 promotion"
            else:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; evidence exists but logs/callback/metrics coverage is thin"
        elif key == "multi_device_10_projection":
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0 or metric_events == 0:
                    status = _worst_status(doc_status, "fail")
                    current_gap = f"{current_gap}; {normalized_stage.upper()} requires per-device evidence plus metrics"
                elif fail_events:
                    status = _worst_status(doc_status, "fail")
                    current_gap = f"{current_gap}; failures block scale until every device has category and artifact"
                elif readiness_ok and real_ios_verified:
                    status = _worst_status(doc_status, "ready")
                    current_gap = f"{current_gap}; scale drill can be reviewed for exact device count only"
                else:
                    status = _worst_status(doc_status, "warn")
                    current_gap = f"{current_gap}; metrics exist but Readiness/real_ios claim boundary is not clean"
            else:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; P3/P4 scale drill is intentionally delayed until P1/P2 closes"
        elif key == "claim_boundary_drill":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
                current_gap = f"{current_gap}; claim boundary clean for current stage only"
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
                current_gap = f"{current_gap}; Acceptance/Readiness not run"
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
                current_gap = f"{current_gap}; gates look clean, but real_ios_verified=False"
            else:
                status = _worst_status(doc_status, "fail")
                current_gap = (
                    f"{current_gap}; acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                    f"component={component_text}; source/GUI artifacts are not field proof"
                )

        method = str(topic["method"])
        rows.append({
            "key": key,
            "status": status,
            "signal": str(topic["signal"]),
            "source": str(topic["source"]),
            "source_doc": source_doc,
            "stage": str(topic["stage"]),
            "current_gap": current_gap,
            "validation_drill": str(topic["validation_drill"]),
            "required_evidence": str(topic["required_evidence"]),
            "failure_category": str(topic["failure_category"]),
            "stop_rule": str(topic["stop_rule"]),
            "gui_action": _iteration_drill_gui_action(method),
            "method": method,
        })
    return rows


def xp_iteration_drill_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "key", statuses={"fail", "pending", "warn"})
    return (
        f"XP iteration drill {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_iteration_drill_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# XP Iteration Drill Board {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Source refresh date: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This board converts XP iteration/help/package signals into validation drills. It does not browse automatically, does not write JSONL evidence, does not prove real iPhone control, and does not prove XP parity.",
        "",
        "## Drill Rows",
        "",
        "| Key | Status | Signal | Source | Stage | Current gap | Validation drill | Required evidence | Failure category | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('key', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('signal', ''))} | {_md_cell(row.get('source', ''))} | "
            f"{_md_cell(row.get('stage', ''))} | {_md_cell(row.get('current_gap', ''))} | "
            f"{_md_cell(row.get('validation_drill', ''))} | {_md_cell(row.get('required_evidence', ''))} | "
            f"{_md_cell(row.get('failure_category', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | `pending` | no rows built | - | - | Refresh XP Drill | - | - | - | Do not promote | - |")
    lines.extend([
        "",
        "## Use Rule",
        "",
        "Run this board after Source Refresh, XP Timeline, and Iter Radar, then execute the first fail/pending/warn drill. A drill export is an operating checklist only; same-run JSONL evidence, screenshot quality, manual observation, Acceptance, Readiness, logs, and exact device/iOS coverage still decide product claims.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _xp_roadmap_gui_action(method: str) -> str:
    return {
        "show_verification_walkthrough_from_gui": "Open Verify",
        "show_field_kit_gate_from_gui": "Open Kit Gate",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_hardware_bench_from_gui": "Open Bench",
        "show_scenario_library_from_gui": "Open Library",
        "attach_callback_log_from_gui": "Attach Log",
        "show_stage_dashboard_from_gui": "Open Dashboard",
        "show_gui_goal_gate_from_gui": "Open Goals",
    }.get(method, method)


def xp_roadmap_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
    route_matrix_rows: list[dict[str, str]] | None = None,
    core_rows: list[dict[str, str]] | None = None,
    industry_rows: list[dict[str, str]] | None = None,
    verification_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build a stage-aware XP clone R&D roadmap without writing field evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    metric_events = int(summary.get("metrics", {}).get("count", 0) or 0) if isinstance(summary.get("metrics"), dict) else 0
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    metrics_status, metrics_text = _acceptance_check_line(acceptance_report, "metrics")
    route_matrix_status = _rows_worst_status(route_matrix_rows or [])
    core_status = _rows_worst_status(core_rows or [])
    industry_status = _rows_worst_status(industry_rows or [])
    verification_status = _rows_worst_status(verification_rows or [])

    def gap_status(*fragments: str) -> str:
        return _xp_gap_status_for_domains(xp_gap_audit, tuple(fragments)) or "pending"

    rows: list[dict[str, str]] = []
    for topic in XP_ROADMAP_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}; route_ready={route_ready}; "
            f"doctor={doctor_overall or '-'}; events={total_events}, fail={fail_events}; "
            f"real_ios_verified={real_ios_verified}"
        )
        next_action = str(topic["rd_goal"])

        if key == "p0_offline_base":
            api_gap = gap_status("kernel/api", "python sdk")
            if api_gap == "pass":
                status = _worst_status(doc_status, "ready")
                current = "offline API/SDK compatibility is locally covered; field-control evidence remains separate"
            elif core_rows and core_status in {"pass", "ready", "warn"}:
                status = _worst_status(doc_status, "ready" if core_status in {"pass", "ready"} else "warn")
                current = f"core={core_status}; API/SDK surface exists but XP helper parity still needs audit rows"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"xp_gap_api={api_gap}; verification={verification_status}"
            next_action = "Keep offline tests green, then move only receiver/HID/iPhone claims into P1 evidence."
        elif key == "p1_route_bench":
            if route_ready and doctor_clean and component_status in {"pass", "pending"}:
                status = _worst_status(doc_status, "ready")
            elif doctor_failed or (route_report is not None and not route_ready):
                status = _worst_status(doc_status, "fail")
            elif route_report is None and doctor_report is None:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "warn")
            current = (
                f"route_ready={route_ready}; doctor={doctor_overall or '-'}; "
                f"component={component_text}; routes={route_matrix_status}; industry={industry_status}"
            )
            next_action = "Fill real receiver/HID/iPhone/Hub/cable values, validate Route Decision, then run Doctor and Bench."
        elif key == "p1_receiver_capture":
            receiver_gap = gap_status("receiver/capture")
            if doctor_failed or screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass" and doctor_clean:
                status = _worst_status(doc_status, "ready" if receiver_gap != "fail" else "warn")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = f"doctor={doctor_overall or '-'}; screenshot={screenshot_text}; XP Gap receiver={receiver_gap}"
            next_action = "Run Shot Bench before HID, save frame artifacts, and attach receiver logs for any black/stale frame."
        elif key == "p1_hid_control":
            hid_gap = gap_status("usb/hid", "mouse/keyboard")
            if doctor_failed or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif manual_status == "pass" and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "ready")
            elif manual_status == "pass":
                status = _worst_status(doc_status, "warn")
            elif route_ready and doctor_clean:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "fail" if route_report or doctor_report else "pending")
            current = f"manual={manual_text}; real_ios_verified={real_ios_verified}; XP Gap HID={hid_gap}"
            next_action = "Run P1 Trial and Control Bench while watching the physical phone; record pass/fail manually."
        elif key == "p1_calibration_input":
            calibration_gap = gap_status("coordinate calibration", "mouse/keyboard")
            if doctor_failed or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif manual_status == "pass" and component_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "ready")
            elif manual_status == "pass" or route_ready:
                status = _worst_status(doc_status, "warn" if manual_status == "pass" else "pending")
            else:
                status = _worst_status(doc_status, "pending")
            current = (
                f"manual={manual_text}; component={component_text}; "
                f"real_ios_verified={real_ios_verified}; XP Gap calibration={calibration_gap}"
            )
            next_action = "Save calibration profile, then repeat click/swipe/type across safe-area and orientation-sensitive points."
        elif key == "xp_hardware_wired_parity":
            route_text = "; ".join(
                f"{row.get('lane', '')}:{row.get('status', '')}"
                for row in (route_matrix_rows or [])
                if "XP" in str(row.get("lane", "")) or "Wired" in str(row.get("lane", ""))
            ) or "side_by_side_xp_parity_evidence=missing"
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = f"{route_text}; real_ios_verified={real_ios_verified}; XP hardware/wired/4.4/hard-decode proof is separate"
            next_action = "Keep generic HID/receiver progress separate; collect XP side-by-side hardware, firmware, wired, and decode artifacts later."
        elif key == "p2_vision_script":
            vision_gap = gap_status("vision/image/color", "ocr", "script runtime")
            if screenshot_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif not evidence_exists or total_events == 0:
                status = _worst_status(doc_status, "pending")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            elif vision_gap in {"fail", "warn"}:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "ready")
            current = f"screenshot={screenshot_text}; events={total_events}, fail={fail_events}; XP Gap vision/script={vision_gap}"
            next_action = "Build templates from real screenshots, export scenario JSON, and replay failures from artifacts."
        elif key == "p2_observability_recovery":
            ops_gap = gap_status("observability", "callback", "logs")
            if fail_events:
                status = _worst_status(doc_status, "warn")
                next_action = "Attach receiver/HID logs, classify failed events, then rerun the smallest failing path."
            elif evidence_exists and total_events > 0:
                status = _worst_status(doc_status, "ready")
                next_action = "Keep Timeline, Matrix, Callback, Triage, metrics, and Review together before moving to P2 stability."
            else:
                status = _worst_status(doc_status, "pending")
                next_action = "Create a real evidence ledger first, then add logs and callback events around every failure."
            current = f"events={total_events}, fail={fail_events}, metrics={metric_events}; {metrics_text}; XP Gap ops={ops_gap}"
        elif key == "p3_p4_scale_ops":
            scale_gap = gap_status("device/group", "commercial/ops", "gui console")
            if normalized_stage in {"p3", "p4"}:
                if not evidence_exists or total_events == 0:
                    status = _worst_status(doc_status, "fail")
                elif fail_events:
                    status = _worst_status(doc_status, "fail")
                elif real_ios_verified and metric_events:
                    status = _worst_status(doc_status, "ready" if scale_gap != "fail" else "warn")
                else:
                    status = _worst_status(doc_status, "warn")
                current = f"stage={normalized_stage.upper()}; events={total_events}, fail={fail_events}, metrics={metric_events}; scale_gap={scale_gap}"
            else:
                status = _worst_status(doc_status, "pending")
                current = f"{normalized_stage.upper()} is not a scale gate; finish P1/P2 field proof before group UX"
            next_action = "Use Dashboard and per-device Matrix to prove isolation before adding commercial group operations."
        elif key == "claim_documentation":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = (
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"real_ios_verified={real_ios_verified}; goals/industry/core/verify="
                f"{industry_status}/{core_status}/{verification_status}"
            )
            next_action = "Update SOP/docs only to the strongest proven gate, then rerun Start Pack and Readiness."

        rows.append({
            "key": key,
            "lane": str(topic["lane"]),
            "stage": str(topic["stage"]),
            "status": status,
            "current": current,
            "xp_signal": str(topic["xp_signal"]),
            "rd_goal": str(topic["rd_goal"]),
            "evidence_gate": str(topic["evidence_gate"]),
            "sop_test": str(topic["sop_test"]),
            "next_action": next_action,
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _xp_roadmap_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def xp_roadmap_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "lane", statuses={"fail", "pending", "warn"})
    return (
        f"XP roadmap {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_xp_roadmap_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    refreshed_at: str = "2026-06-09",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# XP Roadmap {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Source refresh date: `{refreshed_at}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This roadmap turns XP public signals, industry SOP, and local evidence gates into R&D next actions. It does not write evidence, does not prove iOS control, and does not prove XP parity.",
        "",
        "## Roadmap Rows",
        "",
        "| Lane | Target | Status | Current gate | XP/public signal | R&D goal | Evidence gate | SOP/test path | Next action | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('lane', ''))} | {_md_cell(row.get('stage', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('xp_signal', ''))} | {_md_cell(row.get('rd_goal', ''))} | "
            f"{_md_cell(row.get('evidence_gate', ''))} | {_md_cell(row.get('sop_test', ''))} | "
            f"{_md_cell(row.get('next_action', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"`{_md_cell(row.get('source', ''))}` | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| none | - | `pending` | no rows built | - | Refresh Roadmap | - | - | - | Do not promote | - | - |")
    lines.extend([
        "",
        "## Closure Rule",
        "",
        "Use Roadmap after Sources/Industry/Core and before Start Pack. A roadmap row can prioritize work, but only JSONL evidence, saved screenshots, manual observations, Acceptance, Readiness, logs, and per-device artifacts can close the row for a stage claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def gui_goal_gate_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    xp_gap_audit: dict | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    proof_map_rows: list[dict[str, str]] | None = None,
    claim_scope_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Map the user's four acceptance goals to concrete GUI evidence gates."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    artifact_list = artifact_rows or []

    def docs_line(key: str) -> tuple[str, str]:
        sources = GOAL_GATE_DOCS[key]
        missing = [source for source in sources if not (root / source).exists()]
        status = "pass" if not missing else "fail"
        detail = "docs present" if not missing else f"missing docs={', '.join(missing[:3])}"
        return status, detail

    xp_rows = xp_gap_audit.get("rows", []) if isinstance(xp_gap_audit, dict) else []
    xp_blocked = [
        str(row.get("domain", row.get("name", "")) or "")
        for row in xp_rows
        if isinstance(row, dict)
        and str(row.get("status", "")).lower() in {"blocked", "not_started", "partial"}
    ]
    required_missing = [
        row.get("name", "")
        for row in artifact_list
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]
    recommended_missing = [
        row.get("name", "")
        for row in artifact_list
        if row.get("requirement") == "recommended" and row.get("status") != "present"
    ]
    proof_status = _rows_worst_status(proof_map_rows) if proof_map_rows is not None else "pass"
    claim_scope_status = (
        _rows_worst_status(claim_scope_rows_data)
        if claim_scope_rows_data is not None
        else "pass"
    )
    proof_line = (
        acceptance_proof_map_brief(proof_map_rows, stage=normalized_stage)
        if proof_map_rows is not None
        else "proof map not linked"
    )
    claim_scope_line = (
        claim_scope_brief(claim_scope_rows_data, stage=normalized_stage)
        if claim_scope_rows_data is not None
        else "claim scope not linked"
    )

    rows: list[dict[str, str]] = []

    def add(
        goal: str,
        status: str,
        current_evidence: str,
        evidence_needed: str,
        next_action: str,
        test_method: str,
        method: str,
    ) -> None:
        rows.append({
            "goal": goal,
            "status": status,
            "current_evidence": current_evidence,
            "evidence_needed": evidence_needed,
            "next_action": next_action,
            "test_method": test_method,
            "gui_action": _goal_gui_action(method),
            "method": method,
        })

    control_docs_status, control_docs = docs_line("ios_control")
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
        ios_status = _worst_status(control_docs_status, "pass")
    elif acceptance_report is None and readiness_report is None:
        ios_status = _worst_status(control_docs_status, "pending")
    elif acceptance_ok and readiness_ok and not real_ios_verified:
        ios_status = _worst_status(control_docs_status, "warn")
    else:
        ios_status = _worst_status(control_docs_status, "fail")
    ios_status = _worst_status(ios_status, proof_status, claim_scope_status)
    if proof_status in {"fail", "pending", "warn"}:
        ios_method = "show_acceptance_proof_map_from_gui"
    elif claim_scope_status in {"fail", "pending", "warn"}:
        ios_method = "show_claim_scope_from_gui"
    else:
        ios_method = "show_p1_trial_from_gui" if normalized_stage == "p1" else "show_field_runbook_from_gui"
    add(
        "1. iOS perfect control",
        ios_status,
        (
            f"{control_docs}; events={total_events}, fail={fail_events}; "
            f"{acceptance_brief(acceptance_report or {})}; {readiness_brief(readiness_report or {})}; "
            f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}; "
            f"{proof_line}; {claim_scope_line}"
        ),
        "Real iPhone screenshot quality, click, swipe, text input, manual observation, Acceptance PASS, Readiness PASS, Proof Map closure, and Claim Scope pass wording.",
        "Open Proof Map and Claim Scope before any completion claim; then run P1 Trial, Acceptance, and Readiness for the same run_id.",
        "P1: one device first. P2: 100 screenshots and repeated HID samples. P3/P4: per-device evidence and failure isolation.",
        ios_method,
    )

    sop_docs_status, sop_docs = docs_line("sop")
    sop_artifacts = [row for row in artifact_list if row.get("name") in {
        "Field Runbook",
        "Operator Worksheet",
        "GUI SOP Board",
        "Issue Triage",
        "Rerun Playbook",
        "Recovery Drill",
        "Device Evidence Matrix",
        "Acceptance Gap",
    }]
    sop_missing = [row.get("name", "") for row in sop_artifacts if row.get("status") != "present"]
    if sop_docs_status == "pass" and not sop_missing and fail_events == 0:
        sop_status = "pass"
    elif sop_docs_status == "pass":
        sop_status = "ready" if not fail_events else "warn"
    else:
        sop_status = "fail"
    sop_status = _worst_status(sop_status, claim_scope_status)
    add(
        "2. iOS group-control SOP and issue log",
        sop_status,
        (
            f"{sop_docs}; SOP artifacts missing={len(sop_missing)}; "
            f"events={total_events}, fail={fail_events}; {claim_scope_line}"
        ),
        "Stage SOP docs, field runbook, worksheet, issue triage, rerun playbook, recovery drill, device matrix, acceptance gap, Claim Scope, and replayable failure notes.",
        "Export Runbook/SOP/Worksheet/Matrix/Triage/Rerun/Recovery/Claim Scope, then classify every failure before rerun.",
        "Follow P1 single-device SOP before P3/P4 group runs; every failure must have category, affected device, artifact, and rerun result.",
        "show_claim_scope_from_gui" if claim_scope_status in {"fail", "pending", "warn"} else "show_field_runbook_from_gui",
    )

    parity_docs_status, parity_docs = docs_line("core_parity")
    if not xp_gap_audit:
        parity_status = _worst_status(parity_docs_status, "pending")
        parity_signal = "XP Gap audit not built"
    elif xp_blocked:
        parity_status = _worst_status(parity_docs_status, "fail")
        parity_signal = f"gap_blockers={', '.join(xp_blocked[:4])}"
    elif not route_ready or not doctor_clean:
        parity_status = _worst_status(parity_docs_status, "warn")
        parity_signal = f"route_ready={route_ready}, doctor_clean={doctor_clean}"
    else:
        parity_status = _worst_status(parity_docs_status, "ready")
        parity_signal = "XP gap audit has no blocked/partial domains"
    add(
        "3. iMouse XP core functions and docs",
        parity_status,
        (
            f"{parity_docs}; {parity_signal}; required_missing={len(required_missing)}, "
            f"recommended_missing={len(recommended_missing)}"
        ),
        "XP-style API/helper parity, receiver/capture, HID, vision, scripts, GUI docs, and evidence pack with no required missing items.",
        "Export XP Gap and Evidence Pack; fix the first blocked capability before adding cosmetic GUI work.",
        "Run XP API/client tests, then validate the same actions through GUI/script on real receiver/HID/iPhone evidence.",
        "write_xp_gap_audit_from_gui",
    )

    iteration_docs_status, iteration_docs = docs_line("iteration")
    if iteration_docs_status != "pass":
        iteration_status = "fail"
    elif fail_events:
        iteration_status = "warn"
    else:
        iteration_status = "pass"
    add(
        "4. XP iteration lessons and pitfalls",
        iteration_status,
        f"{iteration_docs}; failed evidence events={fail_events}; stage={normalized_stage.upper()}",
        "Public-source refresh, iteration lessons, route selection, receiver/HID benchmark, and pitfall-driven backlog.",
        "Open Knowledge Center and Triage after each run; update backlog from real failure categories.",
        "For every new bench run, compare failures against receiver, HID, calibration, vision, group dispatch, and performance pitfall buckets.",
        "show_gui_knowledge_center_from_gui" if fail_events == 0 else "show_issue_triage_from_gui",
    )
    return rows


def gui_goal_gate_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_blocker = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_blocker == "none" and status in {"fail", "pending"}:
            first_blocker = str(row.get("goal", "") or "unknown")
    return (
        f"Goal gate {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_blocker={first_blocker}"
    )


def write_gui_goal_gate_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 目标门控 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This goal gate maps the user's acceptance goals to required proof. It does not write evidence or prove real iPhone response.",
        "",
        "## Acceptance Goals",
        "",
        "| Goal | Status | Current evidence | Evidence needed | Next action | Test method | GUI action |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('goal', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current_evidence', ''))} | {_md_cell(row.get('evidence_needed', ''))} | "
            f"{_md_cell(row.get('next_action', ''))} | {_md_cell(row.get('test_method', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | Refresh Goal Gate | Refresh | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Do not mark the project complete unless all four rows are PASS and the iOS control row is backed by real-device evidence, Proof Map closure, Claim Scope pass wording, Acceptance PASS, Readiness PASS, and no unexplained fail events.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _goal_gui_action(method: str) -> str:
    return {
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_field_runbook_from_gui": "Open Runbook",
        "show_acceptance_proof_map_from_gui": "Open Proof Map",
        "show_claim_scope_from_gui": "Open Claim Scope",
        "write_xp_gap_audit_from_gui": "Export XP Gap",
        "show_gui_knowledge_center_from_gui": "Open Knowledge",
        "show_issue_triage_from_gui": "Open Triage",
    }.get(method, method)


def _route_nested_fields_gate(route_decision: dict | None, fields: tuple[str, ...]) -> tuple[str, str]:
    if not route_decision:
        return "pending", "route decision not loaded"
    missing: list[str] = []
    placeholders: list[str] = []
    for field in fields:
        value = nested_get(route_decision, field, "")
        if isinstance(value, list):
            text = ", ".join(str(item).strip() for item in value if str(item).strip())
        elif isinstance(value, bool):
            text = "true" if value else "false"
        elif value is None:
            text = ""
        else:
            text = str(value).strip()
        if not text:
            missing.append(field)
        elif _route_form_has_placeholder(text):
            placeholders.append(field)
    if missing or placeholders:
        parts = []
        if missing:
            parts.append(f"missing={', '.join(missing[:3])}")
        if placeholders:
            parts.append(f"placeholder={', '.join(placeholders[:3])}")
        return "fail", "; ".join(parts)
    return "pass", "fields present: " + ", ".join(fields[:4])


def _route_open_blockers_text(route_decision: dict | None) -> str:
    if not route_decision:
        return ""
    blockers = nested_get(route_decision, "decision.open_blockers", [])
    if isinstance(blockers, list):
        return "; ".join(str(item).strip() for item in blockers if str(item).strip())
    return str(blockers or "").strip()


def _route_allowed_to_run_p1(route_decision: dict | None) -> bool:
    if not route_decision:
        return False
    value = nested_get(route_decision, "decision.allowed_to_run_p1", False)
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"true", "yes", "y", "1", "pass", "allow", "allowed"}


def _hardware_scan_match_text(
    hardware_scan_rows: list[dict] | None,
    *,
    serial_port: str = "",
    hid_id: str = "",
) -> tuple[str, str]:
    rows = hardware_scan_rows or []
    if not rows:
        return "ready", "hardware scan not run in GUI"
    needle_values = [value.lower() for value in (serial_port.strip(), hid_id.strip()) if value.strip()]
    if not needle_values:
        return "warn", f"scan_rows={len(rows)}, route has no serial/id target"
    for row in rows:
        haystack = " ".join(str(value).lower() for value in row.values())
        if any(needle in haystack for needle in needle_values):
            return "pass", f"scan_rows={len(rows)}, target_match=True"
    return "warn", f"scan_rows={len(rows)}, target_match=False"


def field_kit_gate_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    hardware_scan_rows: list[dict] | None = None,
) -> list[dict[str, str]]:
    """Build the pre-run procurement and field-kit gate without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    allowed = _route_allowed_to_run_p1(route_decision)
    blockers_text = _route_open_blockers_text(route_decision)
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}
    hid_route = str(route_values.get("hid.route", nested_get(route_decision or {}, "hid.route", "")) or "").strip()
    serial_port = str(route_values.get("hid.serial_port", nested_get(route_decision or {}, "hid.serial_port", "")) or "").strip()
    hid_id = str(route_values.get("hid.id", nested_get(route_decision or {}, "hid.id", "")) or "").strip()

    rows: list[dict[str, str]] = []

    def add(
        gate: str,
        status: str,
        current: str,
        required: str,
        sop: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "gate": gate,
            "status": status,
            "current": current,
            "required": required,
            "sop": sop,
            "stop_rule": stop_rule,
            "gui_action": _field_kit_gate_gui_action(method),
            "method": method,
        })

    missing_docs = [source for source in FIELD_KIT_GATE_DOCS if not (root / source).exists()]
    add(
        "Procurement and SOP source docs",
        "pass" if not missing_docs else "fail",
        (
            f"docs_ready={len(FIELD_KIT_GATE_DOCS) - len(missing_docs)}/{len(FIELD_KIT_GATE_DOCS)}"
            + ("" if not missing_docs else f"; missing={', '.join(missing_docs[:3])}")
        ),
        "Hardware bench, mainstream route, receiver/capture, HID protocol, field matrix, and P1 runbook docs present.",
        "Review these docs before buying or substituting receiver, HID, Hub, cable, or capture hardware.",
        "Stop procurement if the chosen route cannot be mapped to a local SOP row and evidence path.",
        "show_gui_knowledge_center_from_gui",
    )

    scope_status = "pass" if selected_devices and len(selected_devices) >= required_devices else "fail"
    add(
        "Run identity and device scope",
        scope_status,
        f"selected={len(selected_devices)}, required={required_devices}, devices={', '.join(selected_devices) or '-'}",
        "One run_id, one explicit stage, and a traceable device list that matches the physical iPhone labels.",
        "Select the real target devices and keep the same run_id unless a blocker forces a new run.",
        "Stop if the operator cannot point to the exact iPhone, cable, Hub port, and evidence file for this run.",
        "record_component_metadata" if scope_status == "pass" else "edit_route_decision_from_gui",
    )

    receiver_fields = (
        "receiver.route",
        "receiver.name",
        "receiver.version",
        "receiver.path",
        "receiver.start_command",
        "receiver.airplay_name",
        "receiver.capture_method",
        "receiver.license_status",
    )
    receiver_status, receiver_detail = _route_nested_fields_gate(route_decision, receiver_fields)
    add(
        "Receiver procurement and capture route",
        receiver_status,
        f"{receiver_detail}; route_ready={route_ready}, doctor_clean={doctor_clean}",
        "Chosen receiver/capture route with real version, install path, start command, AirPlay name, capture method, and license/status.",
        "Start from UxPlay or the selected Windows/wired/capture-card route, then prove one visible screenshot before HID actions.",
        "Stop if the receiver is still a placeholder, the capture window cannot be identified, or Doctor reports a receiver failure.",
        "edit_route_decision_from_gui" if receiver_status != "pass" else "run_preflight_doctor",
    )

    hid_fields = (
        "hid.route",
        "hid.provider",
        "hid.id",
        "hid.firmware",
        "hid.serial_port",
        "hid.baudrate",
        "bench.hub_port",
        "bench.cable_id",
    )
    hid_fields_status, hid_detail = _route_nested_fields_gate(route_decision, hid_fields)
    scan_status, scan_detail = _hardware_scan_match_text(
        hardware_scan_rows,
        serial_port=serial_port,
        hid_id=hid_id,
    )
    hid_status = _worst_status(hid_fields_status, scan_status)
    add(
        "HID procurement, firmware, and serial binding",
        hid_status,
        f"{hid_detail}; hid.route={hid_route or '-'}; {scan_detail}",
        "HID provider/id/firmware/serial/baudrate plus Hub port and cable id, with GUI scan when hardware is present.",
        "Scan hardware, bind only the selected HID, and keep firmware/serial/cable labels in Route Decision before P1 real actions.",
        "Stop if the HID target cannot be scanned or tied to the same iPhone/cable/Hub port.",
        "scan_hardware" if hid_status != "pass" else "record_component_metadata",
    )

    iphone_fields = (
        "iphone.id",
        "iphone.model",
        "iphone.ios_version",
        "iphone.orientation",
        "iphone.assistive_touch",
        "iphone.pointer_speed",
    )
    iphone_status, iphone_detail = _route_nested_fields_gate(route_decision, iphone_fields)
    assistive_touch = str(route_values.get("iphone.assistive_touch", "") or "").strip().lower()
    if iphone_status == "pass" and assistive_touch not in {"on", "enabled", "true", "yes", "1"}:
        iphone_status = "warn"
        iphone_detail = f"{iphone_detail}; AssistiveTouch={assistive_touch or '-'} needs operator confirmation"
    add(
        "iPhone setup and operator settings",
        iphone_status,
        iphone_detail,
        "iPhone id/model/iOS version/orientation plus AssistiveTouch and pointer speed captured from the real device.",
        "Set the phone to the agreed orientation and pointer profile before screenshot/calibration/HID tests.",
        "Stop if the model/iOS/orientation cannot be read from the device or if pointer settings are unknown.",
        "edit_route_decision_from_gui" if iphone_status != "pass" else "show_p1_trial_from_gui",
    )

    bench_fields = (
        "bench.device_id",
        "bench.device_ids",
        "bench.hub_id",
        "bench.hub_port",
        "bench.cable_id",
        "bench.network",
        "bench.operator",
    )
    bench_status, bench_detail = _route_nested_fields_gate(route_decision, bench_fields)
    add(
        "Hub, cable, network, and operator ledger",
        bench_status,
        bench_detail,
        "Hub id, Hub port, cable id, network topology, operator, and selected device ids recorded before the run.",
        "Label every port/cable and keep one operator accountable for the evidence and rerun notes.",
        "Stop if a disconnect/reconnect cannot be isolated to a single device, cable, Hub port, or network leg.",
        "record_component_metadata" if bench_status == "pass" else "edit_route_decision_from_gui",
    )

    evidence_fields = (
        "evidence.expected_jsonl",
        "evidence.expected_doctor_markdown",
        "evidence.expected_readiness_markdown",
        "evidence.plan.screenshot_probe",
        "evidence.plan.reconnect_probe",
        "evidence.plan.manual_observation",
        "evidence.plan.component_metadata",
    )
    evidence_status, evidence_detail = _route_nested_fields_gate(route_decision, evidence_fields)
    if evidence_status == "pass" and evidence_exists and fail_events:
        evidence_status = "warn"
        evidence_detail = f"{evidence_detail}; existing_events={total_events}, fail={fail_events}"
    add(
        "Evidence plan and artifact ledger",
        evidence_status,
        f"{evidence_detail}; evidence_exists={evidence_exists}, events={total_events}",
        "Expected JSONL, Doctor, Readiness, screenshot probe, reconnect probe, manual observation, and component metadata plan.",
        "Before the first HID action, decide which screenshot/video/log artifacts will prove or disprove each claim.",
        "Stop if the plan cannot explain where screenshot, click, swipe, text, log, and failure-category evidence will be stored.",
        "write_evidence_pack_from_gui" if evidence_status == "pass" else "edit_route_decision_from_gui",
    )

    if route_report is None:
        route_gate_status = "pending"
        route_gate_text = "route decision not validated"
    else:
        route_gate_status = "pass" if route_ready else "fail"
        route_gate_text = route_decision_brief(route_report)
    if doctor_report is None:
        doctor_gate_status = "pending"
        doctor_gate_text = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "unknown") or "unknown").lower()
        doctor_gate_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_gate_text = doctor_brief(doctor_report)
    decision_status = "pass" if route_decision and allowed and not blockers_text else "fail" if route_decision else "pending"
    stop_status = _worst_status(scope_status, route_gate_status, doctor_gate_status, decision_status)
    add(
        "Open P1 stop line",
        stop_status,
        (
            f"allowed={allowed}, blockers={blockers_text or 'none'}; "
            f"{route_gate_text}; {doctor_gate_text}"
        ),
        "Route Decision ready=true, Allow P1 real run=true, no open blockers, Doctor has no fail, and sufficient selected devices.",
        "Run Route Validate and Doctor after the field kit is filled; only then open P1 Trial or Start Pack.",
        "Stop all real HID actions if any blocker is open, Doctor fails, route is not ready, or selected device scope is short.",
        "edit_route_decision_from_gui" if stop_status != "pass" else "show_first_run_packet_from_gui",
    )

    if hid_route == "xp_hardware":
        xp_status = "ready" if hid_fields_status == "pass" else "fail"
        xp_current = f"hid.route=xp_hardware; {hid_detail}; comparison evidence not recorded yet"
    elif hid_route:
        xp_status = "warn"
        xp_current = f"hid.route={hid_route}; generic P1 may continue, XP hardware parity remains blocked"
    else:
        xp_status = "pending"
        xp_current = "hid.route not selected"
    add(
        "XP hardware comparison question",
        xp_status,
        xp_current,
        "A legal XP hardware/firmware sample, CH9329 baseline, same iPhone/page, and side-by-side click/swipe/type/recovery results.",
        "Run generic P1 on the chosen HID route, but keep XP hardware/4.4/auto-binding claims out of scope until the comparison bench exists.",
        "Stop XP parity claims if only CH9329/self-built/Bluetooth HID has been observed or if XP hardware behavior is not documented.",
        "write_xp_gap_audit_from_gui",
    )
    return rows


def field_kit_gate_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_stop = _first_attention_value(rows, "gate", statuses={"fail", "pending"})
    return (
        f"Field kit gate {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_stop={first_stop}"
    )


def write_field_kit_gate_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI Field Kit 门控 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This is a pre-run procurement/material/readiness gate. It does not write evidence or prove real iPhone control.",
        "",
        "## Field Kit Gates",
        "",
        "| Gate | Status | Current | Required | SOP check | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('gate', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('required', ''))} | "
            f"{_md_cell(row.get('sop', ''))} | {_md_cell(row.get('stop_rule', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | Refresh Kit Gate | Refresh | Do not run | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Use this gate before the first real HID action. Generic P1 can only start when the Open P1 stop line is PASS. XP hardware parity still needs a separate side-by-side comparison even when generic P1 is allowed.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


