def _setting_enabled_text(value: str) -> bool:
    return str(value or "").strip().lower() in {"on", "enabled", "true", "yes", "1", "never"}


def ios_field_sop_rows(
    *,
    stage: str = "p1",
    docs_root: str | Path = ".",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build iPhone field settings SOP rows without writing evidence."""
    root = Path(docs_root)
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_clean = doctor_overall == "ok"
    doctor_failed = doctor_overall == "fail"
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    component_status, component_text = _acceptance_check_line(acceptance_report, "component_traceability")
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    values = route_decision_form_values(route_decision or {}) if route_decision else {}

    def field_gate(fields: tuple[str, ...]) -> tuple[str, str]:
        return _route_nested_fields_gate(route_decision, fields)

    rows: list[dict[str, str]] = []
    for topic in IOS_FIELD_SOP_TOPICS:
        key = str(topic["key"])
        source = str(topic["source"])
        doc_status = "pass" if (root / source).exists() else "fail"
        status = doc_status
        current = (
            f"stage={normalized_stage.upper()}; selected={len(selected_devices)}/{required_devices}; "
            f"route_ready={route_ready}; doctor={doctor_overall or '-'}; real_ios_verified={real_ios_verified}"
        )

        if key == "device_identity":
            fields_status, detail = field_gate((
                "iphone.id",
                "iphone.model",
                "iphone.ios_version",
                "iphone.orientation",
                "bench.device_id",
            ))
            if len(selected_devices) < required_devices:
                status = _worst_status(doc_status, "fail")
                current = f"selected={len(selected_devices)}, required={required_devices}; {detail}"
            else:
                status = _worst_status(doc_status, "ready" if fields_status == "pass" else fields_status)
                current = f"selected={len(selected_devices)}, required={required_devices}; {detail}; component={component_text}"
        elif key == "assistive_touch_pointer":
            fields_status, detail = field_gate(("iphone.assistive_touch", "iphone.pointer_speed"))
            assistive = str(values.get("iphone.assistive_touch", "") or "")
            if fields_status != "pass":
                status = _worst_status(doc_status, fields_status)
            elif not _setting_enabled_text(assistive):
                status = _worst_status(doc_status, "warn")
            elif manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
            else:
                status = _worst_status(doc_status, "ready" if manual_status != "fail" else "fail")
            current = f"{detail}; AssistiveTouch={assistive or '-'}; manual={manual_text}; real_ios_verified={real_ios_verified}"
        elif key == "rotation_menu_safety":
            fields_status, detail = field_gate(("iphone.rotation_lock", "iphone.assistive_touch_menu"))
            rotation_lock = str(values.get("iphone.rotation_lock", "") or "")
            menu_state = str(values.get("iphone.assistive_touch_menu", "") or "").strip().lower()
            if fields_status != "pass":
                status = _worst_status(doc_status, fields_status)
            elif not _setting_enabled_text(rotation_lock):
                status = _worst_status(doc_status, "warn")
            elif menu_state not in {"hidden", "minimized"}:
                status = _worst_status(doc_status, "warn")
            elif screenshot_status == "pass" and manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
            else:
                status = _worst_status(doc_status, "ready" if manual_status != "fail" else "fail")
            current = (
                f"{detail}; rotation_lock={rotation_lock or '-'}; "
                f"assistive_touch_menu={menu_state or '-'}; screenshot={screenshot_text}; manual={manual_text}"
            )
        elif key == "keyboard_mouse_access":
            fields_status, detail = field_gate(("iphone.full_keyboard_access", "iphone.trackpad_mouse"))
            full_keyboard = str(values.get("iphone.full_keyboard_access", "") or "")
            trackpad = str(values.get("iphone.trackpad_mouse", "") or "")
            if fields_status != "pass":
                status = _worst_status(doc_status, fields_status)
            elif not (_setting_enabled_text(full_keyboard) and _setting_enabled_text(trackpad)):
                status = _worst_status(doc_status, "warn")
            elif manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
            else:
                status = _worst_status(doc_status, "ready" if manual_status != "fail" else "fail")
            current = (
                f"{detail}; full_keyboard_access={full_keyboard or '-'}; "
                f"trackpad_mouse={trackpad or '-'}; manual={manual_text}"
            )
        elif key == "mouse_parameter_profile":
            fields_status, detail = field_gate((
                "iphone.model",
                "iphone.ios_version",
                "iphone.orientation",
                "iphone.pointer_speed",
                "iphone.mouse_parameter_profile",
                "iphone.qr_scan_policy",
            ))
            profile = str(values.get("iphone.mouse_parameter_profile", "") or "")
            qr_policy = str(values.get("iphone.qr_scan_policy", "") or "")
            if fields_status != "pass":
                status = _worst_status(doc_status, fields_status)
            elif manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif screenshot_status == "pass" and manual_status == "pass" and real_ios_verified:
                status = _worst_status(doc_status, "pass")
            else:
                status = _worst_status(doc_status, "ready")
            current = (
                f"{detail}; profile={profile or '-'}; qr_scan_policy={qr_policy or '-'}; "
                f"screenshot={screenshot_text}; manual={manual_text}; real_ios_verified={real_ios_verified}"
            )
        elif key == "screen_lock_brightness":
            fields_status, detail = field_gate(("iphone.auto_lock", "iphone.brightness", "iphone.focus_mode"))
            auto_lock = str(values.get("iphone.auto_lock", "") or "").strip().lower()
            if fields_status != "pass":
                status = _worst_status(doc_status, fields_status)
            elif auto_lock not in {"never", "off", "disabled"}:
                status = _worst_status(doc_status, "warn")
            elif screenshot_status == "pass":
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, "pending" if screenshot_status != "fail" else "fail")
            current = f"{detail}; auto_lock={auto_lock or '-'}; screenshot={screenshot_text}"
        elif key == "network_airplay":
            fields_status, detail = field_gate((
                "bench.network",
                "receiver.airplay_name",
                "receiver.name",
                "receiver.capture_method",
                "receiver.window_binding.title",
            ))
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif fields_status == "pass" and route_ready and doctor_clean:
                status = _worst_status(doc_status, "ready")
            elif fields_status == "pass":
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, fields_status)
            current = f"{detail}; route_ready={route_ready}; doctor={doctor_overall or '-'}; screenshot={screenshot_text}"
        elif key == "hub_cable_power":
            fields_status, detail = field_gate((
                "bench.hub_id",
                "bench.hub_port",
                "bench.cable_id",
                "hid.id",
                "hid.firmware",
                "hid.serial_port",
                "bench.operator",
            ))
            if doctor_failed:
                status = _worst_status(doc_status, "fail")
            elif fields_status == "pass":
                status = _worst_status(doc_status, "ready")
            else:
                status = _worst_status(doc_status, fields_status)
            current = f"{detail}; doctor={doctor_overall or '-'}; component={component_text}"
        elif key == "baseline_artifacts":
            if screenshot_status == "pass" and manual_status == "pass" and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif screenshot_status == "pass" and manual_status == "pass":
                status = _worst_status(doc_status, "warn")
            elif screenshot_status == "fail" or manual_status == "fail":
                status = _worst_status(doc_status, "fail")
            elif evidence_exists:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "pending")
            current = (
                f"screenshot={screenshot_text}; manual={manual_text}; "
                f"events={total_events}, fail={fail_events}; real_ios_verified={real_ios_verified}"
            )
        elif key == "settings_replay":
            if route_ready and evidence_exists and readiness_report is not None and fail_events == 0:
                status = _worst_status(doc_status, "ready" if not real_ios_verified else "pass")
            elif fail_events:
                status = _worst_status(doc_status, "warn")
            elif route_ready:
                status = _worst_status(doc_status, "pending")
            else:
                status = _worst_status(doc_status, "pending" if route_report is None else "fail")
            current = f"route_ready={route_ready}; evidence_exists={evidence_exists}; events={total_events}, fail={fail_events}; readiness={readiness_ok}"
        elif key == "claim_boundary":
            if acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
                status = _worst_status(doc_status, "pass")
            elif acceptance_report is None and readiness_report is None:
                status = _worst_status(doc_status, "pending")
            elif acceptance_ok and readiness_ok and not real_ios_verified:
                status = _worst_status(doc_status, "warn")
            else:
                status = _worst_status(doc_status, "fail")
            current = (
                f"acceptance_ok={acceptance_ok}; readiness_ok={readiness_ok}; "
                f"real_ios_verified={real_ios_verified}; fail_events={fail_events}"
            )

        rows.append({
            "key": key,
            "check": str(topic["check"]),
            "status": status,
            "current": current,
            "setting": str(topic["setting"]),
            "why": str(topic["why"]),
            "evidence_gate": str(topic["evidence_gate"]),
            "stop_rule": str(topic["stop_rule"]),
            "source": source,
            "gui_action": _ios_field_sop_gui_action(str(topic["method"])),
            "method": str(topic["method"]),
        })
    return rows


def ios_field_sop_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_stop = _first_attention_value(rows, "check", statuses={"fail", "pending", "warn"})
    return (
        f"iOS field SOP {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_stop={first_stop}"
    )


def write_ios_field_sop_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# iOS Field Settings SOP {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This SOP checklist records field settings and next GUI actions. It does not write evidence, does not prove iOS control, and does not prove XP parity.",
        "",
        "## Settings Rows",
        "",
        "| Check | Status | Current | Required setting | Why it matters | Evidence gate | Stop rule | Source | GUI action |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('check', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('setting', ''))} | "
            f"{_md_cell(row.get('why', ''))} | {_md_cell(row.get('evidence_gate', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | `{_md_cell(row.get('source', ''))}` | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | Refresh iOS SOP | - | - | Do not run | - | - |")
    lines.extend([
        "",
        "## Use Rule",
        "",
        "Use this SOP before the first receiver/HID run and before every rerun after hardware or iPhone settings change. A ready settings row only opens the next test; Acceptance, Readiness, JSONL evidence, screenshots, logs, and manual observation decide claims.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def hardware_bench_rows(
    *,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    callback_rows_data: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the hardware bench checklist rows without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    callback_rows = callback_rows_data or []
    callback_warn = sum(
        1
        for row in callback_rows
        if str(row.get("severity", "")).lower() in {"warn", "fail", "error"}
    )
    route_values = route_decision_form_values(route_decision or {}) if route_decision else {}

    rows: list[dict[str, str]] = []

    def add(
        check: str,
        status: str,
        current: str,
        required: str,
        test_method: str,
        next_action: str,
        method: str,
    ) -> None:
        rows.append({
            "check": check,
            "status": status,
            "current": current,
            "required": required,
            "test_method": test_method,
            "next_action": next_action,
            "gui_action": _hardware_bench_gui_action(method),
            "method": method,
        })

    ledger_fields = (
        "bench.device_id",
        "bench.device_ids",
        "iphone.id",
        "iphone.model",
        "iphone.ios_version",
        "bench.hub_id",
        "bench.hub_port",
        "bench.cable_id",
        "bench.operator",
    )
    ledger_status, ledger_detail = _route_fields_gate(route_decision, ledger_fields)
    if len(selected_devices) < required_devices:
        ledger_status = _worst_status(ledger_status, "fail")
        ledger_detail = f"{ledger_detail}; selected={len(selected_devices)}, required={required_devices}"
    add(
        "Bench ledger and labels",
        ledger_status,
        ledger_detail,
        "device_id, iPhone/iOS, HID, receiver, Hub port, cable, operator, and run_id must be traceable.",
        "Before real run, label every device/cable/Hub port and save Route Decision + Record Metadata.",
        "Edit Route, Use Metadata, Scan Issues, Save + Validate, then Record Metadata per device.",
        "edit_route_decision_from_gui" if ledger_status != "pass" else "record_component_metadata",
    )

    receiver_fields = (
        "receiver.route",
        "receiver.name",
        "receiver.version",
        "receiver.path",
        "receiver.start_command",
        "receiver.airplay_name",
        "receiver.capture_method",
    )
    receiver_status, receiver_detail = _route_fields_gate(route_decision, receiver_fields)
    receiver_status = _worst_status(
        receiver_status,
        "pass" if route_ready else "pending" if route_report is None else "fail",
        "pass" if doctor_clean else "pending" if doctor_report is None else "fail",
    )
    add(
        "Receiver/capture route",
        receiver_status,
        f"{receiver_detail}; route_ready={route_ready}, doctor_clean={doctor_clean}",
        "One chosen receiver/capture route with version/path/start command/AirPlay name/capture method and Doctor clean.",
        "Run 1 visible screenshot, then 100 screenshot quality samples before claiming capture stability.",
        "Edit Route, run Doctor, start receiver/capture, then use Screenshot and Shot Bench.",
        "edit_route_decision_from_gui" if receiver_status != "pass" else "run_capture_quality_bench_from_gui",
    )

    hid_fields = (
        "hid.route",
        "hid.provider",
        "hid.id",
        "hid.firmware",
        "hid.serial_port",
        "bench.hub_port",
        "bench.cable_id",
    )
    hid_status, hid_detail = _route_fields_gate(route_decision, hid_fields)
    if manual_status == "pass":
        hid_status = _worst_status(hid_status, "pass")
    elif hid_status == "pass":
        hid_status = "ready"
    add(
        "HID binding and iPhone response",
        hid_status,
        f"{hid_detail}; manual={manual_text}",
        "HID provider/id/firmware/serial/Hub/cable ledger plus observed real iPhone pointer/click/swipe/type response.",
        "Scan hardware, bind the selected device, run click/swipe/type samples, and record Manual pass/fail.",
        "Use Scan/Bind, then P1 Trial rows for HID click, swipe, and keyboard input.",
        "scan_hardware" if hid_status != "pass" else "show_p1_trial_from_gui",
    )

    iphone_fields = (
        "iphone.id",
        "iphone.model",
        "iphone.ios_version",
        "iphone.orientation",
        "iphone.assistive_touch",
        "iphone.pointer_speed",
    )
    iphone_status, iphone_detail = _route_fields_gate(route_decision, iphone_fields)
    if iphone_status == "pass" and manual_status != "pass":
        iphone_status = "ready"
    add(
        "iPhone settings",
        iphone_status,
        iphone_detail,
        "Model, iOS version, orientation, AssistiveTouch, pointer speed, brightness/lock-screen policy recorded.",
        "Confirm iPhone system pointer/keyboard settings before HID tests and keep screenshots/recordings for failures.",
        "Edit Route for static settings, then record Manual observations when the real screen responds.",
        "edit_route_decision_from_gui" if iphone_status != "pass" else "show_p1_trial_from_gui",
    )

    stability_fields = (
        "bench.hub_id",
        "bench.hub_port",
        "bench.cable_id",
        "bench.network",
    )
    stability_status, stability_detail = _route_fields_gate(route_decision, stability_fields)
    if fail_events:
        stability_status = _worst_status(stability_status, "warn")
    elif stability_status == "pass" and normalized_stage in {"p3", "p4"}:
        stability_status = "ready"
    add(
        "Hub/cable/network isolation",
        stability_status,
        f"{stability_detail}; fail_events={fail_events}",
        "Hub id/port, cable id, network topology, and unplug/replug behavior must be traceable per device.",
        "Inject one-device unplug/replug and receiver disconnect tests; other devices must keep separate results.",
        "Use Field Runbook for fault injection and Matrix/Triage for per-device isolation.",
        "show_field_runbook_from_gui",
    )

    evidence_status = _worst_status(
        "pass" if evidence_exists and total_events > 0 and fail_events == 0 else "fail",
        screenshot_status,
        manual_status,
    )
    add(
        "Screenshot and control evidence",
        evidence_status,
        f"events={total_events}, fail={fail_events}; screenshot={screenshot_text}; manual={manual_text}",
        "JSONL evidence must include screenshot_quality and manual real-iPhone observations for click/swipe/type.",
        "Run P1 Trial, then Acceptance and Gap; do not treat API success as iPhone response.",
        "Use P1 Trial and Acceptance Gap until screenshot/manual checks pass.",
        "show_p1_trial_from_gui" if evidence_status != "pass" else "run_acceptance_from_gui",
    )

    hid_route = str(route_values.get("hid.route", "") or "").strip()
    xp_status = "pass" if hid_route == "xp_hardware" and manual_status == "pass" else "ready" if hid_route == "xp_hardware" else "pending"
    add(
        "XP hardware comparison",
        xp_status,
        f"hid.route={hid_route or '-'}; manual={manual_text}",
        "If XP dedicated hardware is available, compare enumeration, binding, firmware, click error, swipe release, input, and recovery against CH9329.",
        "Do not modify CH9329 provider assumptions until XP hardware behavior is legally observed and recorded.",
        "Export XP Gap, then run the hardware benchmark table with the same iPhone/page for both hardware routes.",
        "write_xp_gap_audit_from_gui",
    )

    if not callback_rows:
        log_status = "pending"
        log_detail = "no receiver/HID log rows attached"
    elif callback_warn:
        log_status = "warn"
        log_detail = f"callback/log rows={len(callback_rows)}, warn/fail/error={callback_warn}"
    else:
        log_status = "pass"
        log_detail = f"callback/log rows={len(callback_rows)}, warn/fail/error=0"
    add(
        "Callback/log triage",
        log_status,
        log_detail,
        "Receiver, capture, HID, USB, and generic error logs should be attached after each bench run.",
        "Attach receiver/HID logs and classify failures before rerunning the same bench path.",
        "Use Attach Log, Callback, Timeline, and Triage.",
        "attach_callback_log_from_gui" if log_status != "pass" else "show_issue_triage_from_gui",
    )
    return rows


def hardware_bench_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_blocker = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_blocker == "none" and status in {"fail", "pending"}:
            first_blocker = str(row.get("check", "") or "unknown")
    return (
        f"Hardware bench {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_blocker={first_blocker}"
    )


def write_hardware_bench_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI 硬件基准 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This hardware bench is a field checklist and review index. It does not write evidence or prove real iPhone response.",
        "",
        "## Bench Checks",
        "",
        "| Check | Status | Current | Required evidence | Test method | Next action | GUI action |",
        "|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('check', ''))} | `{_md_cell(row.get('status', ''))}` | "
            f"{_md_cell(row.get('current', ''))} | {_md_cell(row.get('required', ''))} | "
            f"{_md_cell(row.get('test_method', ''))} | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| None | `pending` | no rows built | Refresh Hardware Bench | Refresh | - | - |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Do not run real HID actions until route, Doctor, and bench ledger rows are clean. Do not promote from P1 unless screenshot/control evidence and manual real-iPhone observations are present.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _route_fields_gate(route_decision: dict | None, fields: tuple[str, ...]) -> tuple[str, str]:
    if not route_decision:
        return "pending", "route decision not loaded"
    values = route_decision_form_values(route_decision)
    missing: list[str] = []
    placeholders: list[str] = []
    for field in fields:
        value = str(values.get(field, "") or "").strip()
        if not value:
            missing.append(field)
        elif _route_form_has_placeholder(value):
            placeholders.append(field)
    if missing or placeholders:
        parts = []
        if missing:
            parts.append(f"missing={', '.join(missing[:3])}")
        if placeholders:
            parts.append(f"placeholder={', '.join(placeholders[:3])}")
        return "fail", "; ".join(parts)
    return "pass", "fields present: " + ", ".join(fields[:4])


def _hardware_bench_gui_action(method: str) -> str:
    return {
        "edit_route_decision_from_gui": "Edit Route",
        "record_component_metadata": "Record Metadata",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "scan_hardware": "Scan Hardware",
        "show_field_runbook_from_gui": "Open Runbook",
        "run_acceptance_from_gui": "Run Acceptance",
        "write_xp_gap_audit_from_gui": "Export XP Gap",
        "attach_callback_log_from_gui": "Attach Log",
        "show_issue_triage_from_gui": "Open Triage",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
    }.get(method, method)


def field_evidence_wizard_rows(
    *,
    run_id: str = "",
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_decision: dict | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    callback_rows_data: list[dict[str, str]] | None = None,
    command_queue_items: list[dict] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    """Build the ordered field evidence wizard without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_clean = bool(doctor_report and str(doctor_report.get("overall", "") or "").lower() == "ok")
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    callback_rows = callback_rows_data or []
    callback_warn = sum(
        1
        for row in callback_rows
        if str(row.get("severity", "")).lower() in {"warn", "fail", "error"}
    )
    queue_rows = command_queue_rows(command_queue_items or [])
    template_rows = template_asset_rows_data or []
    template_fail = sum(1 for row in template_rows if row.get("status") == "fail")
    artifact_list = artifact_rows or []
    required_missing = [
        row.get("name", "")
        for row in artifact_list
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        lane: str,
        status: str,
        current: str,
        operator_step: str,
        evidence: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "lane": lane,
            "status": status,
            "current": current,
            "operator_step": operator_step,
            "gui_action": _field_wizard_gui_action(method),
            "evidence": evidence,
            "stop_rule": stop_rule,
            "method": method,
        })

    scope_status = "pass" if selected_devices and len(selected_devices) >= required_devices else "fail"
    add(
        "1",
        "Run identity and device scope",
        scope_status,
        f"run_id={run_id or '-'}; selected={len(selected_devices)}, required={required_devices}",
        "Create one run_id for the bench, select the target devices, and keep the same run_id until a blocker forces a rerun.",
        "Device selection, run_id, and component metadata must be visible before any real HID action.",
        "Stop if the selected device count is below the stage requirement or the operator cannot trace the target iPhone.",
        "record_component_metadata",
    )

    ledger_fields = (
        "bench.device_id",
        "bench.device_ids",
        "iphone.id",
        "iphone.model",
        "iphone.ios_version",
        "receiver.name",
        "receiver.version",
        "hid.id",
        "hid.firmware",
        "bench.hub_id",
        "bench.hub_port",
        "bench.cable_id",
        "bench.operator",
    )
    ledger_status, ledger_detail = _route_fields_gate(route_decision, ledger_fields)
    add(
        "2",
        "Physical ledger",
        ledger_status,
        ledger_detail,
        "Fill receiver, HID, iPhone, hub, cable, port, and operator values from the real bench labels.",
        "Route Decision JSON plus Record Metadata evidence for each selected iPhone.",
        "Stop if any field is blank, placeholder-shaped, or copied from a previous bench without verification.",
        "edit_route_decision_from_gui" if ledger_status != "pass" else "record_component_metadata",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route decision not validated"
    else:
        route_status = "pass" if route_ready else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "3",
        "Route gate",
        route_status,
        route_current,
        "Validate the route after the ledger is filled; do not use dry-run success as route evidence.",
        "Route Decision report with ok=true and ready=true.",
        "Stop if receiver, capture, HID, iPhone, or decision blockers remain open.",
        "edit_route_decision_from_gui",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_current = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "unknown") or "unknown").lower()
        doctor_status = "pass" if overall == "ok" else "warn" if overall == "warn" else "fail"
        doctor_current = doctor_brief(doctor_report)
    add(
        "4",
        "Preflight doctor",
        doctor_status,
        doctor_current,
        "Run Doctor against the same route and fix server, receiver, serial, and dependency issues first.",
        "Doctor report artifact for this run_id.",
        "Stop if Doctor has fail; warn requires an explicit operator note before real actions.",
        "run_preflight_doctor",
    )

    screenshot_gate = _worst_status(
        "pass" if route_ready and doctor_clean else "pending",
        screenshot_status,
    )
    add(
        "5",
        "Receiver screenshot",
        screenshot_gate,
        f"{screenshot_text}; route_ready={route_ready}, doctor_clean={doctor_clean}",
        "Start the receiver/capture route and take one visible screenshot before any click or swipe.",
        "Screenshot quality evidence with orientation, active area, and no black/blurred/incorrect window capture.",
        "Stop if capture is black, stale, cropped incorrectly, wrong device, or orientation is ambiguous.",
        "screenshot",
    )

    calibration_status = "ready" if screenshot_status == "pass" else "pending"
    add(
        "6",
        "Coordinate calibration",
        calibration_status,
        "calibration depends on a current screenshot",
        "Pick a harmless visible point from the current screenshot and save/verify the coordinate mapping.",
        "Calibration profile or screenshot coordinate note tied to the same iPhone orientation.",
        "Stop if the active screen bounds or target point cannot be explained from the screenshot.",
        "show_p1_trial_from_gui",
    )

    control_status = manual_status
    if manual_status == "pass" and screenshot_status != "pass":
        control_status = "warn"
    add(
        "7",
        "HID click, swipe, and text",
        control_status,
        f"manual={manual_text}; screenshot={screenshot_text}",
        "Run one safe click, one swipe with visible release, and one short ASCII text input while watching the real iPhone.",
        "Manual pass/fail observations for click, swipe, and text; failure rows must include category and artifact path.",
        "Stop on pointer drift, missing click, stuck press, inverted swipe, wrong focus, or text mismatch.",
        "show_p1_trial_from_gui" if normalized_stage == "p1" else "show_field_runbook_from_gui",
    )

    if not callback_rows:
        log_status = "pending"
        log_current = "no receiver/HID log rows attached"
    elif callback_warn:
        log_status = "warn"
        log_current = f"callback/log rows={len(callback_rows)}, warn/fail/error={callback_warn}"
    else:
        log_status = "pass"
        log_current = f"callback/log rows={len(callback_rows)}, warn/fail/error=0"
    add(
        "8",
        "Receiver and HID logs",
        log_status,
        log_current,
        "Attach receiver, capture, HID, USB, or device logs before rerunning a failed path.",
        "Callback/log markdown plus categorized Timeline/Triage rows.",
        "Stop promotion if a warn/fail/error log line cannot be tied to a known failure or benign setup event.",
        "attach_callback_log_from_gui" if log_status != "pass" else "show_issue_triage_from_gui",
    )

    if scenario_summary:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_current = scenario_brief(scenario_summary)
        scenario_method = "write_acceptance_gap_from_gui" if not scenario_summary.get("ok") else "run_acceptance_from_gui"
    elif queue_rows:
        scenario_status = "ready"
        scenario_current = command_queue_brief(command_queue_items or [])
        scenario_method = "run_command_queue_from_gui"
    else:
        scenario_status = "pending"
        scenario_current = "no scenario or GUI command queue result"
        scenario_method = "load_probe_script_from_gui"
    add(
        "9",
        "Repeatable action path",
        scenario_status,
        scenario_current,
        "Load the stage script or save a GUI queue, dry-run it, then run real only after the guard allows it.",
        "Scenario summary or GUI queue JSON with dry-run result and, later, real-run evidence events.",
        "Stop if the action cannot be replayed with the same route, device list, and run_id.",
        scenario_method,
    )

    if not template_rows:
        vision_status = "pending"
        vision_current = "no template asset index"
    elif template_fail:
        vision_status = "fail"
        vision_current = f"template rows={len(template_rows)}, fail={template_fail}"
    else:
        vision_status = "pass"
        vision_current = f"template rows={len(template_rows)}, fail=0"
    add(
        "10",
        "Vision assets",
        vision_status,
        vision_current,
        "Check templates/colors/OCR assets used by this stage before blaming HID or receiver failures.",
        "Template Asset Index plus failure screenshots for every recognition miss.",
        "Stop if the template is tiny, low-texture, stale, or cropped from a different device/orientation.",
        "show_template_asset_manager",
    )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_current = "acceptance not evaluated"
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_current = acceptance_brief(acceptance_report)
    if evidence_exists and fail_events and acceptance_status == "pass":
        acceptance_status = "fail"
    add(
        "11",
        "Stage acceptance",
        acceptance_status,
        f"{acceptance_current}; events={total_events}, fail={fail_events}",
        "Run Acceptance and then Gap; only add the missing evidence, do not change the claim boundary to pass the report.",
        "Acceptance report, Gap report if failed, and clean JSONL event summary.",
        "Stop if Acceptance fails or if JSONL contains unexplained fail events.",
        "run_acceptance_from_gui" if acceptance_status != "fail" else "write_acceptance_gap_from_gui",
    )

    if readiness_report is None:
        readiness_status = "pending"
        readiness_current = "readiness not evaluated"
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_current = readiness_brief(readiness_report)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    if readiness_status == "pass" and not real_ios_verified:
        readiness_status = "warn"
        readiness_current = f"{readiness_current}; real_ios_verified=False"
    if required_missing and readiness_status == "pass":
        readiness_status = "warn"
        readiness_current = f"{readiness_current}; required_missing={', '.join(required_missing[:3])}"
    add(
        "12",
        "Readiness and handoff",
        readiness_status,
        readiness_current,
        "Run Readiness, export Pack/Dashboard/Session/Goal Gate, and hand off only the evidence-backed claim.",
        "Readiness report, Evidence Pack, Stage Dashboard, Session Snapshot, Goal Gate, Kit Gate, and Hardware Bench.",
        "Stop any claim of iOS perfect control unless real iPhone evidence, Acceptance, Readiness, and manual observations all agree.",
        "run_readiness_audit" if readiness_status != "pass" else "write_evidence_pack_from_gui",
    )
    return rows


def field_evidence_wizard_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts: dict[str, int] = {}
    first_focus = "none"
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
        if first_focus == "none" and status in {"fail", "pending", "warn"}:
            first_focus = str(row.get("lane", "") or row.get("step", "") or "unknown")
    return (
        f"Field wizard {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_field_evidence_wizard_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# Field Evidence Wizard {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This wizard is an execution sequence. It does not write evidence by itself and does not prove real iPhone response.",
        "",
        "## Ordered Steps",
        "",
        "| # | Lane | Status | Current | Operator step | GUI action | Evidence to keep | Stop rule |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('lane', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('operator_step', ''))} | {_md_cell(row.get('gui_action', ''))} | "
            f"{_md_cell(row.get('evidence', ''))} | {_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Wizard | - | - | Do not promote |")
    lines.extend([
        "",
        "## 审查规则",
        "",
        "Follow the rows in order. When a row is FAIL, PENDING, or unexplained WARN, stop the field run, attach the smallest useful evidence, and rerun from the first affected row with a new run_id if hardware or route changed.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _field_runner_gui_action(method: str) -> str:
    return {
        "prepare_live_probe_from_gui": "Prepare",
        "edit_route_decision_from_gui": "Edit Route",
        "run_preflight_doctor": "Run Doctor",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_control_evidence_ledger_from_gui": "Open Ctrl Ledger",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "run_acceptance_from_gui": "Run Acceptance",
        "write_acceptance_gap_from_gui": "Export Gap",
        "run_readiness_audit": "Run Readiness",
        "write_evidence_pack_from_gui": "Export Pack",
        "show_gui_goal_gate_from_gui": "Open Goals",
    }.get(method, method)


def _artifact_lookup(rows: list[dict[str, str]] | None) -> dict[str, dict[str, str]]:
    return {
        str(row.get("name", "") or ""): row
        for row in (rows or [])
        if isinstance(row, dict) and row.get("name")
    }


def _artifact_current(
    artifacts: dict[str, dict[str, str]],
    name: str,
    fallback_path: str,
) -> tuple[str, str]:
    row = artifacts.get(name)
    if not row:
        return "pending", f"{name} not indexed; expected={fallback_path}"
    status = str(row.get("status", "") or "missing")
    path = str(row.get("path", "") or fallback_path)
    if status == "present":
        return "pass", f"present: {path}"
    return "pending", f"{status}: {path}"


def field_evidence_runner_rows(
    *,
    run_id: str,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    events: list[dict] | None = None,
    control_rows_data: list[dict[str, str]] | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
    evidence_path: str | Path = "",
    route_decision_path: str | Path = "",
) -> list[dict[str, str]]:
    """Build a field evidence runner that checks artifacts and real-control lanes."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    required_devices = STAGE_DEVICE_REQUIREMENTS.get(normalized_stage, 1)
    safe_run_id = ValidationRecorder(run_id or normalized_stage).safe_run_id
    evidence_text = str(evidence_path or Path("evidence") / f"{safe_run_id}.jsonl")
    route_text = str(route_decision_path or Path("evidence") / f"{safe_run_id}_route_decision.json")
    script_path = standard_probe_script(normalized_stage)
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    artifacts = _artifact_lookup(artifact_rows)
    control_rows = control_rows_data or control_response_bench_rows(events or [], device_ids=selected_devices)
    control_by_label = {str(row.get("label", "") or ""): row for row in control_rows}
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        gate: str,
        status: str,
        current: str,
        command: str,
        artifact: str,
        next_action: str,
        stop_rule: str,
        method: str,
    ) -> None:
        rows.append({
            "step": step,
            "gate": gate,
            "status": status,
            "current": current,
            "command": command,
            "gui_action": _field_runner_gui_action(method),
            "artifact": artifact,
            "next_action": next_action,
            "stop_rule": stop_rule,
            "method": method,
        })

    scope_status = "pass" if run_id.strip() and len(selected_devices) >= required_devices else "fail"
    add(
        "1",
        "Run scope",
        scope_status,
        f"run_id={safe_run_id}; selected={len(selected_devices)}, required={required_devices}; evidence={'present' if evidence_exists else 'missing'}",
        f"Set GUI Evidence run id to {safe_run_id}, select {required_devices} device(s), and keep Record enabled.",
        evidence_text,
        "Prepare the GUI run and record component metadata.",
        "Stop if the physical iPhone, HID, receiver, Hub port, cable, or run_id cannot be pointed to.",
        "prepare_live_probe_from_gui",
    )

    if route_report is None:
        route_status = "pending"
        route_current = "route decision not evaluated"
    else:
        route_status = "pass" if route_report.get("ok") and route_report.get("ready") else "fail"
        route_current = route_decision_brief(route_report)
    add(
        "2",
        "Route decision",
        route_status,
        route_current,
        f".\\.venv\\Scripts\\python -m imouse.route_decision validate {route_text} --require-ready --markdown evidence\\{safe_run_id}_{normalized_stage}_route_decision.md --record-evidence {evidence_text}",
        route_text,
        "Fill real receiver, capture, HID, iPhone, iOS, Hub, cable, operator, and blocker fields.",
        "Stop if placeholders or open blockers remain; if a fail was recorded, use a fresh run_id after fixing it.",
        "edit_route_decision_from_gui",
    )

    if doctor_report is None:
        doctor_status = "pending"
        doctor_current = "doctor not run"
    else:
        overall = str(doctor_report.get("overall", "unknown") or "unknown").lower()
        fail_count = int((doctor_report.get("counts", {}) or {}).get("fail", 0) or 0)
        if overall == "ok":
            doctor_status = "pass"
        elif overall == "warn" and fail_count == 0:
            doctor_status = "warn"
        else:
            doctor_status = "fail"
        doctor_current = doctor_brief(doctor_report)
    add(
        "3",
        "Route-aware doctor",
        doctor_status,
        doctor_current,
        f".\\.venv\\Scripts\\python -m imouse.doctor --route-decision {route_text} --markdown evidence\\{safe_run_id}_{normalized_stage}_doctor.md",
        f"evidence\\{safe_run_id}_{normalized_stage}_doctor.md",
        "Run Doctor for the chosen receiver route and resolve every fail before real HID actions.",
        "Stop on any Doctor fail. Route-specific warn needs an operator note and matching route decision.",
        "run_preflight_doctor",
    )

    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    if screenshot_status == "pass":
        shot_status = "pass"
    elif acceptance_report is None:
        shot_status = "pending"
    else:
        shot_status = "fail"
    shot_artifact_status, shot_artifact = _artifact_current(
        artifacts,
        "Capture Quality Bench",
        f"evidence\\{safe_run_id}_{normalized_stage}_capture_bench.md",
    )
    if shot_status == "pass" and shot_artifact_status == "pending":
        shot_status = "warn"
    add(
        "4",
        "Screenshot quality",
        shot_status,
        f"{screenshot_text}; shot_bench={shot_artifact}",
        "GUI: Start receiver/capture -> Screenshot -> Shot Bench",
        shot_artifact,
        "Save a non-black, current, correctly oriented screenshot artifact before click/swipe/type.",
        "Stop if the frame is black, stale, cropped, from the wrong window, or not tied to this iPhone.",
        "run_capture_quality_bench_from_gui",
    )

    for step, label in (("5", "HID click"), ("6", "HID swipe"), ("7", "Keyboard input")):
        control = control_by_label.get(label, {})
        status = str(control.get("status", "pending") or "pending")
        current = str(control.get("current", "") or f"{label} manual observation missing")
        artifact = str(control.get("artifacts", "") or "-")
        add(
            step,
            label,
            status,
            current,
            f"GUI: P1 Trial -> {label} -> Manual Record pass/fail",
            artifact,
            "Record the visible real-iPhone result with note, category on fail, and artifact/log path when useful.",
            str(control.get("stop_rule", "") or "Stop if API success is not matched by visible real-iPhone behavior."),
            "show_control_evidence_ledger_from_gui",
        )

    if acceptance_report is None:
        acceptance_status = "pending"
        acceptance_current = "acceptance not evaluated"
    else:
        acceptance_status = "pass" if acceptance_report.get("ok") else "fail"
        acceptance_current = acceptance_brief(acceptance_report)
    if acceptance_status == "pass" and fail_events:
        acceptance_status = "fail"
        acceptance_current = f"{acceptance_current}; unexplained_fail_events={fail_events}"
    add(
        "8",
        "Acceptance report",
        acceptance_status,
        f"{acceptance_current}; events={total_events}, fail={fail_events}",
        f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_text} --gate {normalized_stage} --markdown evidence\\{safe_run_id}_{normalized_stage}_acceptance.md",
        f"evidence\\{safe_run_id}_{normalized_stage}_acceptance.md",
        "Evaluate the current evidence JSONL for the selected stage.",
        "Stop if Acceptance fails, or if it passes while JSONL still has unexplained fail rows.",
        "run_acceptance_from_gui",
    )

    if acceptance_report is None:
        gap_status = "pending"
        gap_current = "run Acceptance before exporting a gap report"
    elif acceptance_report.get("ok"):
        gap_status = "pass"
        gap_current = "no acceptance gap required"
    else:
        gap_status = "ready"
        gap_current = acceptance_gap_brief(acceptance_report)
    add(
        "9",
        "Acceptance gap",
        gap_status,
        gap_current,
        f".\\.venv\\Scripts\\python -m imouse.acceptance {evidence_text} --gate {normalized_stage} --gap-markdown evidence\\{safe_run_id}_{normalized_stage}_gap.md",
        f"evidence\\{safe_run_id}_{normalized_stage}_gap.md",
        "Use the gap report to collect only missing evidence; do not weaken acceptance wording.",
        "Stop if the fix would relabel public-source, API, or GUI output as real iPhone proof.",
        "write_acceptance_gap_from_gui",
    )

    if readiness_report is None:
        readiness_status = "pending"
        readiness_current = "readiness not evaluated"
    else:
        readiness_status = "pass" if readiness_report.get("ok") else "fail"
        readiness_current = readiness_brief(readiness_report)
        if readiness_status == "pass" and normalized_stage == "p1" and not real_ios_verified:
            readiness_status = "warn"
            readiness_current = f"{readiness_current}; real_ios_verified=False"
    add(
        "10",
        "Readiness report",
        readiness_status,
        readiness_current,
        f".\\.venv\\Scripts\\python -m imouse.readiness --target {normalized_stage} --evidence {evidence_text} --markdown evidence\\{safe_run_id}_readiness.md",
        f"evidence\\{safe_run_id}_readiness.md",
        "Run Readiness as the final promotion gate for the same run_id.",
        "Stop any control claim unless Readiness PASS names the same stage and same evidence JSONL.",
        "run_readiness_audit",
    )

    required_missing = [
        row.get("name", "")
        for row in (artifact_rows or [])
        if row.get("requirement") == "required" and row.get("status") != "present"
    ]
    recommended_missing = [
        row.get("name", "")
        for row in (artifact_rows or [])
        if row.get("requirement") == "recommended" and row.get("status") != "present"
    ]
    if not artifact_rows:
        pack_status = "pending"
    elif required_missing:
        pack_status = "fail"
    elif recommended_missing:
        pack_status = "warn"
    else:
        pack_status = "pass"
    add(
        "11",
        "Evidence pack",
        pack_status,
        f"required_missing={len(required_missing)}, recommended_missing={len(recommended_missing)}",
        "GUI: Runner Export -> Pack -> Dashboard -> Session",
        f"evidence\\{safe_run_id}_{normalized_stage}_evidence_pack.md",
        "Export the runner, pack, dashboard, and session snapshot for second-person replay.",
        "Stop handoff if required artifacts are missing; markdown presence still is not control proof.",
        "write_evidence_pack_from_gui",
    )

    control_clean = all(
        control_by_label.get(label, {}).get("status") == "pass"
        for label in ("HID click", "HID swipe", "Keyboard input")
    )
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    if control_clean and acceptance_ok and readiness_ok and real_ios_verified and fail_events == 0:
        claim_status = "pass"
    elif control_clean and acceptance_ok and readiness_ok and not real_ios_verified:
        claim_status = "warn"
    else:
        claim_status = "fail"
    add(
        "12",
        "Claim boundary",
        claim_status,
        (
            f"control_clean={control_clean}; acceptance_ok={acceptance_ok}; "
            f"readiness_ok={readiness_ok}; real_ios_verified={real_ios_verified}; fail={fail_events}"
        ),
        f".\\.venv\\Scripts\\python -m imouse.script_runner {script_path} --run-id {safe_run_id}",
        "same-run JSONL, screenshots, manual notes, Acceptance, Readiness",
        "Only discuss the strongest claim supported by the same-run evidence.",
        "Stop iOS perfect-control, broad compatibility, or XP-parity wording unless every prior runner row is clean.",
        "show_gui_goal_gate_from_gui",
    )
    return rows


def field_evidence_runner_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "gate")
    return (
        f"Field runner {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_field_evidence_runner_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# Field Evidence Runner {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This runner is a field execution and evidence checklist. It does not write evidence by itself and does not prove real iPhone response.",
        "",
        "## Runner Gates",
        "",
        "| # | Gate | Status | Current | Command or GUI path | GUI action | Artifact | Next action | Stop rule |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('gate', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"`{_md_cell(row.get('command', ''))}` | {_md_cell(row.get('gui_action', ''))} | "
            f"`{_md_cell(row.get('artifact', ''))}` | {_md_cell(row.get('next_action', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | `Refresh Runner` | - | - | - | Do not promote |")
    commands = [
        str(row.get("command", ""))
        for row in rows
        if str(row.get("command", "")).startswith(".\\.venv\\Scripts\\python")
    ]
    lines.extend([
        "",
        "## Copy-Ready Commands",
        "",
    ])
    if commands:
        lines.append("```powershell")
        lines.extend(commands)
        lines.append("```")
    else:
        lines.append("- No CLI command rows are available yet; refresh Runner after route/evidence paths are set.")
    lines.extend([
        "",
        "## Claim Boundary",
        "",
        "Runner PASS is still scoped to the exact run_id, device ids, iPhone model/iOS, receiver route, HID route, screenshots, manual observations, Acceptance report, and Readiness report. Do not turn API success, exported Markdown, public-source research, or dry-run output into an iOS control claim.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


