def _control_lane_row(rows: list[dict[str, str]], label: str) -> dict[str, str]:
    for row in rows:
        if str(row.get("label", "") or "") == label:
            return row
    return {}


def p1_test_coach_rows(
    *,
    run_id: str,
    stage: str = "p1",
    device_ids: list[str] | None = None,
    action_map_rows: list[dict[str, str]] | None = None,
    local_rows: list[dict[str, str]] | None = None,
    kit_rows: list[dict[str, str]] | None = None,
    ios_sop_rows: list[dict[str, str]] | None = None,
    control_bench_rows_data: list[dict[str, str]] | None = None,
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    scenario_summary: dict | None = None,
    acceptance_report: dict | None = None,
    readiness_report: dict | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
) -> list[dict[str, str]]:
    """Build a hands-on P1 real-device coaching checklist without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    selected_devices = [str(item).strip() for item in (device_ids or []) if str(item).strip()]
    safe_run_id = ValidationRecorder(run_id).safe_run_id
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    route_ready = bool(route_report and route_report.get("ok") and route_report.get("ready"))
    doctor_overall = str((doctor_report or {}).get("overall", "") or "").lower()
    doctor_status = "pending" if doctor_report is None else "pass" if doctor_overall == "ok" else "fail"
    screenshot_status, screenshot_text = _acceptance_check_line(acceptance_report, "screenshot_quality")
    manual_status, manual_text = _acceptance_check_line(acceptance_report, "manual_observation")
    acceptance_ok = bool(acceptance_report and acceptance_report.get("ok"))
    readiness_ok = bool(readiness_report and readiness_report.get("ok"))
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    control_rows = control_bench_rows_data or []

    rows: list[dict[str, str]] = []

    def add(
        step: str,
        focus: str,
        status: str,
        current: str,
        do_this: str,
        gui_method: str,
        command: str,
        pass_criteria: str,
        if_fail: str,
        evidence: str,
        stop_rule: str,
    ) -> None:
        rows.append({
            "step": step,
            "focus": focus,
            "status": status,
            "current": current,
            "do_this": do_this,
            "gui_action": _p1_coach_gui_action(gui_method),
            "method": gui_method,
            "command": command,
            "pass_criteria": pass_criteria,
            "if_fail": if_fail,
            "evidence": evidence,
            "stop_rule": stop_rule,
        })

    scope_status = "pass" if safe_run_id and selected_devices else "fail"
    add(
        "1",
        "Run identity and device scope",
        scope_status,
        f"run_id={safe_run_id or '-'}; devices={', '.join(selected_devices) or '-'}; stage={normalized_stage.upper()}",
        "Set the run id, select exactly one physical iPhone for P1, keep Record enabled, and label the phone, cable, Hub port, HID, and receiver.",
        "prepare_live_probe_from_gui",
        "GUI: Evidence=<run_id>, select dev_1, Record=on, Prepare",
        "Operator can point to the exact iPhone, HID, receiver, Hub port, cable, and JSONL path.",
        "Do not continue; create the physical ledger and select the device first.",
        "`evidence/<run_id>.jsonl`, route decision, operator worksheet, component metadata.",
        "Stop if the device identity or run_id is ambiguous.",
    )

    action_status = _rows_worst_status(action_map_rows or [])
    add(
        "2",
        "Source-derived SOP gates",
        action_status,
        xp_public_source_action_map_brief(action_map_rows or [], stage=normalized_stage) if action_map_rows else "action map not built",
        "Open Action Map and resolve the first source-derived gate before changing route or hardware scope.",
        "show_xp_public_source_action_map_from_gui",
        "GUI: Action Map -> Run Selected on first fail/pending/warn row",
        "Every public XP/package/Apple signal has a mapped R&D decision, SOP gate, stop rule, and GUI owner.",
        "Treat public claims as backlog input only; do not use them as proof.",
        "`evidence/<run_id>_<stage>_xp_source_action_map.md` if exported.",
        "Stop XP parity or compatibility language when the row is source-only.",
    )

    route_status = "pending" if route_report is None else "pass" if route_ready else "fail"
    route_current = route_decision_brief(route_report) if route_report else "route decision not validated"
    add(
        "3",
        "Route Decision",
        route_status,
        route_current,
        "Fill real receiver, HID, iPhone, Hub, cable, network, operator, and open_blockers fields; validate with require-ready.",
        "edit_route_decision_from_gui",
        f".\\.venv\\Scripts\\python -m imouse.route_decision validate evidence\\{safe_run_id}_route_decision.json --require-ready --markdown evidence\\{safe_run_id}_route_decision.md",
        "Route report is PASS/ready and contains no placeholders or open blockers.",
        "Fix Route Decision and start a fresh run_id if a failed route decision was already written to evidence.",
        "Route JSON/report and component metadata.",
        "Stop before receiver/HID tests when route is not ready.",
    )

    local_status = _rows_worst_status(local_rows or [])
    add(
        "4",
        "Local command replay",
        local_status,
        local_verification_brief(local_rows or [], stage=normalized_stage) if local_rows else "local verification not built",
        "Replay the local command list top to bottom in PowerShell after route changes.",
        "show_local_verification_from_gui",
        ".\\.venv\\Scripts\\python -m unittest discover -s tests -v; .\\.venv\\Scripts\\python -m compileall -q imouse tests; .\\.venv\\Scripts\\python -m imouse.doctor --json",
        "Unit tests and compileall pass; dependency/doctor output is understood and copied into handoff notes.",
        "Fix local failures before connecting or moving hardware.",
        "Terminal transcript plus `evidence/<run_id>_<stage>_local_verification.md`.",
        "Local green checks do not prove real iPhone control.",
    )

    add(
        "5",
        "Preflight Doctor",
        doctor_status,
        doctor_brief(doctor_report) if doctor_report else "doctor not run",
        "Run Doctor with the selected route. A missing UxPlay can only be non-blocking when an alternate receiver route is explicitly validated.",
        "run_preflight_doctor",
        f".\\.venv\\Scripts\\python -m imouse.doctor --route-decision evidence\\{safe_run_id}_route_decision.json --json",
        "Doctor has no fail, or the chosen non-UxPlay receiver route has its own provider preflight and stop rule.",
        "Fix the fail first; do not proceed to HID or readiness.",
        "`evidence/<run_id>_doctor.md` or terminal JSON output.",
        "Stop P1 when Doctor overall is fail.",
    )

    setup_status = _worst_status(_rows_worst_status(kit_rows or []), _rows_worst_status(ios_sop_rows or []))
    add(
        "6",
        "Field kit and iOS settings",
        setup_status,
        (
            f"kit={field_kit_gate_brief(kit_rows or [], stage=normalized_stage) if kit_rows else 'not built'}; "
            f"ios={ios_field_sop_brief(ios_sop_rows or [], stage=normalized_stage) if ios_sop_rows else 'not built'}"
        ),
        "Open Kit Gate and iOS SOP. Confirm AssistiveTouch, pointer speed/profile, keyboard behavior, rotation lock, auto-lock, brightness, network, receiver identity, Hub, and cable labels.",
        "show_ios_field_sop_from_gui",
        "GUI: Kit Gate -> iOS SOP -> Run Selected on first non-pass row",
        "The phone settings profile and physical kit are recorded for this exact model/iOS/orientation.",
        "Fix the physical setup or iPhone settings before screenshots and HID tests.",
        "Kit Gate export, iOS SOP export, baseline photo/screenshot, route metadata.",
        "Stop if iPhone settings are unknown or not tied to the run.",
    )

    screenshot_gate = screenshot_status
    if screenshot_gate == "pass" and not evidence_exists:
        screenshot_gate = "warn"
    add(
        "7",
        "Receiver screenshot and Shot Bench",
        screenshot_gate,
        f"{screenshot_text}; evidence_exists={evidence_exists}; events={total_events}; fail_events={fail_events}",
        "Start receiver/capture, connect iPhone projection, take Screenshot, then run Shot Bench before any HID action.",
        "run_capture_quality_bench_from_gui",
        "GUI: Screenshot -> Shot Bench",
        "Current screenshots are nonblank, correctly bound to the selected iPhone, stable in size, and saved as artifacts.",
        "Classify receiver/capture failure: discovery, stream, wrong window, stale frame, crop, black/white frame, or lock screen.",
        "Screenshot quality JSONL rows and `evidence/<run_id>_<stage>_capture_bench.md`.",
        "Stop HID tests until screenshot quality is proven.",
    )

    calibration_status = "ready" if screenshot_status == "pass" else "pending" if screenshot_status == "pending" else "fail"
    add(
        "8",
        "Coordinate calibration",
        calibration_status,
        f"screenshot={screenshot_text}",
        "Use the current screenshot for active area, choose harmless calibration points, and verify visible tap location before business actions.",
        "show_p1_trial_from_gui",
        "GUI: Use Screenshot -> set active/target bounds -> Save calibration -> safe click",
        "Calibration profile matches the current orientation and safe tap error is within the stage tolerance.",
        "Redo screenshot/active area before blaming HID.",
        "`state/calibration.json`, screenshot artifact, manual calibration notes.",
        "Stop when active bounds, orientation, or safe area cannot be explained.",
    )

    for step, label, command, pass_criteria, if_fail in (
        (
            "9",
            "HID click",
            f"curl.exe -X POST http://127.0.0.1:9911/api -H \"Content-Type: application/json\" -d \"{{\\\"fun\\\":\\\"/mouse/click\\\",\\\"data\\\":{{\\\"id\\\":\\\"dev_1\\\",\\\"x\\\":100,\\\"y\\\":100}}}}\"",
            "A safe click visibly affects the real iPhone and a Manual pass is recorded.",
            "Classify as hid, calibration, focus, or capture mismatch; attach artifact before rerun.",
        ),
        (
            "10",
            "HID swipe",
            f"curl.exe -X POST http://127.0.0.1:9911/api -H \"Content-Type: application/json\" -d \"{{\\\"fun\\\":\\\"/mouse/swipe\\\",\\\"data\\\":{{\\\"id\\\":\\\"dev_1\\\",\\\"x1\\\":300,\\\"y1\\\":900,\\\"x2\\\":300,\\\"y2\\\":500,\\\"steps\\\":20}}}}\"",
            "Swipe direction and release are visible on the real iPhone and a Manual pass is recorded.",
            "Stop on inverted direction, stuck press, no release, or coordinate drift; rerun calibration/Control Bench.",
        ),
        (
            "11",
            "Keyboard input",
            f"curl.exe -X POST http://127.0.0.1:9911/api -H \"Content-Type: application/json\" -d \"{{\\\"fun\\\":\\\"/keyboard/type\\\",\\\"data\\\":{{\\\"id\\\":\\\"dev_1\\\",\\\"text\\\":\\\"imouse-smoke\\\"}}}}\"",
            "ASCII text appears in the intended focused field and a Manual pass is recorded.",
            "Check focus, keyboard settings, HID binding, input method state, and stuck modifier keys.",
        ),
    ):
        lane = _control_lane_row(control_rows, label)
        lane_status = str(lane.get("status", "pending") or "pending")
        add(
            step,
            label,
            lane_status,
            lane.get("current", f"{label} not yet observed"),
            f"Use P1 Trial and Ctrl Ledger for {label.lower()} while watching the physical iPhone; then record Manual pass/fail with category and artifact.",
            "show_control_evidence_ledger_from_gui" if lane_status != "pass" else "show_control_response_bench_from_gui",
            command,
            pass_criteria,
            if_fail,
            "Lane-specific Manual observation JSONL row plus optional screenshot/video artifact.",
            "API/HID command success without visible iPhone response is not a pass.",
        )

    if scenario_summary:
        scenario_status = "pass" if scenario_summary.get("ok") else "fail"
        scenario_current = scenario_brief(scenario_summary)
        scenario_method = "run_acceptance_from_gui" if scenario_summary.get("ok") else "write_acceptance_gap_from_gui"
    elif evidence_exists and fail_events:
        scenario_status = "fail"
        scenario_current = f"evidence has fail_events={fail_events}; triage before replay"
        scenario_method = "show_issue_triage_from_gui"
    elif evidence_exists:
        scenario_status = "ready"
        scenario_current = f"events={total_events}; no scenario summary"
        scenario_method = "load_probe_script_from_gui"
    else:
        scenario_status = "pending"
        scenario_current = "no scenario or evidence replay yet"
        scenario_method = "load_probe_script_from_gui"
    add(
        "12",
        "Replayable script and logs",
        scenario_status,
        scenario_current,
        "Only after click/swipe/text manual rows exist, run the P1 script or command queue and attach receiver/HID logs for failures.",
        scenario_method,
        f".\\.venv\\Scripts\\python -m imouse.script_runner scripts\\p1_single_device_control_probe.json --run-id {safe_run_id}",
        "Scenario summary is pass and every manual placeholder was replaced with real observation.",
        "Attach logs, run Triage/Rerun/Recovery, then rerun the smallest affected path.",
        "Scenario summary, callback/log export, Timeline, Triage, Recovery notes.",
        "Stop when the action cannot be replayed with the same route, device id, and run_id.",
    )

    acceptance_status = "pending" if acceptance_report is None else "pass" if acceptance_ok and fail_events == 0 else "fail"
    add(
        "13",
        "Acceptance",
        acceptance_status,
        acceptance_brief(acceptance_report) if acceptance_report else "acceptance not run",
        "Run Acceptance after screenshot/manual/script evidence exists. If it fails, export Gap and add only the missing evidence.",
        "run_acceptance_from_gui" if acceptance_status != "fail" else "write_acceptance_gap_from_gui",
        f".\\.venv\\Scripts\\python -m imouse.acceptance evidence\\{safe_run_id}.jsonl --gate p1 --markdown evidence\\{safe_run_id}_p1_acceptance.md",
        "P1 Acceptance passes and JSONL has no unexplained fail events.",
        "Use Gap; do not lower the claim boundary or mark manual evidence as pass without observation.",
        "Acceptance report and Gap report if failed.",
        "Stop P1 promotion when Acceptance fails.",
    )

    readiness_status = "pending" if readiness_report is None else "pass" if readiness_ok and real_ios_verified and fail_events == 0 else "fail"
    add(
        "14",
        "Readiness and handoff",
        readiness_status,
        (
            f"{readiness_brief(readiness_report) if readiness_report else 'readiness not run'}; "
            f"manual={manual_text}; real_ios_verified={real_ios_verified}; fail_events={fail_events}"
        ),
        "Run Readiness last, then export Pack/Dashboard/Session. Handoff only the exact evidence-backed claim.",
        "run_readiness_audit" if readiness_status != "pass" else "write_evidence_pack_from_gui",
        f".\\.venv\\Scripts\\python -m imouse.readiness --target p1 --evidence evidence\\{safe_run_id}.jsonl",
        "Readiness passes, real_ios_control_verified is true, and the same run has screenshot plus click/swipe/text manual observations.",
        "Return to the first failing coach row; use a fresh run_id if route/hardware changed.",
        "Readiness report, Evidence Pack, Dashboard, Session Snapshot, Goal Gate.",
        "Do not claim iOS perfect control or XP parity until this row passes.",
    )
    return rows


def p1_test_coach_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_focus = _first_attention_value(rows, "focus")
    return (
        f"P1 coach {stage.upper()}: "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_focus={first_focus}"
    )


def write_p1_test_coach_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool(
        (readiness_report or {}).get("claims", {}).get("real_ios_control_verified")
    )
    lines = [
        f"# GUI P1 测试教练 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This coach is a step-by-step operator guide. It does not execute commands, does not write JSONL evidence, and does not prove real iPhone control.",
        "",
        "## Steps",
        "",
        "| # | Focus | Status | Current | Do this | GUI action | Command | Pass criteria | If fail | Evidence to keep | Stop rule |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('focus', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('do_this', ''))} | {_md_cell(row.get('gui_action', ''))} | "
            f"`{_md_cell(row.get('command', ''))}` | {_md_cell(row.get('pass_criteria', ''))} | "
            f"{_md_cell(row.get('if_fail', ''))} | {_md_cell(row.get('evidence', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Coach | - | - | - | - | - | Do not promote |")
    lines.extend([
        "",
        "## Field Rule",
        "",
        "Work from the first FAIL, PENDING, or WARN row. Do not skip to HID actions before receiver screenshots are current. Do not turn API/HID command success into a pass unless the operator saw the real iPhone respond and recorded Manual evidence for the same run_id.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _p1_transcript_gui_action(method: str) -> str:
    labels = {
        "show_receiver_setup_wizard_from_gui": "Open Rx Setup",
        "show_p1_test_coach_from_gui": "Open Coach",
        "show_p1_trial_from_gui": "Open P1 Trial",
        "show_control_response_bench_from_gui": "Open Control Bench",
        "run_capture_quality_bench_from_gui": "Run Shot Bench",
        "attach_callback_log_from_gui": "Attach Log",
        "show_issue_triage_from_gui": "Open Triage",
        "run_acceptance_from_gui": "Run Acceptance",
        "run_readiness_audit": "Run Readiness",
        "write_evidence_pack_from_gui": "Export Pack",
    }
    return labels.get(method, _p1_coach_gui_action(method))


def _p1_transcript_failure_categories(focus: str) -> str:
    text = focus.lower()
    if "route" in text:
        return "route_decision, binding"
    if "doctor" in text or "local" in text:
        return "environment, dependency"
    if "receiver" in text or "screenshot" in text or "shot" in text:
        return "airplay_discovery, airplay_stream, capture"
    if "calibration" in text:
        return "calibration, capture"
    if "click" in text or "swipe" in text or "keyboard" in text or "hid" in text:
        return "hid, calibration, business_state"
    if "script" in text or "logs" in text:
        return "receiver, capture, hid, business_state, performance"
    if "acceptance" in text or "readiness" in text:
        return "claim_boundary, missing_evidence"
    return "uncategorized"


def _p1_transcript_prompt(focus: str) -> str:
    text = focus.lower()
    if "screenshot" in text or "shot" in text or "receiver" in text:
        return "Record what is visible on the physical iPhone and saved frame: app/page, orientation, blank/stale/wrong-window result, artifact path."
    if "click" in text:
        return "Record the exact tap target, whether the physical iPhone changed state, pointer/click behavior, and before/after artifact."
    if "swipe" in text:
        return "Record swipe direction, release, distance, whether content moved on the physical iPhone, and before/after artifact."
    if "keyboard" in text:
        return "Record focused field, expected text, actual text on the physical iPhone, input method state, and artifact path."
    if "calibration" in text:
        return "Record active area, target point, observed tap offset, orientation, and whether calibration was reused or newly saved."
    if "doctor" in text or "route" in text:
        return "Record the command/output summary, remaining blockers, and whether a fresh run_id is required."
    if "acceptance" in text or "readiness" in text:
        return "Record the report result, first blocker, claim boundary, and next smallest rerun."
    return "Record operator observation, actual result, artifact path, and whether the row can advance."


def _p1_transcript_control_checkpoint(value: str) -> bool:
    text = str(value or "").lower()
    return any(token in text for token in ("hid click", "hid swipe", "keyboard input"))


def _p1_transcript_first_valid_category(value: str) -> str:
    for item in str(value or "").split(","):
        cleaned = item.strip()
        if cleaned in FAILURE_CATEGORIES and cleaned:
            return cleaned
    return "uncategorized"


def _p1_transcript_artifact_prefill(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith("evidence/") or text.startswith("screenshots/") or text.startswith("logs/"):
        return text.split()[0].strip("`.,;")
    return ""


def p1_transcript_manual_prefill(row: dict[str, str], *, requested_status: str = "pass") -> dict[str, str]:
    """Convert a transcript row into Manual controls without overclaiming setup rows."""
    status = str(requested_status or "info").strip().lower()
    if status not in {"pass", "fail", "info", "skip"}:
        status = "info"
    checkpoint = str(row.get("checkpoint", "") or "P1 transcript").strip()
    control_checkpoint = _p1_transcript_control_checkpoint(checkpoint)
    status_note = ""
    if status == "pass" and not control_checkpoint:
        status = "info"
        status_note = " pass request kept as info because this checkpoint is not click/swipe/text control."
    category = _p1_transcript_first_valid_category(row.get("failure_categories", "")) if status == "fail" else ""
    prompt = str(row.get("observation_prompt", "") or "").strip()
    expected = str(row.get("expected", "") or "").strip()
    current = str(row.get("current", "") or "").strip()
    note_parts = [
        f"checkpoint={checkpoint}",
        f"current={current or '-'}",
        f"prompt={prompt or '-'}",
        f"expected={expected or '-'}",
    ]
    if status_note:
        note_parts.append(status_note.strip())
    note_parts.append("replace this note with the physical iPhone observation before/after state")
    return {
        "step": f"P1 transcript - {checkpoint}",
        "status": status,
        "category": category,
        "artifact": _p1_transcript_artifact_prefill(row.get("artifact", "")),
        "note": "; ".join(note_parts),
        "control_checkpoint": "true" if control_checkpoint else "false",
        "writes_evidence": "false",
    }


def p1_field_transcript_rows(
    *,
    run_id: str,
    stage: str = "p1",
    coach_rows: list[dict[str, str]] | None = None,
    receiver_setup_rows: list[dict[str, str]] | None = None,
    evidence_exists: bool = False,
    evidence_summary: dict | None = None,
    readiness_report: dict | None = None,
) -> list[dict[str, str]]:
    """Build a fillable P1 field transcript without writing evidence."""
    normalized_stage = stage.lower().strip() or "p1"
    safe_run_id = ValidationRecorder(run_id).safe_run_id
    summary = evidence_summary or {}
    status_counts = summary.get("by_status", {}) if isinstance(summary.get("by_status"), dict) else {}
    total_events = int(summary.get("total", 0) or 0)
    fail_events = int(status_counts.get("fail", 0) or 0)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    rows: list[dict[str, str]] = []

    def add(
        step: str,
        checkpoint: str,
        status: str,
        current: str,
        observation_prompt: str,
        expected: str,
        failure_categories: str,
        artifact: str,
        rerun_rule: str,
        stop_rule: str,
        method: str,
        command: str = "",
    ) -> None:
        rows.append({
            "step": step,
            "checkpoint": checkpoint,
            "status": status,
            "current": current,
            "observation_prompt": observation_prompt,
            "expected": expected,
            "failure_categories": failure_categories,
            "artifact": artifact,
            "operator_fill": "[ ] pass [ ] fail [ ] n/a; observer=; time=; actual=; artifact=; note=",
            "rerun_rule": rerun_rule,
            "stop_rule": stop_rule,
            "command": command,
            "gui_action": _p1_transcript_gui_action(method),
            "method": method,
        })

    add(
        "0",
        "Transcript header",
        "pass" if safe_run_id else "fail",
        (
            f"run_id={safe_run_id}; stage={normalized_stage.upper()}; "
            f"evidence_exists={evidence_exists}; events={total_events}; fail_events={fail_events}"
        ),
        "Fill operator, bench location, iPhone model/iOS, receiver route, HID id, cable, Hub port, and start time before P1 actions.",
        "The transcript header matches the Route Decision JSON and the JSONL evidence path.",
        "missing_evidence, route_decision",
        f"evidence/{safe_run_id}.jsonl and evidence/{safe_run_id}_{normalized_stage}_p1_field_transcript.md",
        "If route, receiver, HID, cable, Hub port, iPhone, or selected device changes after a fail is recorded, use a fresh run_id.",
        "Stop if the transcript cannot be tied to one run_id and one physical bench.",
        "show_p1_test_coach_from_gui",
    )

    setup_rows = receiver_setup_rows or []
    setup_status = _rows_worst_status(setup_rows)
    setup_first = _first_attention_value(setup_rows, "step") if setup_rows else "not built"
    add(
        "RX",
        "Receiver setup split",
        setup_status,
        receiver_setup_wizard_brief(setup_rows, stage=normalized_stage) if setup_rows else "receiver setup wizard not built",
        "Record which receiver lane was selected and why: uxplay, windows_receiver, wired, or capture_card.",
        "The selected lane has a known provider, version/path/start command, capture binding, and stop rule.",
        "airplay_discovery, airplay_stream, capture, binding",
        f"evidence/{safe_run_id}_{normalized_stage}_receiver_setup_wizard.md",
        f"Fix the first receiver setup gap: {setup_first}. Start a fresh run_id if the receiver lane changes after failed evidence.",
        "Stop if capture is manual-only, wrong-window, stale, or not tied to device_id.",
        "show_receiver_setup_wizard_from_gui",
    )

    for coach in coach_rows or []:
        focus = str(coach.get("focus", "") or "unknown")
        step = str(coach.get("step", "") or "")
        status = str(coach.get("status", "pending") or "pending")
        current = str(coach.get("current", "") or "")
        expected = str(coach.get("pass_criteria", "") or "")
        artifact = str(coach.get("evidence", "") or "")
        if_fail = str(coach.get("if_fail", "") or "Classify the failure and rerun the smallest affected path.")
        stop_rule = str(coach.get("stop_rule", "") or "Do not promote while this row is not pass.")
        method = str(coach.get("method", "") or "show_p1_test_coach_from_gui")
        add(
            step,
            focus,
            status,
            current,
            _p1_transcript_prompt(focus),
            expected,
            _p1_transcript_failure_categories(focus),
            artifact,
            if_fail,
            stop_rule,
            method,
            str(coach.get("command", "") or ""),
        )

    claim_status = "pass" if real_ios_verified and fail_events == 0 else "fail" if fail_events else "pending"
    add(
        "SIGN",
        "Operator sign-off",
        claim_status,
        f"real_ios_control_verified={real_ios_verified}; fail_events={fail_events}; events={total_events}",
        "Before handoff, write the exact claim allowed by evidence and list every unresolved blocker.",
        "The sign-off claim matches Readiness and does not exceed the evidence scope.",
        "claim_boundary, missing_evidence",
        f"evidence/{safe_run_id}_readiness.md; evidence/{safe_run_id}_{normalized_stage}_evidence_pack.md",
        "Return to the first non-pass transcript row. Do not merge two route/device attempts into one claim.",
        "Stop perfect-control or XP-parity wording until Readiness proves it for the same run_id.",
        "run_readiness_audit",
    )
    return rows


def p1_field_transcript_brief(rows: list[dict[str, str]], *, stage: str = "p1") -> str:
    counts = _row_status_counts(rows)
    first_checkpoint = _first_attention_value(rows, "checkpoint")
    return (
        f"P1 field transcript {stage.upper()}: rows={len(rows)}, "
        f"pass={counts.get('pass', 0)}, ready={counts.get('ready', 0)}, "
        f"warn={counts.get('warn', 0)}, fail={counts.get('fail', 0)}, "
        f"pending={counts.get('pending', 0)}; first_checkpoint={first_checkpoint}"
    )


def write_p1_field_transcript_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    evidence_path: str | Path = "",
    readiness_report: dict | None = None,
) -> Path:
    out_path = Path(path)
    real_ios_verified = bool((readiness_report or {}).get("claims", {}).get("real_ios_control_verified"))
    lines = [
        f"# P1 Field Transcript {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Evidence: `{evidence_path}`",
        f"- Real iOS control verified: `{real_ios_verified}`",
        "- This transcript is a fillable operator log. It is not JSONL evidence, does not record Manual pass by itself, and does not prove real iPhone control.",
        "",
        "## Operator Fill-In",
        "",
        "| Step | Checkpoint | Status | Current | Observation prompt | Expected | Failure categories | Artifact | Operator fill | Rerun rule | Stop rule | GUI action |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    commands: list[str] = []
    seen_commands: set[str] = set()
    for row in rows:
        command = str(row.get("command", "") or "").strip()
        if command and not command.startswith("GUI:") and command not in seen_commands:
            seen_commands.add(command)
            commands.append(command)
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('checkpoint', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(row.get('observation_prompt', ''))} | {_md_cell(row.get('expected', ''))} | "
            f"{_md_cell(row.get('failure_categories', ''))} | {_md_cell(row.get('artifact', ''))} | "
            f"{_md_cell(row.get('operator_fill', ''))} | {_md_cell(row.get('rerun_rule', ''))} | "
            f"{_md_cell(row.get('stop_rule', ''))} | {_md_cell(row.get('gui_action', ''))} |"
        )
    if not rows:
        lines.append("| - | none | `pending` | no rows built | Refresh Transcript | - | - | - | - | - | Do not promote | - |")
    lines.extend([
        "",
        "## Transcript Rules",
        "",
        "- Record what the physical iPhone did, not what the API returned.",
        "- Every fail row needs one failure category, one artifact/log path, and one smallest-rerun decision.",
        "- Use `P1 Trial` or `Manual` recording to write real Manual observations into JSONL; this Markdown alone is not evidence.",
        "- If route, receiver, HID, cable, Hub port, iPhone, selected device, or iOS settings changed after a failure, use a fresh run_id.",
        "- Do not claim iOS perfect control, broad compatibility, or XP parity unless Readiness proves the same scope.",
        "",
        "## Copy-Ready Commands",
        "",
    ])
    if commands:
        lines.append("```powershell")
        lines.extend(commands)
        lines.append("```")
    else:
        lines.append("- Commands are inherited from Coach/Rx Bootstrap/Rx Setup rows after those boards are built.")
    lines.append("")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


