def capture_quality_bench_rows(
    samples: list[dict],
    *,
    device_id: str = "",
) -> list[dict[str, str]]:
    """Normalize repeated screenshot samples into a reviewable bench table."""
    rows: list[dict[str, str]] = []
    for idx, sample in enumerate(samples, start=1):
        if not isinstance(sample, dict):
            sample = {"error": repr(sample)}
        quality = sample.get("screenshot_quality")
        if not isinstance(quality, dict):
            quality = analyze_screenshot_base64(sample.get("base64"))
        status = "pass" if quality.get("ok") is True else "fail"
        artifact_error = str(sample.get("artifact_error", "") or "")
        if artifact_error:
            status = "fail"
        width = quality.get("width", "")
        height = quality.get("height", "")
        size = f"{width}x{height}" if width and height else "-"
        row_device = str(sample.get("device_id", "") or device_id or "-")
        reason = str(quality.get("reason", "") or sample.get("error", "") or "unknown")
        if artifact_error and reason == "ok":
            reason = "artifact_error"
        if sample.get("error") and reason == "unknown":
            reason = str(sample.get("error"))
        rows.append({
            "sample": str(sample.get("sample") or sample.get("index") or idx),
            "device_id": row_device,
            "status": status,
            "reason": reason,
            "size": size,
            "width": str(width or ""),
            "height": str(height or ""),
            "mean_luma": str(quality.get("mean_luma", "")),
            "stddev_luma": str(quality.get("stddev_luma", "")),
            "bytes": str(quality.get("bytes", sample.get("bytes", "")) or ""),
            "elapsed_ms": str(sample.get("elapsed_ms", "")),
            "artifact": str(sample.get("artifact", "") or "-"),
            "artifact_error": artifact_error,
            "error": str(sample.get("error", "") or quality.get("error", "") or ""),
        })
    return rows


def capture_quality_bench_status(rows: list[dict[str, str]], *, sample_goal: int = 10) -> str:
    if not rows or len(rows) < sample_goal:
        return "fail"
    if any(row.get("status") == "fail" for row in rows):
        return "fail"
    sizes = {row.get("size", "") for row in rows if row.get("size") and row.get("size") != "-"}
    if len(sizes) > 1:
        return "warn"
    return "pass"


def capture_quality_bench_brief(
    rows: list[dict[str, str]],
    *,
    stage: str = "p1",
    sample_goal: int = 10,
) -> str:
    counts = _row_status_counts(rows)
    status = capture_quality_bench_status(rows, sample_goal=sample_goal)
    sizes = sorted({row.get("size", "") for row in rows if row.get("size") and row.get("size") != "-"})
    first_failure = "none"
    for row in rows:
        if row.get("status") == "fail":
            first_failure = f"{row.get('sample')}: {row.get('reason')}"
            break
    size_text = ", ".join(sizes[:3]) if sizes else "none"
    return (
        f"Capture bench {stage.upper()}: status={status}, samples={len(rows)}/{sample_goal}, "
        f"pass={counts.get('pass', 0)}, fail={counts.get('fail', 0)}, "
        f"size_variants={len(sizes)} ({size_text}); first_failure={first_failure}"
    )


def write_capture_quality_bench_markdown(
    rows: list[dict[str, str]],
    path: str | Path,
    *,
    run_id: str,
    stage: str = "p1",
    device_id: str = "",
    sample_goal: int = 10,
    evidence_path: str | Path = "",
) -> Path:
    out_path = Path(path)
    bench_status = capture_quality_bench_status(rows, sample_goal=sample_goal)
    lines = [
        f"# GUI 捕获质量基准 {stage.upper()}",
        "",
        f"- Run ID: `{run_id}`",
        f"- Device: `{device_id or '-'}`",
        f"- Evidence: `{evidence_path}`",
        f"- Bench status: `{bench_status}`",
        "- Real iOS control verified: `False`",
        "- This bench records repeated screenshot quality. It does not prove click, swipe, text input, or full iOS control.",
        "",
        "## Samples",
        "",
        "| # | Device | Status | Reason | Size | Mean luma | Stddev luma | Bytes | Elapsed ms | Artifact | Error |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            f"| {_md_cell(row.get('sample', ''))} | {_md_cell(row.get('device_id', ''))} | "
            f"`{_md_cell(row.get('status', ''))}` | {_md_cell(row.get('reason', ''))} | "
            f"{_md_cell(row.get('size', ''))} | {_md_cell(row.get('mean_luma', ''))} | "
            f"{_md_cell(row.get('stddev_luma', ''))} | {_md_cell(row.get('bytes', ''))} | "
            f"{_md_cell(row.get('elapsed_ms', ''))} | `{_md_cell(row.get('artifact', ''))}` | "
            f"{_md_cell(row.get('error', '') or row.get('artifact_error', ''))} |"
        )
    if not rows:
        lines.append("| - | - | `fail` | no samples | - | - | - | - | - | - | - |")
    lines.extend([
        "",
        "## Stop Rule",
        "",
        "Stop the field run if any sample fails, if the sample count is below the target, or if screenshot dimensions drift. For XP-level receiver/capture confidence, repeat this as a 100-screenshot stability run before expanding devices.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def _row_status_counts(rows: list[dict[str, str]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("status", "pending") or "pending")
        counts[status] = counts.get(status, 0) + 1
    return counts


def _rows_worst_status(rows: list[dict[str, str]]) -> str:
    if not rows:
        return "pending"
    return _worst_status(*(str(row.get("status", "pending") or "pending") for row in rows))


def _first_attention_value(
    rows: list[dict[str, str]],
    key: str,
    *,
    statuses: set[str] | None = None,
) -> str:
    attention = statuses or {"fail", "pending", "warn"}
    for row in rows:
        if str(row.get("status", "pending") or "pending") in attention:
            return str(row.get(key, "") or "unknown")
    return "none"


