def _stage_dashboard_blockers(
    *,
    stage: str,
    selected_devices: list[str],
    readiness_report: dict | None,
    acceptance_report: dict | None,
    route_report: dict | None,
    doctor_report: dict | None,
    evidence_exists: bool,
) -> list[str]:
    blockers: list[str] = []
    readiness_blockers = _readiness_blocker_names(readiness_report)
    if stage == "p0":
        blockers.extend(name for name in readiness_blockers if name in {"docs", "scripts", "modules"})
        if readiness_report is None:
            blockers.append("readiness_pending")
        return _unique_text(blockers)

    required_devices = STAGE_DEVICE_REQUIREMENTS.get(stage, 1)
    if len(selected_devices) < required_devices:
        blockers.append("devices")
    if route_report is None:
        blockers.append("route_pending")
    elif not route_report.get("ok"):
        blockers.append("route_decision")
    if doctor_report is None:
        blockers.append("doctor_pending")
    elif str(doctor_report.get("overall", "")).lower() == "fail":
        blockers.append("doctor")
    if not evidence_exists:
        blockers.append("field_evidence")
    if acceptance_report is None:
        blockers.append(f"acceptance:{stage}_pending")
    elif not acceptance_report.get("ok"):
        failed = [
            str(item.get("name", ""))
            for item in acceptance_report.get("checks", [])
            if isinstance(item, dict) and item.get("status") != "pass" and item.get("name")
        ]
        blockers.extend(failed[:3] or [f"acceptance:{stage}"])
    blockers.extend(
        name
        for name in readiness_blockers
        if name in {"docs", "scripts", "modules", "doctor", "field_evidence", f"acceptance:{stage}"}
    )
    return _unique_text(blockers)


def _readiness_blocker_names(report: dict | None) -> list[str]:
    if not isinstance(report, dict):
        return []
    names = []
    for item in report.get("blockers", []):
        if isinstance(item, dict) and item.get("name"):
            names.append(str(item["name"]))
    return names


def _unique_text(items: list[str]) -> list[str]:
    seen = set()
    out = []
    for item in items:
        cleaned = str(item).strip()
        if cleaned and cleaned not in seen:
            seen.add(cleaned)
            out.append(cleaned)
    return out


def _stage_dashboard_next_action(stage: str, blockers: list[str]) -> str:
    if not blockers:
        if stage == "p0":
            return "P0 assets are ready; prepare P1 route, doctor, and evidence."
        return "Review artifacts and promote only after manual real-iPhone evidence is accepted."
    for blocker in blockers:
        if blocker in {"docs", "scripts", "modules", "readiness_pending"}:
            return "Run Readiness and fix missing P0 assets before field testing."
        if blocker == "devices":
            return f"Register/select at least {STAGE_DEVICE_REQUIREMENTS.get(stage, 1)} device(s)."
        if blocker in {"route_pending", "route_decision"}:
            return "Use Prepare/Route Init, fill real route values, then Validate."
        if blocker in {"doctor_pending", "doctor"}:
            return "Run Doctor and fix fail checks before real hardware actions."
        if blocker == "field_evidence":
            return "Record JSONL evidence with Metadata, Screenshot, Scenario, and Manual observations."
        if blocker.startswith("acceptance") or blocker in {
            "evidence_exists",
            "no_fail_events",
            "device_traceability",
            "component_traceability",
            "manual_observation",
            "screenshot_quality",
            "metrics",
        }:
            return "Run Acceptance and Gap, then add the listed evidence."
    return "Resolve blockers, refresh Dashboard, then rerun Acceptance and Readiness."


def manual_observation_details(
    *,
    note: str,
    selected_device: str,
    click_x: int,
    click_y: int,
    category: str = "",
) -> dict:
    details = {
        "manual": True,
        "note": note,
        "selected_device": selected_device,
        "click": {"x": click_x, "y": click_y},
    }
    cleaned_category = category.strip()
    if cleaned_category:
        details["category"] = cleaned_category
    return details


def _split_recovery_categories(value: str) -> list[str]:
    categories = []
    for item in str(value or "").split(","):
        cleaned = item.strip()
        if cleaned:
            categories.append(cleaned)
    return _unique_text(categories)


def recovery_observation_details(
    *,
    row: dict[str, str],
    status: str,
    note: str,
    selected_device: str,
    click_x: int,
    click_y: int,
) -> dict:
    categories = _split_recovery_categories(str(row.get("categories", "")))
    details = {
        "recovery_drill": True,
        "operator_result": status.strip().lower() or "info",
        "recovery_key": str(row.get("key", "") or "").strip(),
        "lane_status": str(row.get("status", "") or "").strip(),
        "category_failures": str(row.get("category_count", "") or "").strip(),
        "trigger": str(row.get("trigger", "") or "").strip(),
        "current": str(row.get("current", "") or "").strip(),
        "recovery_step": str(row.get("recovery", "") or "").strip(),
        "verify_step": str(row.get("verify", "") or "").strip(),
        "evidence_to_keep": str(row.get("evidence", "") or "").strip(),
        "stop_rule": str(row.get("stop_rule", "") or "").strip(),
        "gui_action": str(row.get("gui_action", "") or "").strip(),
        "method": str(row.get("method", "") or "").strip(),
        "operator_note": note.strip(),
        "selected_device": selected_device.strip(),
        "click": {"x": click_x, "y": click_y},
    }
    if categories:
        details["category"] = categories[0]
        details["categories"] = categories
    return details


def component_metadata_details(
    *,
    device_id: str,
    receiver_provider: str,
    capture_method: str,
    hid_provider: str,
    hid_id: str,
    serial_port: str,
    iphone_id: str,
    ios_version: str,
    receiver_name: str = "",
    receiver_version: str = "",
) -> dict:
    details = {
        "manual": True,
        "device_id": device_id.strip(),
        "receiver_provider": receiver_provider.strip(),
        "capture_method": capture_method.strip(),
        "hid_provider": hid_provider.strip(),
        "hid_id": hid_id.strip(),
        "serial_port": serial_port.strip(),
        "iphone_id": iphone_id.strip(),
        "ios_version": ios_version.strip(),
        "receiver_name": receiver_name.strip(),
        "receiver_version": receiver_version.strip(),
    }
    missing = [
        key
        for key in ("device_id", "receiver_provider", "capture_method", "hid_provider", "iphone_id", "ios_version")
        if not details[key]
    ]
    if not details["hid_id"] and not details["serial_port"]:
        missing.append("hid_id_or_serial_port")
    if missing:
        raise ValueError(", ".join(missing))
    return details


def command_queue_rows(items: list[dict]) -> list[dict[str, str]]:
    """Return display rows for the GUI command queue."""
    rows = []
    for index, item in enumerate(items, start=1):
        devices = _command_queue_devices(item)
        rows.append({
            "index": str(index),
            "action": str(item.get("action", "") or ""),
            "devices": ", ".join(devices) if devices else "-",
            "payload": _command_queue_payload_brief(item),
        })
    return rows


def command_queue_brief(items: list[dict]) -> str:
    rows = command_queue_rows(items)
    counts: dict[str, int] = {}
    for row in rows:
        action = row["action"] or "unknown"
        counts[action] = counts.get(action, 0) + 1
    count_text = ", ".join(f"{key}={value}" for key, value in sorted(counts.items())) or "empty"
    return f"Command queue: {len(rows)} item(s); {count_text}"


def build_command_queue_scenario(
    items: list[dict],
    *,
    repeat: int = 1,
    wait_between: float = 0.0,
    name: str = "GUI command queue",
    stop_on_error: bool = True,
) -> dict:
    """Convert GUI queue items to a ScriptRunner scenario."""
    if not items:
        raise ValueError("Command queue is empty")
    repeat_count = int(repeat)
    if repeat_count < 1:
        raise ValueError("repeat must be >= 1")
    wait_seconds = float(wait_between)
    if wait_seconds < 0:
        raise ValueError("wait_between must be >= 0")

    steps: list[dict] = []
    for item in items:
        steps.extend(_command_queue_steps(item))
    if not steps:
        raise ValueError("Command queue produced no runnable steps")

    scenario_steps: list[dict]
    if repeat_count > 1:
        scenario_steps = [{
            "action": "repeat",
            "name": f"{name} repeat",
            "count": repeat_count,
            "wait_between": wait_seconds,
            "stop_on_error": stop_on_error,
            "steps": steps,
        }]
    else:
        scenario_steps = steps
    return {
        "name": name,
        "stop_on_error": stop_on_error,
        "steps": scenario_steps,
    }


def write_command_queue_scenario(
    items: list[dict],
    path: str | Path,
    *,
    repeat: int = 1,
    wait_between: float = 0.0,
    name: str = "GUI command queue",
    stop_on_error: bool = True,
) -> Path:
    scenario = build_command_queue_scenario(
        items,
        repeat=repeat,
        wait_between=wait_between,
        name=name,
        stop_on_error=stop_on_error,
    )
    out_path = Path(path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(scenario, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return out_path


def template_asset_rows(base_dir: str | Path = "templates") -> list[dict[str, str]]:
    """Scan local template images and return GUI-safe quality rows."""
    root = Path(base_dir)
    if not root.exists():
        return []
    rows = []
    for path in sorted(item for item in root.rglob("*") if item.is_file()):
        if path.suffix.lower() not in TEMPLATE_ASSET_SUFFIXES:
            continue
        quality = analyze_template_path(path)
        width = quality.get("width", "")
        height = quality.get("height", "")
        rows.append({
            "name": path.name,
            "path": str(path),
            "size": f"{width}x{height}" if width and height else "-",
            "status": "ok" if quality.get("ok") else "fail",
            "reason": str(quality.get("reason", "unknown")),
            "stddev_luma": str(quality.get("stddev_luma", "")),
            "modified": _path_mtime_text(path),
        })
    return rows


def template_asset_brief(rows: list[dict[str, str]]) -> str:
    total = len(rows)
    ok_count = sum(1 for row in rows if row.get("status") == "ok")
    fail_count = sum(1 for row in rows if row.get("status") == "fail")
    return f"Template assets: total={total}, ok={ok_count}, fail={fail_count}"


def write_template_asset_index_markdown(rows: list[dict[str, str]], path: str | Path) -> Path:
    out_path = Path(path)
    lines = [
        "# GUI Template Asset Index",
        "",
        "- Real iOS control verified: `False`",
        "- This index only checks local template files and does not prove template recognition on a live iPhone.",
        "",
        "| Name | Status | Reason | Size | Stddev | Path |",
        "|---|---|---|---|---|---|",
    ]
    if rows:
        for row in rows:
            lines.append(
                f"| {row.get('name', '')} | {row.get('status', '')} | {row.get('reason', '')} | "
                f"{row.get('size', '')} | {row.get('stddev_luma', '')} | `{row.get('path', '')}` |"
            )
    else:
        lines.append("| None | missing | no template assets found | - | - | - |")
    lines.extend([
        "",
        "Use low-texture or too-small failures as a prompt to crop a larger, more distinctive UI region.",
        "",
    ])
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    return out_path


def build_gui_session_snapshot(
    *,
    run_id: str,
    stage: str,
    server_url: str,
    device_ids: list[str],
    evidence_path: str | Path,
    evidence_summary: dict | None = None,
    route_decision_path: str | Path = "",
    route_report: dict | None = None,
    doctor_report: dict | None = None,
    readiness_report: dict | None = None,
    live_probe_rows_data: list[dict[str, str]] | None = None,
    sop_rows_data: list[dict[str, str]] | None = None,
    command_queue_rows_data: list[dict[str, str]] | None = None,
    template_asset_rows_data: list[dict[str, str]] | None = None,
    artifact_rows: list[dict[str, str]] | None = None,
) -> dict:
    """Build a GUI handoff snapshot without writing evidence."""
    return {
        "run_id": run_id,
        "stage": stage,
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "server_url": server_url,
        "device_ids": [str(item).strip() for item in device_ids if str(item).strip()],
        "evidence_path": str(evidence_path),
        "evidence_summary": evidence_summary or {},
        "route_decision_path": str(route_decision_path or ""),
        "route_brief": route_decision_brief(route_report) if route_report else "Route decision not loaded",
        "doctor_brief": doctor_brief(doctor_report) if doctor_report else "Doctor not loaded",
        "readiness_brief": readiness_brief(readiness_report) if readiness_report else "Readiness not loaded",
        "live_probe_rows": live_probe_rows_data or [],
        "sop_rows": sop_rows_data or [],
        "command_queue_rows": command_queue_rows_data or [],
        "template_asset_rows": template_asset_rows_data or [],
        "artifact_rows": artifact_rows or [],
        "claims": {
            "snapshot_writes_evidence": False,
            "snapshot_verifies_real_ios_control": False,
        },
    }


def gui_session_snapshot_brief(snapshot: dict) -> str:
    stage = str(snapshot.get("stage", "p1") or "p1").upper()
    devices = len(snapshot.get("device_ids", []) or [])
    queue_count = len(snapshot.get("command_queue_rows", []) or [])
    live_fail = sum(1 for row in snapshot.get("live_probe_rows", []) or [] if row.get("status") == "fail")
    sop_blockers = sum(1 for row in snapshot.get("sop_rows", []) or [] if row.get("status") in {"fail", "pending"})
    template_fail = sum(1 for row in snapshot.get("template_asset_rows", []) or [] if row.get("status") == "fail")
    return (
        f"GUI session {stage}: devices={devices}, queue={queue_count}, "
        f"live_fail={live_fail}, sop_blockers={sop_blockers}, template_fail={template_fail}"
    )


def write_gui_session_snapshot_markdown(snapshot: dict, path: str | Path) -> Path:
    out_path = Path(path)
    evidence_summary = snapshot.get("evidence_summary", {}) if isinstance(snapshot.get("evidence_summary"), dict) else {}
    status_counts = evidence_summary.get("by_status", {}) if isinstance(evidence_summary.get("by_status"), dict) else {}
    lines = [
        f"# GUI 会话快照 {str(snapshot.get('stage', 'p1')).upper()}",
        "",
        f"- Run ID: `{snapshot.get('run_id', '')}`",
        f"- Generated at: `{snapshot.get('generated_at', '')}`",
        f"- Server: `{snapshot.get('server_url', '')}`",
        f"- Evidence: `{snapshot.get('evidence_path', '')}`",
        f"- Route decision: `{snapshot.get('route_decision_path', '')}`",
        f"- Devices: `{', '.join(snapshot.get('device_ids', []) or []) or '-'}`",
        f"- Snapshot writes evidence: `{snapshot.get('claims', {}).get('snapshot_writes_evidence', False)}`",
        f"- Snapshot verifies real iOS control: `{snapshot.get('claims', {}).get('snapshot_verifies_real_ios_control', False)}`",
        "",
        "## Status",
        "",
        f"- Evidence events: `{evidence_summary.get('total', 0)}`",
        f"- Evidence pass/fail/info/skip: `{status_counts.get('pass', 0)}/{status_counts.get('fail', 0)}/{status_counts.get('info', 0)}/{status_counts.get('skip', 0)}`",
        f"- Route: {snapshot.get('route_brief', '')}",
        f"- Doctor: {snapshot.get('doctor_brief', '')}",
        f"- Readiness: {snapshot.get('readiness_brief', '')}",
        "",
        "## Live Probe",
        "",
        "| Check | Status | Message | Action |",
        "|---|---|---|---|",
    ]
    for row in snapshot.get("live_probe_rows", []) or []:
        lines.append(
            f"| {_md_cell(row.get('label', row.get('key', '')))} | {_md_cell(row.get('status', ''))} | "
            f"{_md_cell(row.get('message', ''))} | {_md_cell(row.get('action', ''))} |"
        )
    if not snapshot.get("live_probe_rows"):
        lines.append("| None | missing | Refresh Live Probe first | Refresh Live Probe |")

    lines.extend([
        "",
        "## SOP Board",
        "",
        "| # | Workstream | Status | Current | Primary command | Next action |",
        "|---|---|---|---|---|---|",
    ])
    for row in snapshot.get("sop_rows", []) or []:
        command = stage_sop_next_command(row)
        lines.append(
            f"| {_md_cell(row.get('step', ''))} | {_md_cell(row.get('workstream', ''))} | "
            f"{_md_cell(row.get('status', ''))} | {_md_cell(row.get('current', ''))} | "
            f"{_md_cell(command.get('label', ''))} | "
            f"{_md_cell(row.get('next_action', ''))} |"
        )
    if not snapshot.get("sop_rows"):
        lines.append("| - | pending | missing | Open SOP Board first | Refresh SOP | Refresh SOP Board |")

    lines.extend(["", "## Command Queue", "", "| # | Action | Devices | Payload |", "|---|---|---|---|"])
    for row in snapshot.get("command_queue_rows", []) or []:
        lines.append(
            f"| {_md_cell(row.get('index', ''))} | {_md_cell(row.get('action', ''))} | "
            f"{_md_cell(row.get('devices', ''))} | {_md_cell(row.get('payload', ''))} |"
        )
    if not snapshot.get("command_queue_rows"):
        lines.append("| - | empty | - | Build a queue or run a JSON scenario |")

    lines.extend(["", "## Template Assets", "", "| Name | Status | Reason | Size | Path |", "|---|---|---|---|---|"])
    for row in snapshot.get("template_asset_rows", []) or []:
        lines.append(
            f"| {_md_cell(row.get('name', ''))} | {_md_cell(row.get('status', ''))} | "
            f"{_md_cell(row.get('reason', ''))} | {_md_cell(row.get('size', ''))} | `{row.get('path', '')}` |"
        )
