    def attach_callback_log_from_gui(self) -> None:
        path_text = filedialog.askopenfilename(
            title="Attach receiver/HID log",
            filetypes=[
                ("Log/Text files", "*.log *.txt *.jsonl *.csv"),
                ("All files", "*.*"),
            ],
        )
        if not path_text:
            return
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        device_ids = self._selected_device_ids()
        device_id = device_ids[0] if device_ids else self.device_id.get().strip()
        source_path = Path(path_text)
        source_name = f"log:{source_path.name}"

        def worker() -> dict:
            text = source_path.read_text(encoding="utf-8", errors="replace")
            events = callback_log_events_from_text(
                text,
                device_id=device_id,
                source=source_name,
                max_lines=200,
            )
            pushed = 0
            push_error = ""
            for event in events:
                try:
                    self.client.push_callback(
                        event.get("event", "receiver_log"),
                        event.get("data", {}),
                        device_id=event.get("device_id", ""),
                        source=event.get("source", source_name),
                        severity=event.get("severity", "info"),
                    )
                    pushed += 1
                except XpApiError as exc:
                    push_error = str(exc)
                    break
            out_path = write_callback_log_markdown(
                events,
                recorder.path.with_name(f"{recorder.safe_run_id}_callback_log.md"),
                run_id=recorder.safe_run_id,
                source_path=source_path,
                server_url=self.client.base_url,
                pushed=pushed,
                push_error=push_error,
            )
            evidence_status = callback_log_evidence_status(events)
            evidence_details = callback_log_evidence_details(
                events,
                source_path=source_path,
                pushed=pushed,
                push_error=push_error,
            )
            return {
                "events": len(events),
                "pushed": pushed,
                "push_error": push_error,
                "artifact": str(out_path),
                "brief": callback_log_brief(events, pushed=pushed),
                "evidence_status": evidence_status,
                "evidence_details": evidence_details,
                "source_path": str(source_path),
            }

        def on_success(result: dict) -> None:
            line = str(result.get("brief", "") or "Callback log attach: events=0, pushed=0")
            artifact = result.get("artifact", "")
            push_error = result.get("push_error", "")
            source_artifact = str(result.get("source_path", "") or "")
            evidence_artifacts = [item for item in (source_artifact, str(artifact or "")) if item]
            evidence_device_ids = device_ids if device_ids else ([device_id] if device_id else None)
            self._record_evidence(
                "Attach Log triage",
                str(result.get("evidence_status", "info") or "info"),
                result.get("evidence_details", {}),
                artifacts=evidence_artifacts,
                device_ids=evidence_device_ids,
            )
            if push_error:
                line = f"{line}; push_error={push_error}"
                self._log(f"{line}; artifact={artifact}")
                messagebox.showwarning(
                    "iMouse",
                    f"{line}\n{artifact}\n\n"
                    "The log report was written, but not all callback events reached the API. "
                    "If Record is enabled, log triage was recorded as JSONL evidence.",
                )
            else:
                self._log(f"{line}; artifact={artifact}")
                messagebox.showinfo(
                    "iMouse",
                    f"{line}\n{artifact}\n\n"
                    "Attached logs can support triage evidence when Record is enabled, "
                    "but they are not real iOS control proof.",
                )
            self.refresh_live_probe_status()

        self._apply_server_url()
        self._run_api(
            "Attach callback log",
            worker,
            on_success,
            record_success=False,
            record_error=False,
        )

