    def _rerun_playbook_context(self) -> tuple[list[dict[str, str]], ValidationRecorder, dict | None]:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        recorder = ValidationRecorder(run_id)
        events = recorder.load() if recorder.path.exists() else []
        issue_rows_data = issue_triage_rows(events)
        summary = recorder.summary() if recorder.path.exists() else {"total": 0, "by_status": {}, "by_failure_category": {}, "metrics": {}}
        route_report = self._probe_report("route") or self._load_current_route_report()
        doctor_report = self._probe_report("doctor")
        acceptance_report = self._probe_report("acceptance")
        readiness_report = self._probe_report("readiness") or self._probe_report("readiness_preview")
        rows = rerun_playbook_rows(
            issue_rows_data,
            stage=stage,
            route_report=route_report,
            doctor_report=doctor_report,
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=recorder.path.exists(),
            evidence_summary=summary,
        )
        return rows, recorder, readiness_report

