    def _control_evidence_ledger_context(self) -> tuple[list[dict[str, str]], dict | None, ValidationRecorder]:
        run_id = self._ensure_evidence_run_id()
        recorder = ValidationRecorder(run_id)
        stage = self.field_stage.get().strip().lower() or "p1"
        evidence_exists = recorder.path.exists()
        events = recorder.load() if evidence_exists else []
        evidence_summary = recorder.summary() if evidence_exists else {}
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(recorder.path, gate=stage)
                self._store_probe_report("acceptance", acceptance_report)
            except Exception as exc:
                acceptance_report = {
                    "gate": stage,
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=recorder.path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None
        rows = control_evidence_ledger_rows(
            events,
            run_id=run_id,
            stage=stage,
            device_ids=self._selected_device_ids(),
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            control_rows_data=control_response_bench_rows(
                events,
                device_ids=self._selected_device_ids(),
                min_manual_pass=1,
            ),
            evidence_path=recorder.path,
        )
        return rows, readiness_report, recorder

    def show_control_evidence_ledger_from_gui(self) -> None:
        stage = self.field_stage.get().strip().lower() or "p1"
        try:
            rows, _readiness_report, recorder = self._control_evidence_ledger_context()
        except Exception as exc:
            messagebox.showerror("iMouse", f"Control evidence ledger 失败: {exc}")
            return

        dialog = tk.Toplevel(self)
        dialog.title(f"Control Evidence Ledger {stage.upper()} {recorder.safe_run_id}")
        dialog.geometry("1580x600")
        dialog.minsize(1140, 420)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=control_evidence_ledger_brief(rows, stage=stage))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("step", "lane", "status", "current", "minimum", "record", "action", "next", "stop")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=12)
        for column, label, width in (
            ("step", "#", 42),
            ("lane", "Lane", 190),
            ("status", "Status", 80),
            ("current", "Current", 330),
            ("minimum", "Minimum evidence", 390),
            ("record", "Record path", 300),
            ("action", "GUI action", 150),
            ("next", "Next action", 320),
            ("stop", "Stop rule", 360),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("step", ""),
                        row.get("lane", ""),
                        row.get("status", ""),
                        row.get("current", ""),
                        row.get("minimum_evidence", ""),
                        row.get("record_path", ""),
                        row.get("gui_action", ""),
                        row.get("next_action", ""),
                        row.get("stop_rule", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(control_evidence_ledger_brief(next_rows, stage=stage))

        def selected_row() -> dict[str, str] | None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one control ledger row first.")
                return None
            return row_by_item.get(selection[0], {})

        def refresh() -> None:
            try:
                refreshed, _readiness, _recorder = self._control_evidence_ledger_context()
            except Exception as exc:
                status_var.set(f"Control ledger refresh 失败: {exc}")
                self._log(f"Control evidence ledger refresh 失败: {exc}")
                return
            render(refreshed)
            self._log(control_evidence_ledger_brief(refreshed, stage=stage))

        def run_selected() -> None:
            row = selected_row()
            if not row:
                return
            method_name = str(row.get("method", "") or "")
            method = getattr(self, method_name, None)
            if not callable(method):
                messagebox.showerror("iMouse", f"Ledger action is not available: {method_name}")
                return
            self._log(f"Control ledger action {row.get('lane', '')}: {row.get('gui_action', '')}")
            method()

        def record_selected(status: str) -> None:
            row = selected_row()
            if not row:
                return
            lane = str(row.get("lane", "") or "")
            if lane not in {"HID click", "HID swipe", "Keyboard input"}:
                messagebox.showwarning("iMouse", "Only click, swipe, and keyboard rows can record Manual control evidence.")
                return
            self.manual_step.set(f"Control ledger - {lane}")
            self.manual_status.set(status)
            self.manual_category.set(_p1_trial_failure_category(lane) if status == "fail" else "")
            self.manual_note.set(
                f"{lane}: replace with physical iPhone before/after observation; "
                f"minimum={row.get('minimum_evidence', '')}; artifact=<path>"
            )
            self.record_manual_observation()
            refresh()

        ttk.Button(footer, text="Run Selected", command=run_selected).pack(side="left")
        ttk.Button(footer, text="Record Pass", command=lambda: record_selected("pass")).pack(side="left", padx=4)
        ttk.Button(footer, text="Record Fail", command=lambda: record_selected("fail")).pack(side="left", padx=4)
        ttk.Button(footer, text="刷新", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="导出", command=self.write_control_evidence_ledger_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="P1 Trial", command=self.show_p1_trial_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Control Bench", command=self.show_control_response_bench_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Acceptance", command=self.run_acceptance_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Readiness", command=self.run_readiness_audit).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Ledger keeps click, swipe, and text evidence separate; generic Manual rows stay context only.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

