    def _operator_home_context(self) -> tuple[list[dict[str, str]], dict | None]:
        run_id = self._ensure_evidence_run_id()
        stage = self.field_stage.get().strip().lower() or "p1"
        recorder = ValidationRecorder(run_id)
        evidence_exists = recorder.path.exists()
        evidence_summary = recorder.summary() if evidence_exists else {}
        route_path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))

        route_report = self._probe_report("route") or self._load_current_route_report()
        acceptance_report = self._probe_report("acceptance")
        if acceptance_report is None and evidence_exists:
            try:
                acceptance_report = evaluate_acceptance(recorder.path, gate=stage)
                self._store_probe_report("acceptance", acceptance_report)
            except Exception as exc:
                acceptance_report = {
                    "gate": stage,
                    "ok": False,
                    "checks": [{
                        "name": "acceptance_error",
                        "status": "fail",
                        "message": str(exc),
                    }],
                }
        readiness_report = self._probe_report("readiness_preview") or self._probe_report("readiness")
        if readiness_report is None:
            try:
                readiness_report = evaluate_readiness(
                    evidence_jsonl=recorder.path if evidence_exists else None,
                    target=stage,
                    run_doctor_check=False,
                    doctor_report=self._probe_report("doctor"),
                )
                self._store_probe_report("readiness_preview", readiness_report)
            except Exception:
                readiness_report = None

        def context_rows(name: str) -> list[dict[str, str]]:
            method = getattr(self, name)
            try:
                rows, _readiness = method()
            except Exception:
                return []
            return rows

        try:
            live_rows = self._live_probe_rows()
        except Exception:
            live_rows = []
        artifact_rows = gui_evidence_pack_rows(
            run_id=run_id,
            stage=stage,
            base_dir="evidence",
            evidence_path=recorder.path,
            route_decision_path=route_path,
        )
        rows = operator_home_rows(
            run_id=run_id,
            stage=stage,
            device_ids=self._selected_device_ids(),
            source_rows=context_rows("_xp_public_source_ledger_context"),
            industry_rows=context_rows("_industry_sop_radar_context"),
            roadmap_rows=context_rows("_xp_roadmap_context"),
            local_rows=context_rows("_local_verification_context"),
            core_rows=context_rows("_xp_core_function_matrix_context"),
            script_coverage_rows=context_rows("_script_coverage_board_context"),
            proof_map_rows=context_rows("_acceptance_proof_map_context"),
            claim_scope_rows_data=context_rows("_claim_scope_context"),
            event_contract_rows=context_rows("_xp_event_error_contract_context"),
            route_matrix_rows=context_rows("_mainstream_route_matrix_context"),
            goal_rows=context_rows("_gui_goal_gate_context"),
            pitfall_rows=context_rows("_pitfall_library_context"),
            kit_gate_rows=context_rows("_field_kit_gate_context"),
            ios_sop_rows=context_rows("_ios_field_sop_context"),
            bench_rows=context_rows("_hardware_bench_context"),
            wizard_rows=context_rows("_field_evidence_wizard_context"),
            live_probe_rows_data=live_rows,
            artifact_rows=artifact_rows,
            route_report=route_report,
            doctor_report=self._probe_report("doctor"),
            scenario_summary=self._probe_report("scenario"),
            acceptance_report=acceptance_report,
            readiness_report=readiness_report,
            evidence_exists=evidence_exists,
            evidence_summary=evidence_summary,
            command_queue_items=self.command_queue_items,
        )
        return rows, readiness_report

    def show_operator_home_from_gui(self) -> None:
        stage = self.field_stage.get().strip().lower() or "p1"
        try:
            rows, _readiness_report = self._operator_home_context()
        except Exception as exc:
            messagebox.showerror("iMouse", f"Operator home 失败: {exc}")
            return

        dialog = tk.Toplevel(self)
        dialog.title(f"Operator Home {stage.upper()}")
        dialog.geometry("1580x600")
        dialog.minsize(1120, 420)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)

        status_var = tk.StringVar(value=operator_home_brief(rows, stage=stage))
        ttk.Label(dialog, textvariable=status_var, padding=(10, 8)).grid(row=0, column=0, sticky="ew")

        columns = ("step", "phase", "status", "current", "next", "action", "support", "artifact", "stop")
        tree = ttk.Treeview(dialog, columns=columns, show="headings", height=11)
        for column, label, width in (
            ("step", "#", 42),
            ("phase", "Phase", 210),
            ("status", "Status", 80),
            ("current", "Current", 330),
            ("next", "Next action", 360),
            ("action", "Primary GUI", 150),
            ("support", "Supporting GUI", 250),
            ("artifact", "Artifact", 330),
            ("stop", "Stop rule", 370),
        ):
            tree.heading(column, text=label)
            tree.column(column, width=width, anchor="w")
        tree.grid(row=1, column=0, sticky="nsew", padx=10)
        scroll = ttk.Scrollbar(dialog, orient="vertical", command=tree.yview)
        scroll.grid(row=1, column=1, sticky="ns")
        tree.configure(yscrollcommand=scroll.set)

        footer = ttk.Frame(dialog, padding=(10, 8))
        footer.grid(row=2, column=0, columnspan=2, sticky="ew")
        row_by_item: dict[str, dict[str, str]] = {}

        def render(next_rows: list[dict[str, str]]) -> None:
            tree.delete(*tree.get_children())
            row_by_item.clear()
            for row in next_rows:
                item_id = tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("step", ""),
                        row.get("phase", ""),
                        row.get("status", ""),
                        row.get("current", ""),
                        row.get("next_action", ""),
                        row.get("gui_action", ""),
                        row.get("supporting_actions", ""),
                        row.get("artifact", ""),
                        row.get("stop_rule", ""),
                    ),
                )
                row_by_item[item_id] = row
            status_var.set(operator_home_brief(next_rows, stage=stage))

        def refresh() -> None:
            try:
                refreshed, _readiness = self._operator_home_context()
            except Exception as exc:
                status_var.set(f"Operator home refresh 失败: {exc}")
                self._log(f"Operator home refresh 失败: {exc}")
                return
            render(refreshed)
            self._log(operator_home_brief(refreshed, stage=stage))

        def run_selected() -> None:
            selection = tree.selection()
            if not selection:
                messagebox.showwarning("iMouse", "Select one home row first.")
                return
            row = row_by_item.get(selection[0], {})
            method_name = str(row.get("method", "") or "")
            method = getattr(self, method_name, None)
            if not callable(method):
                messagebox.showerror("iMouse", f"Home action is not available: {method_name}")
                return
            self._log(f"Home action {row.get('phase', '')}: {row.get('gui_action', '')}")
            method()

        ttk.Button(footer, text="Run Selected", command=run_selected).pack(side="left")
        ttk.Button(footer, text="刷新", command=refresh).pack(side="left", padx=4)
        ttk.Button(footer, text="导出", command=self.write_operator_home_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Start Pack", command=self.show_first_run_packet_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Proof Map", command=self.show_acceptance_proof_map_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Claim Scope", command=self.show_claim_scope_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Center", command=self.show_gui_control_center_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Wizard", command=self.show_field_evidence_wizard_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="P1 Trial", command=self.show_p1_trial_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Events", command=self.show_xp_event_error_contract_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Pack", command=self.write_evidence_pack_from_gui).pack(side="left", padx=4)
        ttk.Button(footer, text="Readiness", command=self.run_readiness_audit).pack(side="left", padx=4)
        ttk.Label(
            footer,
            text="Home is the operator workflow map; only JSONL evidence and stage gates can support control claims.",
        ).pack(side="left", padx=(12, 0))
        render(rows)

