    def browse_route_decision(self) -> None:
        path = filedialog.askopenfilename(
            title="Select route decision JSON",
            initialdir="evidence",
            filetypes=(("Route decision JSON", "*.json"), ("All files", "*.*")),
        )
        if not path:
            return
        self.route_decision_path.set(path)
        try:
            data = load_decision(path)
        except Exception as exc:
            self._log(f"Selected route decision file but could not read run_id: {exc}")
            return
        run_id = str(data.get("run_id", "") or "").strip()
        if run_id:
            self.evidence_run_id.set(run_id)
            self._log(f"Loaded route decision path for run_id={run_id}: {path}")

    def edit_route_decision_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        try:
            if not path.exists():
                write_decision_template(path, run_id=run_id, devices=self._selected_device_ids())
            data = load_decision(path)
        except Exception as exc:
            messagebox.showerror("iMouse", f"Route decision editor 失败: {exc}")
            return

        self.route_decision_path.set(str(path))
        form_values = route_decision_form_values(data)
        dialog = tk.Toplevel(self)
        dialog.title("Route Decision Editor")
        dialog.geometry("860x680")
        dialog.minsize(760, 540)
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(1, weight=1)
        style = ttk.Style(dialog)
        style.configure("Issue.TEntry", fieldbackground="#fff4f2")
        style.configure("Issue.TCombobox", fieldbackground="#fff4f2")

        header = ttk.Frame(dialog, padding=(10, 8))
        header.grid(row=0, column=0, sticky="ew")
        header.columnconfigure(1, weight=1)
        ttk.Label(header, text="File").grid(row=0, column=0, sticky="w")
        ttk.Label(header, text=str(path)).grid(row=0, column=1, sticky="w", padx=(6, 0))
        ttk.Label(header, text="Run ID").grid(row=1, column=0, sticky="w", pady=(4, 0))
        ttk.Label(header, text=str(data.get("run_id", run_id))).grid(row=1, column=1, sticky="w", padx=(6, 0), pady=(4, 0))

        body = ttk.Frame(dialog, padding=(10, 0, 10, 8))
        body.grid(row=1, column=0, sticky="nsew")
        body.rowconfigure(0, weight=1)
        body.columnconfigure(0, weight=1)

        canvas = tk.Canvas(body, highlightthickness=0)
        scrollbar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas)
        inner.columnconfigure(1, weight=1)
        window_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")

        def on_inner_configure(_event: object) -> None:
            canvas.configure(scrollregion=canvas.bbox("all"))

        def on_canvas_configure(event: tk.Event) -> None:
            canvas.itemconfigure(window_id, width=event.width)

        inner.bind("<Configure>", on_inner_configure)
        canvas.bind("<Configure>", on_canvas_configure)

        variables: dict[str, tk.StringVar] = {}
        issue_variables: dict[str, tk.StringVar] = {}
        issue_widgets: dict[str, ttk.Widget] = {}
        for row, (field_path, label, options) in enumerate(ROUTE_DECISION_FORM_FIELDS):
            variable = tk.StringVar(value=form_values.get(field_path, ""))
            variables[field_path] = variable
            issue_variable = tk.StringVar(value="")
            issue_variables[field_path] = issue_variable
            ttk.Label(inner, text=label).grid(row=row, column=0, sticky="w", padx=(0, 8), pady=3)
            if options:
                widget = ttk.Combobox(inner, textvariable=variable, values=options, state="normal")
            else:
                widget = ttk.Entry(inner, textvariable=variable)
            issue_widgets[field_path] = widget
            widget.grid(row=row, column=1, sticky="ew", pady=3)
            ttk.Label(inner, text=field_path).grid(row=row, column=2, sticky="w", padx=(8, 0), pady=3)
            ttk.Label(inner, textvariable=issue_variable, foreground="#b42318").grid(
                row=row, column=3, sticky="w", padx=(8, 0), pady=3
            )

        footer = ttk.Frame(dialog, padding=(10, 0, 10, 10))
        footer.grid(row=2, column=0, sticky="ew")
        footer.columnconfigure(0, weight=1)

        def draft_data() -> dict:
            current = json.loads(json.dumps(data, ensure_ascii=False))
            values = {field_path: variable.get() for field_path, variable in variables.items()}
            return apply_route_decision_form_values(current, values)

        def refresh_issues() -> None:
            issues = route_decision_form_issues(draft_data())
            for field_path, issue_variable in issue_variables.items():
                issue = issues.get(field_path, "")
                issue_variable.set(issue)
                widget = issue_widgets.get(field_path)
                if widget is not None:
                    try:
                        if isinstance(widget, ttk.Combobox):
                            widget.configure(style="Issue.TCombobox" if issue else "TCombobox")
                        else:
                            widget.configure(style="Issue.TEntry" if issue else "TEntry")
                    except tk.TclError:
                        pass

        def use_metadata() -> None:
            device_ids = self._selected_device_ids()
            primary_device = device_ids[0] if device_ids else ""
            try:
                serial_port = self._metadata_serial_port(primary_device) if primary_device else self.hardware_port.get().strip()
            except Exception:
                serial_port = self.hardware_port.get().strip()
            values = route_decision_metadata_prefill_values(
                device_ids=device_ids,
                receiver_provider=self.metadata_receiver_provider.get(),
                capture_method=self.metadata_capture_method.get(),
                hid_provider=self.metadata_hid_provider.get(),
                hid_id=self.metadata_hid_id.get(),
                serial_port=serial_port,
                iphone_id=self.metadata_iphone_id.get(),
                ios_version=self.metadata_ios_version.get(),
                receiver_name=self.metadata_receiver_name.get(),
                receiver_version=self.metadata_receiver_version.get(),
            )
            for field_path, value in values.items():
                if field_path in variables:
                    variables[field_path].set(value)
            self._log(f"Route decision form filled from current Metadata: {sorted(values)}")
            refresh_issues()

        def save() -> bool:
            try:
                current = load_decision(path) if path.exists() else data
                values = {field_path: variable.get() for field_path, variable in variables.items()}
                updated = apply_route_decision_form_values(current, values)
                if not str(updated.get("run_id", "")).strip():
                    updated["run_id"] = run_id
                if not str(updated.get("target_stage", "")).strip():
                    updated["target_stage"] = "p1"
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(
                    json.dumps(updated, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
            except Exception as exc:
                messagebox.showerror("iMouse", f"Route decision save 失败: {exc}")
                return False
            self.route_decision_path.set(str(path))
            saved_run_id = str(updated.get("run_id", "") or "").strip()
            if saved_run_id:
                self.evidence_run_id.set(saved_run_id)
            self._log(f"Saved route decision form: {path}")
            refresh_issues()
            return True

        def save_and_close() -> None:
            if save():
                dialog.destroy()

        def save_and_validate() -> None:
            if save():
                self.validate_route_decision_from_gui()

        ttk.Label(
            footer,
            text="Blank Open blockers means none. Validate only after every placeholder is replaced by real bench values.",
        ).grid(row=0, column=0, sticky="w")
        ttk.Button(footer, text="Use Metadata", command=use_metadata).grid(row=0, column=1, padx=(8, 0), sticky="e")
        ttk.Button(footer, text="Scan Issues", command=refresh_issues).grid(row=0, column=2, padx=(8, 0), sticky="e")
        ttk.Button(footer, text="保存", command=save).grid(row=0, column=3, padx=(8, 0), sticky="e")
        ttk.Button(footer, text="Save + Validate", command=save_and_validate).grid(
            row=0, column=4, padx=(8, 0), sticky="e"
        )
        ttk.Button(footer, text="关闭", command=save_and_close).grid(row=0, column=5, padx=(8, 0), sticky="e")
        refresh_issues()

    def write_route_issue_checklist_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        if not path.exists():
            messagebox.showwarning("iMouse", f"Route decision JSON does not exist:\n{path}")
            return
        try:
            data = load_decision(path)
            decision_run_id = str(data.get("run_id", "") or "").strip()
            if decision_run_id:
                self.evidence_run_id.set(decision_run_id)
                run_id = decision_run_id
            out_path = write_route_decision_issue_markdown(data, self.route_issue_checklist_file(run_id))
        except Exception as exc:
            messagebox.showerror("iMouse", f"Route checklist 失败: {exc}")
            return
        line = route_decision_issue_brief(data)
        self._log(f"{line}; artifact={out_path}")
        messagebox.showinfo(
            "iMouse",
            f"{line}\n{out_path}\n\n"
            "This checklist does not record evidence and does not prove real iOS control.",
        )

    def validate_route_decision_from_gui(self) -> None:
        run_id = self._ensure_evidence_run_id()
        path = Path(self.route_decision_path.get().strip() or self.route_decision_file(run_id))
        if not path.exists():
            messagebox.showwarning("iMouse", f"Route decision JSON does not exist:\n{path}")
            return
        try:
            data = load_decision(path)
            decision_run_id = str(data.get("run_id", "") or "").strip()
            if decision_run_id:
                self.evidence_run_id.set(decision_run_id)
                run_id = decision_run_id
            report = evaluate_decision(data, require_ready=True)
            markdown_path = write_decision_markdown(report, path.with_suffix(".md"))
            evidence_path = ValidationRecorder(run_id).path
            append_decision_evidence(data, report, evidence_path)
        except Exception as exc:
            messagebox.showerror("iMouse", f"Route decision validation 失败: {exc}")
            return

        line = route_decision_brief(report)
        self._store_probe_report("route", report)
        self._log(f"{line}; artifact={markdown_path}; evidence={evidence_path}")
        self.refresh_live_probe_status()
        if report.get("ok"):
            messagebox.showinfo("iMouse", f"{line}\n{markdown_path}\n{evidence_path}")
        else:
            messagebox.showwarning(
                "iMouse",
                f"{line}\n{markdown_path}\n{evidence_path}\n\n"
                "A failed route decision was recorded; treat this run_id as blocked and use a fresh run_id after fixing blockers.",
            )

